import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useLanguage } from '../../contexts/UiContext';
import { toast } from 'react-toastify';
import axios from 'axios';

const AdminAssets = () => {
  const { language, theme } = useLanguage();
  const [assets, setAssets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState('');
  const [filterDepartment, setFilterDepartment] = useState('');
  const [filterCategory, setFilterCategory] = useState('');
  const [filterCondition, setFilterCondition] = useState('');
  const [sortBy, setSortBy] = useState('created_at');
  const [sortOrder, setSortOrder] = useState('desc');
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalItems, setTotalItems] = useState(0);
  const [selectedAssets, setSelectedAssets] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [categories, setCategories] = useState([]);
  const [showAssignModal, setShowAssignModal] = useState(false);
  const [showTransferModal, setShowTransferModal] = useState(false);
  const [showHistoryModal, setShowHistoryModal] = useState(false);
  const [selectedAsset, setSelectedAsset] = useState(null);
  const [assignData, setAssignData] = useState({
    department_id: '',
    user_id: '',
    location: '',
    reason: ''
  });
  const [transferData, setTransferData] = useState({
    department_id: '',
    location: '',
    reason: ''
  });
  const [historyData, setHistoryData] = useState([]);
  const [users, setUsers] = useState([]);

  const isDark = theme === 'dark';
  const t = language === 'en' ? englishTranslations : amharicTranslations;

  useEffect(() => {
    fetchAssets();
    fetchDepartments();
    fetchCategories();
    fetchUsers();
  }, [currentPage, filterStatus, filterDepartment, filterCategory, filterCondition, sortBy, sortOrder]);

  const fetchAssets = async () => {
    setLoading(true);
    try {
      const params = {
        page: currentPage,
        limit: 10,
        status: filterStatus || undefined,
        department_id: filterDepartment || undefined,
        category: filterCategory || undefined,
        condition: filterCondition || undefined,
        sort_by: sortBy,
        sort_order: sortOrder,
        search: search || undefined
      };
      const response = await axios.get('/api/assets', { params });
      setAssets(response.data.assets || []);
      setTotalPages(response.data.pagination?.pages || 1);
      setTotalItems(response.data.pagination?.total || 0);
    } catch (error) {
      toast.error('Failed to load assets');
    }
    setLoading(false);
  };

  const fetchDepartments = async () => {
    try {
      const response = await axios.get('/api/departments');
      setDepartments(response.data.departments || []);
    } catch (error) {
      console.error('Failed to load departments');
    }
  };

  const fetchCategories = async () => {
    try {
      const response = await axios.get('/api/categories');
      setCategories(response.data.categories || []);
    } catch (error) {
      console.error('Failed to load categories');
    }
  };

  const fetchUsers = async () => {
    try {
      const response = await axios.get('/api/users');
      setUsers(response.data.users || []);
    } catch (error) {
      console.error('Failed to load users');
    }
  };

  const fetchAssetHistory = async (assetId) => {
    try {
      const response = await axios.get(`/api/assignments/history/${assetId}`);
      setHistoryData(response.data.history || []);
      setShowHistoryModal(true);
    } catch (error) {
      toast.error('Failed to load asset history');
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm(t.confirmDelete)) return;
    try {
      await axios.delete(`/api/assets/${id}`);
      toast.success(t.assetDeleted);
      fetchAssets();
    } catch (error) {
      toast.error(t.deleteFailed);
    }
  };

  const handleBulkDelete = async () => {
    if (selectedAssets.length === 0) return;
    if (!window.confirm(t.confirmBulkDelete.replace('{count}', selectedAssets.length))) return;
    try {
      await Promise.all(selectedAssets.map(id => axios.delete(`/api/assets/${id}`)));
      toast.success(t.bulkDeleteSuccess.replace('{count}', selectedAssets.length));
      setSelectedAssets([]);
      fetchAssets();
    } catch (error) {
      toast.error(t.deleteFailed);
    }
  };

  const handleAssign = async () => {
    try {
      await axios.post('/api/assignments', { asset_id: selectedAsset.id, assigned_to: assignData.user_id, notes: assignData.reason });
      toast.success(t.assignSuccess);
      setShowAssignModal(false);
      setAssignData({ department_id: '', user_id: '', location: '', reason: '' });
      fetchAssets();
    } catch (error) {
      toast.error(t.assignFailed);
    }
  };

  const handleTransfer = async () => {
    try {
      await axios.post(`/api/assignments/${selectedAsset.id}/transfer`, { new_user_id: transferData.user_id, notes: transferData.reason });
      toast.success(t.transferSuccess);
      setShowTransferModal(false);
      setTransferData({ department_id: '', location: '', reason: '' });
      fetchAssets();
    } catch (error) {
      toast.error(t.transferFailed);
    }
  };

  const handleGenerateQR = async (assetId) => {
    try {
      const response = await axios.get(`/api/assets/${assetId}/qr`);
      window.open(response.data.qr_url, '_blank');
      toast.success(t.qrGenerated);
    } catch (error) {
      toast.error(t.qrFailed);
    }
  };

  const getStatusColor = (status) => {
    const colors = {
      'Active': '#48bb78',
      'In-Use': '#48bb78',
      'Available': '#4299e1',
      'Under-Maintenance': '#ed8936',
      'Maintenance': '#ed8936',
      'Disposed': '#fc8181',
      'Lost': '#fc8181',
      'Reserved': '#805ad5',
      'Pending': '#f6ad55'
    };
    return colors[status] || '#a0aec0';
  };

  const getConditionColor = (condition) => {
    const colors = {
      'Excellent': '#48bb78',
      'Good': '#4299e1',
      'Fair': '#ed8936',
      'Poor': '#fc8181',
      'Damaged': '#fc8181'
    };
    return colors[condition] || '#a0aec0';
  };

  const getHistoryIcon = (type) => {
    const icons = {
      'created': '➕',
      'assigned': '📋',
      'transferred': '🔄',
      'maintained': '🔧',
      'returned': '↩️',
      'disposed': '🗑️',
      'updated': '✏️'
    };
    return icons[type] || '📌';
  };

  const resetFilters = () => {
    setSearch('');
    setFilterStatus('');
    setFilterDepartment('');
    setFilterCategory('');
    setFilterCondition('');
    setSortBy('created_at');
    setSortOrder('desc');
    setCurrentPage(1);
  };

  const styles = {
    container: { padding: '20px', maxWidth: '1400px', margin: '0 auto' },
    header: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      flexWrap: 'wrap',
      gap: '16px',
      marginBottom: '24px'
    },
    title: {
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '1.75rem',
      fontWeight: 700,
      margin: 0
    },
    subtitle: {
      color: isDark ? '#8896b0' : '#4a5568',
      fontSize: '0.9rem',
      margin: '4px 0 0 0'
    },
    controls: {
      display: 'flex',
      gap: '12px',
      flexWrap: 'wrap',
      alignItems: 'center',
      marginBottom: '16px',
      padding: '16px',
      background: isDark ? '#1a273a' : '#f7fafc',
      borderRadius: '12px',
      border: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`
    },
    input: {
      padding: '10px 16px',
      borderRadius: '8px',
      border: `1px solid ${isDark ? '#32465f' : '#d0d8e8'}`,
      background: isDark ? '#0d1b2a' : '#ffffff',
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.9rem',
      minWidth: '180px',
      flex: '1'
    },
    select: {
      padding: '10px 16px',
      borderRadius: '8px',
      border: `1px solid ${isDark ? '#32465f' : '#d0d8e8'}`,
      background: isDark ? '#0d1b2a' : '#ffffff',
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.9rem',
      cursor: 'pointer',
      minWidth: '140px'
    },
    button: (bg, hover) => ({
      padding: '10px 20px',
      background: bg || 'linear-gradient(135deg, #2b6cb0, #4299e1)',
      color: 'white',
      border: 'none',
      borderRadius: '8px',
      fontWeight: 600,
      cursor: 'pointer',
      fontSize: '0.9rem',
      transition: 'all 0.2s',
      whiteSpace: 'nowrap'
    }),
    table: {
      width: '100%',
      borderCollapse: 'collapse',
      background: isDark ? '#1e2d45' : '#ffffff',
      borderRadius: '12px',
      overflow: 'hidden',
      boxShadow: isDark ? '0 4px 12px rgba(0,0,0,0.3)' : '0 4px 12px rgba(0,0,100,0.06)'
    },
    th: {
      padding: '12px 16px',
      textAlign: 'left',
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontWeight: 600,
      borderBottom: `2px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      background: isDark ? '#141e2d' : '#f7fafc',
      fontSize: '0.85rem',
      whiteSpace: 'nowrap',
      cursor: 'pointer'
    },
    td: {
      padding: '12px 16px',
      borderBottom: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.9rem',
      verticalAlign: 'middle'
    },
    statusBadge: (status) => ({
      display: 'inline-block',
      padding: '4px 12px',
      borderRadius: '20px',
      fontSize: '0.75rem',
      fontWeight: 600,
      background: getStatusColor(status) + '20',
      color: getStatusColor(status)
    }),
    conditionBadge: (condition) => ({
      display: 'inline-block',
      padding: '4px 12px',
      borderRadius: '20px',
      fontSize: '0.75rem',
      fontWeight: 600,
      background: getConditionColor(condition) + '20',
      color: getConditionColor(condition)
    }),
    pagination: {
      display: 'flex',
      justifyContent: 'center',
      gap: '8px',
      marginTop: '20px',
      alignItems: 'center',
      flexWrap: 'wrap'
    },
    pageButton: (active) => ({
      padding: '8px 16px',
      borderRadius: '6px',
      border: `1px solid ${isDark ? '#32465f' : '#d0d8e8'}`,
      background: active ? (isDark ? '#2b6cb0' : '#2b6cb0') : (isDark ? '#0d1b2a' : '#ffffff'),
      color: active ? '#ffffff' : (isDark ? '#c8dcf5' : '#1a365d'),
      cursor: 'pointer',
      fontWeight: active ? 700 : 400,
      transition: 'all 0.2s'
    }),
    actionButton: (bg, color = 'white') => ({
      padding: '6px 10px',
      borderRadius: '6px',
      border: 'none',
      cursor: 'pointer',
      fontSize: '0.75rem',
      marginRight: '4px',
      background: bg,
      color: color,
      transition: 'all 0.2s'
    }),
    checkbox: { width: '18px', height: '18px', cursor: 'pointer' },
    emptyState: {
      textAlign: 'center',
      padding: '60px 20px',
      color: isDark ? '#8896b0' : '#4a5568',
      background: isDark ? '#1e2d45' : '#ffffff',
      borderRadius: '12px',
      border: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`
    },
    // Modal styles
    modalOverlay: {
      position: 'fixed',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      background: 'rgba(0,0,0,0.6)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      zIndex: 1000,
      padding: '20px'
    },
    modal: {
      background: isDark ? '#1e2d45' : '#ffffff',
      borderRadius: '16px',
      padding: '30px',
      maxWidth: '550px',
      width: '100%',
      maxHeight: '90vh',
      overflowY: 'auto',
      boxShadow: '0 20px 60px rgba(0,0,0,0.4)'
    },
    modalTitle: {
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '1.3rem',
      fontWeight: 700,
      marginBottom: '20px'
    },
    formGroup: { marginBottom: '16px' },
    label: {
      display: 'block',
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.85rem',
      fontWeight: 600,
      marginBottom: '4px'
    },
    formInput: {
      width: '100%',
      padding: '10px 14px',
      borderRadius: '8px',
      border: `1px solid ${isDark ? '#32465f' : '#d0d8e8'}`,
      background: isDark ? '#0d1b2a' : '#ffffff',
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.95rem'
    },
    modalActions: {
      display: 'flex',
      gap: '12px',
      justifyContent: 'flex-end',
      marginTop: '20px'
    },
    historyItem: {
      display: 'flex',
      alignItems: 'center',
      gap: '12px',
      padding: '10px 0',
      borderBottom: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`
    },
    historyIcon: { fontSize: '1.3rem' },
    historyContent: { flex: 1 },
    historyTitle: { color: isDark ? '#c8dcf5' : '#1a365d', fontSize: '0.9rem' },
    historyMeta: { color: isDark ? '#8896b0' : '#4a5568', fontSize: '0.75rem' },
    historyTimeline: {
      borderLeft: `2px solid ${isDark ? '#32465f' : '#d0d8e8'}`,
      paddingLeft: '16px',
      marginLeft: '8px'
    },
    chip: {
      display: 'inline-block',
      padding: '2px 10px',
      borderRadius: '12px',
      fontSize: '0.7rem',
      fontWeight: 600,
      background: isDark ? '#32465f' : '#e8edf5',
      color: isDark ? '#c8dcf5' : '#1a365d'
    },
    tooltip: {
      position: 'relative',
      cursor: 'help'
    }
  };

  if (loading && assets.length === 0) {
    return <div style={styles.emptyState}>⏳ {t.loading}</div>;
  }

  return (
    <div style={styles.container}>
      {/* Header */}
      <div style={styles.header}>
        <div>
          <h1 style={styles.title}>📦 {t.assets}</h1>
          <p style={styles.subtitle}>{t.totalAssetsCount.replace('{count}', totalItems)}</p>
        </div>
        <div style={{ display: 'flex', gap: '12px', flexWrap: 'wrap' }}>
          {selectedAssets.length > 0 && (
            <button style={styles.button('#e53e3e')} onClick={handleBulkDelete}>
              🗑️ {t.deleteSelected} ({selectedAssets.length})
            </button>
          )}
          <button style={styles.button('#805ad5')} onClick={resetFilters}>
            🔄 {t.resetFilters}
          </button>
          <Link to="/admin/assets/create">
            <button style={styles.button()}>➕ {t.createAsset}</button>
          </Link>
        </div>
      </div>

      {/* Controls */}
      <div style={styles.controls}>
        <input
          type="text"
          style={styles.input}
          placeholder={t.searchPlaceholder}
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <select style={styles.select} value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)}>
          <option value="">{t.allStatus}</option>
          <option value="Active">{t.active}</option>
          <option value="In-Use">{t.inUse}</option>
          <option value="Available">{t.available}</option>
          <option value="Under-Maintenance">{t.underMaintenance}</option>
          <option value="Disposed">{t.disposed}</option>
          <option value="Lost">{t.lost}</option>
          <option value="Reserved">{t.reserved}</option>
        </select>
        <select style={styles.select} value={filterDepartment} onChange={(e) => setFilterDepartment(e.target.value)}>
          <option value="">{t.allDepartments}</option>
          {departments.map(dept => (
            <option key={dept.id} value={dept.id}>{dept.name}</option>
          ))}
        </select>
        <select style={styles.select} value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)}>
          <option value="">{t.allCategories}</option>
          {categories.map(cat => (
            <option key={cat.id} value={cat.name}>{cat.name}</option>
          ))}
        </select>
        <select style={styles.select} value={filterCondition} onChange={(e) => setFilterCondition(e.target.value)}>
          <option value="">{t.allConditions}</option>
          <option value="Excellent">{t.excellent}</option>
          <option value="Good">{t.good}</option>
          <option value="Fair">{t.fair}</option>
          <option value="Poor">{t.poor}</option>
          <option value="Damaged">{t.damaged}</option>
        </select>
        <select style={styles.select} value={sortBy} onChange={(e) => setSortBy(e.target.value)}>
          <option value="name">{t.sortByName}</option>
          <option value="created_at">{t.sortByDate}</option>
          <option value="current_value">{t.sortByValue}</option>
          <option value="status">{t.sortByStatus}</option>
        </select>
        <select style={styles.select} value={sortOrder} onChange={(e) => setSortOrder(e.target.value)}>
          <option value="asc">{t.ascending}</option>
          <option value="desc">{t.descending}</option>
        </select>
        <button style={styles.button('linear-gradient(135deg, #2b6cb0, #4299e1)')} onClick={fetchAssets}>
          🔍 {t.search}
        </button>
      </div>

      {/* Table */}
      {assets.length === 0 ? (
        <div style={styles.emptyState}>
          <div style={{ fontSize: '3rem', marginBottom: '12px' }}>📭</div>
          <p>{t.noAssets}</p>
          <Link to="/admin/assets/create">
            <button style={{ ...styles.button(), marginTop: '12px' }}>➕ {t.createFirstAsset}</button>
          </Link>
        </div>
      ) : (
        <>
          <div style={{ overflowX: 'auto' }}>
            <table style={styles.table}>
              <thead>
                <tr>
                  <th style={styles.th}>
                    <input
                      type="checkbox"
                      style={styles.checkbox}
                      onChange={(e) => {
                        if (e.target.checked) {
                          setSelectedAssets(assets.map(a => a.id));
                        } else {
                          setSelectedAssets([]);
                        }
                      }}
                    />
                  </th>
                  <th style={styles.th}>{t.assetTag}</th>
                  <th style={styles.th}>{t.name}</th>
                  <th style={styles.th}>{t.category}</th>
                  <th style={styles.th}>{t.department}</th>
                  <th style={styles.th}>{t.status}</th>
                  <th style={styles.th}>{t.condition}</th>
                  <th style={styles.th}>{t.location}</th>
                  <th style={styles.th}>{t.value}</th>
                  <th style={styles.th}>{t.assignedTo}</th>
                  <th style={styles.th}>{t.actions}</th>
                </tr>
              </thead>
              <tbody>
                {assets.map((asset) => (
                  <tr key={asset.id}>
                    <td style={styles.td}>
                      <input
                        type="checkbox"
                        style={styles.checkbox}
                        checked={selectedAssets.includes(asset.id)}
                        onChange={(e) => {
                          if (e.target.checked) {
                            setSelectedAssets([...selectedAssets, asset.id]);
                          } else {
                            setSelectedAssets(selectedAssets.filter(id => id !== asset.id));
                          }
                        }}
                      />
                    </td>
                    <td style={styles.td}>
                      <Link to={`/assets/${asset.id}`} style={{ color: '#2b6cb0', textDecoration: 'none', fontWeight: 600 }}>
                        {asset.asset_tag || asset.id}
                      </Link>
                    </td>
                    <td style={styles.td}>
                      <div style={{ fontWeight: 500 }}>{asset.name}</div>
                      <div style={{ fontSize: '0.7rem', color: isDark ? '#8896b0' : '#4a5568' }}>
                        {asset.model || asset.serial_number || ''}
                      </div>
                    </td>
                    <td style={styles.td}>{asset.category || '-'}</td>
                    <td style={styles.td}>{asset.department_name || '-'}</td>
                    <td style={styles.td}>
                      <span style={styles.statusBadge(asset.status)}>{asset.status}</span>
                    </td>
                    <td style={styles.td}>
                      <span style={styles.conditionBadge(asset.condition)}>{asset.condition || '-'}</span>
                    </td>
                    <td style={styles.td}>{asset.location || '-'}</td>
                    <td style={styles.td}>${(asset.current_value || 0).toLocaleString()}</td>
                    <td style={styles.td}>{asset.assigned_to_name || '-'}</td>
                    <td style={styles.td}>
                      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '2px' }}>
                        <Link to={`/assets/${asset.id}`}>
                          <button style={styles.actionButton('#4299e1')} title={t.view}>👁️</button>
                        </Link>
                        <Link to={`/assets/${asset.id}/edit`}>
                          <button style={styles.actionButton('#ed8936')} title={t.edit}>✏️</button>
                        </Link>
                        <button
                          style={styles.actionButton('#48bb78')}
                          title={t.assign}
                          onClick={() => {
                            setSelectedAsset(asset);
                            setShowAssignModal(true);
                          }}
                        >
                          📋
                        </button>
                        <button
                          style={styles.actionButton('#805ad5')}
                          title={t.transfer}
                          onClick={() => {
                            setSelectedAsset(asset);
                            setShowTransferModal(true);
                          }}
                        >
                          🔄
                        </button>
                        <button
                          style={styles.actionButton('#9f7aea')}
                          title={t.qrCode}
                          onClick={() => handleGenerateQR(asset.id)}
                        >
                          📱
                        </button>
                        <button
                          style={styles.actionButton('#3182ce')}
                          title={t.history}
                          onClick={() => fetchAssetHistory(asset.id)}
                        >
                          📜
                        </button>
                        <button
                          style={styles.actionButton('#e53e3e')}
                          title={t.delete}
                          onClick={() => handleDelete(asset.id)}
                        >
                          🗑️
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* Pagination */}
          {totalPages > 1 && (
            <div style={styles.pagination}>
              <span style={{ color: isDark ? '#8896b0' : '#4a5568' }}>
                {t.showing} {assets.length} {t.of} {totalItems}
              </span>
              <button
                style={styles.pageButton(false)}
                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                disabled={currentPage === 1}
              >
                {t.previous}
              </button>
              {Array.from({ length: Math.min(totalPages, 7) }, (_, i) => {
                let page;
                if (totalPages <= 7) page = i + 1;
                else if (currentPage <= 4) page = i + 1;
                else if (currentPage >= totalPages - 3) page = totalPages - 6 + i;
                else page = currentPage - 3 + i;
                return (
                  <button
                    key={page}
                    style={styles.pageButton(page === currentPage)}
                    onClick={() => setCurrentPage(page)}
                  >
                    {page}
                  </button>
                );
              })}
              <button
                style={styles.pageButton(false)}
                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                disabled={currentPage === totalPages}
              >
                {t.next}
              </button>
            </div>
          )}
        </>
      )}

      {/* Assign Modal */}
      {showAssignModal && selectedAsset && (
        <div style={styles.modalOverlay} onClick={() => setShowAssignModal(false)}>
          <div style={styles.modal} onClick={(e) => e.stopPropagation()}>
            <h2 style={styles.modalTitle}>📋 {t.assignAsset} - {selectedAsset.name}</h2>
            <div style={styles.formGroup}>
              <label style={styles.label}>{t.department}</label>
              <select
                style={styles.formInput}
                value={assignData.department_id}
                onChange={(e) => setAssignData({ ...assignData, department_id: e.target.value })}
              >
                <option value="">{t.selectDepartment}</option>
                {departments.map(dept => (
                  <option key={dept.id} value={dept.id}>{dept.name}</option>
                ))}
              </select>
            </div>
            <div style={styles.formGroup}>
              <label style={styles.label}>{t.assignTo}</label>
              <select
                style={styles.formInput}
                value={assignData.user_id}
                onChange={(e) => setAssignData({ ...assignData, user_id: e.target.value })}
              >
                <option value="">{t.selectUser}</option>
                {users.map(user => (
                  <option key={user.id} value={user.id}>{user.full_name || user.username}</option>
                ))}
              </select>
            </div>
            <div style={styles.formGroup}>
              <label style={styles.label}>{t.location}</label>
              <input
                style={styles.formInput}
                placeholder={t.enterLocation}
                value={assignData.location}
                onChange={(e) => setAssignData({ ...assignData, location: e.target.value })}
              />
            </div>
            <div style={styles.formGroup}>
              <label style={styles.label}>{t.reason}</label>
              <input
                style={styles.formInput}
                placeholder={t.enterReason}
                value={assignData.reason}
                onChange={(e) => setAssignData({ ...assignData, reason: e.target.value })}
              />
            </div>
            <div style={styles.modalActions}>
              <button style={styles.button('#a0aec0')} onClick={() => setShowAssignModal(false)}>
                {t.cancel}
              </button>
              <button style={styles.button('#48bb78')} onClick={handleAssign}>
                {t.confirmAssign}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Transfer Modal */}
      {showTransferModal && selectedAsset && (
        <div style={styles.modalOverlay} onClick={() => setShowTransferModal(false)}>
          <div style={styles.modal} onClick={(e) => e.stopPropagation()}>
            <h2 style={styles.modalTitle}>🔄 {t.transferAsset} - {selectedAsset.name}</h2>
            <div style={styles.formGroup}>
              <label style={styles.label}>{t.currentDepartment}</label>
              <input style={styles.formInput} value={selectedAsset.department_name || '-'} disabled />
            </div>
            <div style={styles.formGroup}>
              <label style={styles.label}>{t.newDepartment}</label>
              <select
                style={styles.formInput}
                value={transferData.department_id}
                onChange={(e) => setTransferData({ ...transferData, department_id: e.target.value })}
              >
                <option value="">{t.selectDepartment}</option>
                {departments.map(dept => (
                  <option key={dept.id} value={dept.id}>{dept.name}</option>
                ))}
              </select>
            </div>
            <div style={styles.formGroup}>
              <label style={styles.label}>{t.newLocation}</label>
              <input
                style={styles.formInput}
                placeholder={t.enterNewLocation}
                value={transferData.location}
                onChange={(e) => setTransferData({ ...transferData, location: e.target.value })}
              />
            </div>
            <div style={styles.formGroup}>
              <label style={styles.label}>{t.reason}</label>
              <input
                style={styles.formInput}
                placeholder={t.enterReason}
                value={transferData.reason}
                onChange={(e) => setTransferData({ ...transferData, reason: e.target.value })}
              />
            </div>
            <div style={styles.modalActions}>
              <button style={styles.button('#a0aec0')} onClick={() => setShowTransferModal(false)}>
                {t.cancel}
              </button>
              <button style={styles.button('#805ad5')} onClick={handleTransfer}>
                {t.confirmTransfer}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* History Modal */}
      {showHistoryModal && (
        <div style={styles.modalOverlay} onClick={() => setShowHistoryModal(false)}>
          <div style={{ ...styles.modal, maxWidth: '600px' }} onClick={(e) => e.stopPropagation()}>
            <h2 style={styles.modalTitle}>📜 {t.assetHistory} - {selectedAsset?.name}</h2>
            {historyData.length === 0 ? (
              <p style={{ color: isDark ? '#8896b0' : '#4a5568' }}>{t.noHistory}</p>
            ) : (
              <div style={styles.historyTimeline}>
                {historyData.map((item, index) => (
                  <div key={index} style={styles.historyItem}>
                    <span style={styles.historyIcon}>{getHistoryIcon(item.type)}</span>
                    <div style={styles.historyContent}>
                      <div style={styles.historyTitle}>
                        {item.description || item.type}
                        {item.details && (
                          <span style={{ ...styles.chip, marginLeft: '8px' }}>
                            {item.details}
                          </span>
                        )}
                      </div>
                      <div style={styles.historyMeta}>
                        {item.user_name || 'System'} • {new Date(item.created_at).toLocaleString()}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
            <div style={styles.modalActions}>
              <button style={styles.button('#a0aec0')} onClick={() => setShowHistoryModal(false)}>
                {t.close}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

