import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useLanguage } from '../../contexts/UiContext';
import { toast } from 'react-toastify';
import axios from 'axios';

const AdminAssignment = () => {
  const { user } = useAuth();
  const { language, theme } = useLanguage();
  const [assignments, setAssignments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [editingId, setEditingId] = useState(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage] = useState(10);

  const isDark = theme === 'dark';

  const [formData, setFormData] = useState({
    assetId: '',
    assignedTo: '',
    department: '',
    location: '',
    assignmentDate: new Date().toISOString().split('T')[0],
    expectedReturnDate: '',
    notes: '',
    status: 'Pending'
  });

  const [assets, setAssets] = useState([]);
  const [users, setUsers] = useState([]);
  const [departments, setDepartments] = useState([]);

  const themeStyles = {
    light: {
      bg: '#f0f5ff',
      card: '#ffffff',
      text: '#1a375d',
      subText: '#4a5568',
      border: '#b4d2f0',
      hover: '#e0e7ff',
      accent: '#2b6cb0',
      danger: '#e53e3e',
      success: '#48bb78',
      warning: '#ed8936',
      shadow: '0 4px 12px rgba(0, 0, 100, 0.1)'
    },
    dark: {
      bg: '#141e2d',
      card: '#1e2d45',
      text: '#c8dcf5',
      subText: '#a0aec0',
      border: '#32465f',
      hover: '#334155',
      accent: '#63b3ed',
      danger: '#fc8181',
      success: '#48bb78',
      warning: '#ed8936',
      shadow: '0 4px 12px rgba(0, 0, 0, 0.3)'
    }
  };

  const styles = themeStyles[theme];

  useEffect(() => {
    fetchAssignments();
    fetchAssets();
    fetchUsers();
    fetchDepartments();
  }, []);

  const fetchAssignments = async () => {
    setLoading(true);
    try {
      const response = await axios.get('/api/assignments');
      setAssignments(response.data?.assignments || response.data?.data || response.data || []);
    } catch (error) {
      console.error('Error fetching assignments:', error);
      toast.error('Failed to load assignments');
    } finally {
      setLoading(false);
    }
  };

  const fetchAssets = async () => {
    try {
      const response = await axios.get('/api/assets');
      setAssets(response.data?.data || response.data || []);
    } catch (error) {
      console.error('Error fetching assets:', error);
    }
  };

  const fetchUsers = async () => {
    try {
      const response = await axios.get('/api/users');
      setUsers(response.data?.data || response.data || []);
    } catch (error) {
      console.error('Error fetching users:', error);
    }
  };

  const fetchDepartments = async () => {
    try {
      const response = await axios.get('/api/departments');
      setDepartments(response.data?.data || response.data?.departments || response.data || []);
    } catch (error) {
      console.error('Error fetching departments:', error);
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editingId) {
        await axios.put(`/api/assignments/${editingId}`, formData);
        toast.success('Assignment updated successfully');
      } else {
        await axios.post('/api/assignments', formData);
        toast.success('Assignment created successfully');
      }
      fetchAssignments();
      setFormData({
        assetId: '',
        assignedTo: '',
        department: '',
        location: '',
        assignmentDate: new Date().toISOString().split('T')[0],
        expectedReturnDate: '',
        notes: '',
        status: 'Pending'
      });
      setShowForm(false);
      setEditingId(null);
    } catch (error) {
      toast.error('Error saving assignment');
    }
  };

  const handleApprove = async (id) => {
    try {
      await axios.patch(`/api/assignments/${id}`, { status: 'Approved' });
      toast.success('Assignment approved');
      fetchAssignments();
    } catch (error) {
      toast.error('Error approving assignment');
    }
  };

  const handleReject = async (id) => {
    try {
      await axios.patch(`/api/assignments/${id}`, { status: 'Rejected' });
      toast.success('Assignment rejected');
      fetchAssignments();
    } catch (error) {
      toast.error('Error rejecting assignment');
    }
  };

  const handleReturnAsset = async (id) => {
    try {
      await axios.patch(`/api/assignments/${id}`, { status: 'Returned' });
      toast.success('Asset returned successfully');
      fetchAssignments();
    } catch (error) {
      toast.error('Error returning asset');
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this assignment?')) {
      try {
        await axios.delete(`/api/assignments/${id}`);
        toast.success('Assignment deleted');
        fetchAssignments();
      } catch (error) {
        toast.error('Error deleting assignment');
      }
    }
  };

  const handleEdit = (assignment) => {
    setFormData(assignment);
    setEditingId(assignment.id);
    setShowForm(true);
  };

  const filteredAssignments = assignments.filter(assignment => {
    const matchesSearch = 
      (assignment.asset?.name?.toLowerCase().includes(searchQuery.toLowerCase())) ||
      (assignment.assignedToUser?.username?.toLowerCase().includes(searchQuery.toLowerCase())) ||
      (assignment.department?.toLowerCase().includes(searchQuery.toLowerCase()));
    
    const matchesFilter = filterStatus === 'all' || assignment.status === filterStatus;
    return matchesSearch && matchesFilter;
  });

  const paginatedAssignments = filteredAssignments.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  const totalPages = Math.ceil(filteredAssignments.length / itemsPerPage);

  return (
    <div style={{ padding: '20px', backgroundColor: styles.bg, minHeight: '100vh' }}>
      <div style={{
        backgroundColor: styles.card,
        borderRadius: '12px',
        padding: '24px',
        boxShadow: styles.shadow,
        marginBottom: '20px'
      }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
          <h1 style={{ color: styles.text, margin: 0 }}>📋 Asset Assignment Management</h1>
          <button
            onClick={() => {
              setShowForm(!showForm);
              setEditingId(null);
              setFormData({
                assetId: '',
                assignedTo: '',
                department: '',
                location: '',
                assignmentDate: new Date().toISOString().split('T')[0],
                expectedReturnDate: '',
                notes: '',
                status: 'Pending'
              });
            }}
            style={{
              padding: '10px 16px',
              backgroundColor: styles.accent,
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              cursor: 'pointer',
              fontWeight: 600
            }}
          >
            {showForm ? '✕ Close' : '➕ New Assignment'}
          </button>
        </div>

        {/* Search and Filter */}
        <div style={{ display: 'flex', gap: '12px', marginBottom: '20px', flexWrap: 'wrap' }}>
          <input
            type="text"
            placeholder="Search by asset, user, or department..."
            value={searchQuery}
            onChange={(e) => {
              setSearchQuery(e.target.value);
              setCurrentPage(1);
            }}
            style={{
              flex: 1,
              minWidth: '200px',
              padding: '10px 12px',
              backgroundColor: isDark ? '#0d1b2a' : '#f8f9fa',
              border: `1px solid ${styles.border}`,
              borderRadius: '6px',
              color: styles.text
            }}
          />
          <select
            value={filterStatus}
            onChange={(e) => {
              setFilterStatus(e.target.value);
              setCurrentPage(1);
            }}
            style={{
              padding: '10px 12px',
              backgroundColor: isDark ? '#0d1b2a' : '#f8f9fa',
              border: `1px solid ${styles.border}`,
              borderRadius: '6px',
              color: styles.text,
              cursor: 'pointer'
            }}
          >
            <option value="all">All Status</option>
            <option value="Pending">Pending</option>
            <option value="Approved">Approved</option>
            <option value="Rejected">Rejected</option>
            <option value="Active">Active</option>
            <option value="Returned">Returned</option>
          </select>
        </div>

        {/* Form */}
        {showForm && (
          <form onSubmit={handleSubmit} style={{
            backgroundColor: isDark ? '#0d1b2a' : '#f8f9fa',
            padding: '20px',
            borderRadius: '8px',
            marginBottom: '20px',
            border: `1px solid ${styles.border}`
          }}>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '15px', marginBottom: '15px' }}>
              <div>
                <label style={{ color: styles.text, fontWeight: 600, marginBottom: '5px', display: 'block' }}>Asset *</label>
                <select
                  name="assetId"
                  value={formData.assetId}
                  onChange={handleInputChange}
                  required
                  style={{
                    width: '100%',
                    padding: '10px',
                    backgroundColor: styles.card,
                    color: styles.text,
                    border: `1px solid ${styles.border}`,
                    borderRadius: '6px',
                    cursor: 'pointer'
                  }}
                >
                  <option value="">Select Asset</option>
                  {assets.map(asset => (
                    <option key={asset.id} value={asset.id}>{asset.name} ({asset.code})</option>
                  ))}
                </select>
              </div>

              <div>
                <label style={{ color: styles.text, fontWeight: 600, marginBottom: '5px', display: 'block' }}>Assigned To *</label>
                <select
                  name="assignedTo"
                  value={formData.assignedTo}
                  onChange={handleInputChange}
                  required
                  style={{
                    width: '100%',
                    padding: '10px',
                    backgroundColor: styles.card,
                    color: styles.text,
                    border: `1px solid ${styles.border}`,
                    borderRadius: '6px',
                    cursor: 'pointer'
                  }}
                >
                  <option value="">Select User</option>
                  {users.map(u => (
                    <option key={u.id} value={u.id}>{u.username} ({u.email})</option>
                  ))}
                </select>
              </div>

              <div>
                <label style={{ color: styles.text, fontWeight: 600, marginBottom: '5px', display: 'block' }}>Department</label>
                <select
                  name="department"
                  value={formData.department}
                  onChange={handleInputChange}
                  style={{
                    width: '100%',
                    padding: '10px',
                    backgroundColor: styles.card,
                    color: styles.text,
                    border: `1px solid ${styles.border}`,
                    borderRadius: '6px',
                    cursor: 'pointer'
                  }}
                >
                  <option value="">Select Department</option>
                  {departments.map(dept => (
                    <option key={dept.id} value={dept.id}>{dept.name}</option>
                  ))}
                </select>
              </div>

              <div>
                <label style={{ color: styles.text, fontWeight: 600, marginBottom: '5px', display: 'block' }}>Location</label>
                <input
                  type="text"
                  name="location"
                  value={formData.location}
                  onChange={handleInputChange}
                  style={{
                    width: '100%',
                    padding: '10px',
                    backgroundColor: styles.card,
                    color: styles.text,
                    border: `1px solid ${styles.border}`,
                    borderRadius: '6px'
                  }}
                />
              </div>

              <div>
                <label style={{ color: styles.text, fontWeight: 600, marginBottom: '5px', display: 'block' }}>Assignment Date *</label>
                <input
                  type="date"
                  name="assignmentDate"
                  value={formData.assignmentDate}
                  onChange={handleInputChange}
                  required
                  style={{
                    width: '100%',
                    padding: '10px',
                    backgroundColor: styles.card,
                    color: styles.text,
                    border: `1px solid ${styles.border}`,
                    borderRadius: '6px'
                  }}
                />
              </div>

              <div>
                <label style={{ color: styles.text, fontWeight: 600, marginBottom: '5px', display: 'block' }}>Expected Return Date</label>
                <input
                  type="date"
                  name="expectedReturnDate"
                  value={formData.expectedReturnDate}
                  onChange={handleInputChange}
                  style={{
                    width: '100%',
                    padding: '10px',
                    backgroundColor: styles.card,
                    color: styles.text,
                    border: `1px solid ${styles.border}`,
                    borderRadius: '6px'
                  }}
                />
              </div>
            </div>

            <div style={{ marginBottom: '15px' }}>
              <label style={{ color: styles.text, fontWeight: 600, marginBottom: '5px', display: 'block' }}>Notes</label>
              <textarea
                name="notes"
                value={formData.notes}
                onChange={handleInputChange}
                rows="3"
                style={{
                  width: '100%',
                  padding: '10px',
                  backgroundColor: styles.card,
                  color: styles.text,
                  border: `1px solid ${styles.border}`,
                  borderRadius: '6px',
                  fontFamily: 'inherit'
                }}
              />
            </div>

            <div style={{ display: 'flex', gap: '10px' }}>
              <button
                type="submit"
                style={{
                  padding: '10px 20px',
                  backgroundColor: styles.success,
                  color: 'white',
                  border: 'none',
                  borderRadius: '6px',
                  cursor: 'pointer',
                  fontWeight: 600
                }}
              >
                {editingId ? '💾 Update' : '✔️ Create'} Assignment
              </button>
              <button
                type="button"
                onClick={() => {
                  setShowForm(false);
                  setEditingId(null);
                  setFormData({
                    assetId: '',
                    assignedTo: '',
                    department: '',
                    location: '',
                    assignmentDate: new Date().toISOString().split('T')[0],
                    expectedReturnDate: '',
                    notes: '',
                    status: 'Pending'
                  });
                }}
                style={{
                  padding: '10px 20px',
                  backgroundColor: styles.border,
                  color: styles.text,
                  border: 'none',
                  borderRadius: '6px',
                  cursor: 'pointer',
                  fontWeight: 600
                }}
              >
                Cancel
              </button>
            </div>
          </form>
        )}

        {/* Assignments Table */}
        {loading ? (
          <div style={{ textAlign: 'center', padding: '40px', color: styles.subText }}>
            <div style={{ fontSize: '1.5rem', marginBottom: '10px' }}>⏳</div>
            <div>Loading assignments...</div>
          </div>
        ) : paginatedAssignments.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '40px', color: styles.subText }}>
            <div style={{ fontSize: '2rem', marginBottom: '10px' }}>📭</div>
            <div>No assignments found</div>
          </div>
        ) : (
          <>
            <div style={{ overflowX: 'auto' }}>
              <table style={{
                width: '100%',
                borderCollapse: 'collapse',
                fontSize: '0.9rem'
              }}>
                <thead>
                  <tr style={{ backgroundColor: isDark ? '#0d1b2a' : '#f8f9fa', borderBottom: `2px solid ${styles.border}` }}>
                    <th style={{ padding: '12px', textAlign: 'left', color: styles.text }}>Asset</th>
                    <th style={{ padding: '12px', textAlign: 'left', color: styles.text }}>Assigned To</th>
                    <th style={{ padding: '12px', textAlign: 'left', color: styles.text }}>Department</th>
                    <th style={{ padding: '12px', textAlign: 'left', color: styles.text }}>Location</th>
                    <th style={{ padding: '12px', textAlign: 'left', color: styles.text }}>Date</th>
                    <th style={{ padding: '12px', textAlign: 'left', color: styles.text }}>Status</th>
                    <th style={{ padding: '12px', textAlign: 'center', color: styles.text }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {paginatedAssignments.map(assignment => (
                    <tr key={assignment.id} style={{ borderBottom: `1px solid ${styles.border}` }}>
                      <td style={{ padding: '12px', color: styles.text }}>{assignment.asset?.name || 'N/A'}</td>
                      <td style={{ padding: '12px', color: styles.text }}>{assignment.assignedToUser?.username || 'N/A'}</td>
                      <td style={{ padding: '12px', color: styles.text }}>{assignment.department || 'N/A'}</td>
                      <td style={{ padding: '12px', color: styles.text }}>{assignment.location || 'N/A'}</td>
                      <td style={{ padding: '12px', color: styles.text }}>{new Date(assignment.assignmentDate).toLocaleDateString()}</td>
                      <td style={{ padding: '12px' }}>
                        <span style={{
                          padding: '4px 8px',
                          borderRadius: '4px',
                          fontSize: '0.8rem',
                          fontWeight: 600,
                          backgroundColor: assignment.status === 'Approved' ? '#c6f6d5' :
                                          assignment.status === 'Pending' ? '#feebc8' :
                                          assignment.status === 'Rejected' ? '#fed7d7' :
                                          assignment.status === 'Returned' ? '#bee3f8' : '#e2e8f0',
                          color: assignment.status === 'Approved' ? '#22543d' :
                                assignment.status === 'Pending' ? '#7c2d12' :
                                assignment.status === 'Rejected' ? '#742a2a' :
                                assignment.status === 'Returned' ? '#2c5282' : '#1a365d'
                        }}>
                          {assignment.status}
                        </span>
                      </td>
                      <td style={{ padding: '12px', textAlign: 'center' }}>
                        <button
                          onClick={() => handleEdit(assignment)}
                          style={{
                            padding: '4px 8px',
                            marginRight: '4px',
                            backgroundColor: styles.accent,
                            color: 'white',
                            border: 'none',
                            borderRadius: '4px',
                            cursor: 'pointer',
                            fontSize: '0.85rem'
                          }}
                        >
                          ✏️
                        </button>
                        {assignment.status === 'Pending' && (
                          <>
                            <button
                              onClick={() => handleApprove(assignment.id)}
                              style={{
                                padding: '4px 8px',
                                marginRight: '4px',
                                backgroundColor: styles.success,
                                color: 'white',
                                border: 'none',
                                borderRadius: '4px',
                                cursor: 'pointer',
                                fontSize: '0.85rem'
                              }}
                            >
                              ✔️
                            </button>
                            <button
                              onClick={() => handleReject(assignment.id)}
                              style={{
                                padding: '4px 8px',
                                marginRight: '4px',
                                backgroundColor: styles.danger,
                                color: 'white',
                                border: 'none',
                                borderRadius: '4px',
                                cursor: 'pointer',
                                fontSize: '0.85rem'
                              }}
                            >
                              ✕
                            </button>
                          </>
                        )}
                        {assignment.status === 'Approved' && (
                          <button
                            onClick={() => handleReturnAsset(assignment.id)}
                            style={{
                              padding: '4px 8px',
                              marginRight: '4px',
                              backgroundColor: styles.warning,
                              color: 'white',
                              border: 'none',
                              borderRadius: '4px',
                              cursor: 'pointer',
                              fontSize: '0.85rem'
                            }}
                          >
                            🔄
                          </button>
                        )}
                        <button
                          onClick={() => handleDelete(assignment.id)}
                          style={{
                            padding: '4px 8px',
                            backgroundColor: '#cbd5e0',
                            color: '#1a365d',
                            border: 'none',
                            borderRadius: '4px',
                            cursor: 'pointer',
                            fontSize: '0.85rem'
                          }}
                        >
                          🗑️
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Pagination */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '20px', color: styles.subText }}>
              <div>Showing {((currentPage - 1) * itemsPerPage) + 1} to {Math.min(currentPage * itemsPerPage, filteredAssignments.length)} of {filteredAssignments.length}</div>
              <div style={{ display: 'flex', gap: '5px' }}>
                <button
                  onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                  disabled={currentPage === 1}
                  style={{
                    padding: '6px 12px',
                    backgroundColor: currentPage === 1 ? '#e2e8f0' : styles.accent,
                    color: currentPage === 1 ? '#a0aec0' : 'white',
                    border: 'none',
                    borderRadius: '4px',
                    cursor: currentPage === 1 ? 'not-allowed' : 'pointer'
                  }}
                >
                  ← Prev
                </button>
                {Array.from({ length: totalPages }, (_, i) => i + 1).map(page => (
                  <button
                    key={page}
                    onClick={() => setCurrentPage(page)}
                    style={{
                      padding: '6px 10px',
                      backgroundColor: page === currentPage ? styles.accent : isDark ? '#0d1b2a' : '#f8f9fa',
                      color: page === currentPage ? 'white' : styles.text,
                      border: `1px solid ${styles.border}`,
                      borderRadius: '4px',
                      cursor: 'pointer'
                    }}
                  >
                    {page}
                  </button>
                ))}
                <button
                  onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                  disabled={currentPage === totalPages}
                  style={{
                    padding: '6px 12px',
                    backgroundColor: currentPage === totalPages ? '#e2e8f0' : styles.accent,
                    color: currentPage === totalPages ? '#a0aec0' : 'white',
                    border: 'none',
                    borderRadius: '4px',
                    cursor: currentPage === totalPages ? 'not-allowed' : 'pointer'
                  }}
                >
                  Next →
                </button>
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default AdminAssignment;

import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useLanguage } from '../../contexts/UiContext';
import { toast } from 'react-toastify';
import axios from 'axios';

const AdminAuditLogs = () => {
  const { user } = useAuth();
  const { language, theme } = useLanguage();
  const [auditLogs, setAuditLogs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [filterAction, setFilterAction] = useState('all');
  const [filterModule, setFilterModule] = useState('all');
  const [filterUser, setFilterUser] = useState('all');
  const [filterStartDate, setFilterStartDate] = useState('');
  const [filterEndDate, setFilterEndDate] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage] = useState(15);

  const isDark = theme === 'dark';

  const [users, setUsers] = useState([]);
  const [actions, setActions] = useState([]);
  const [modules, setModules] = useState([]);

  const themeStyles = {
    light: {
      bg: '#f0f5ff',
      card: '#ffffff',
      text: '#1a375d',
      subText: '#4a5568',
      border: '#b4d2f0',
      hover: '#e0e7ff',
      accent: '#2b6cb0',
      danger: '#e53e3e',
      success: '#48bb78',
      warning: '#ed8936',
      shadow: '0 4px 12px rgba(0, 0, 100, 0.1)'
    },
    dark: {
      bg: '#141e2d',
      card: '#1e2d45',
      text: '#c8dcf5',
      subText: '#a0aec0',
      border: '#32465f',
      hover: '#334155',
      accent: '#63b3ed',
      danger: '#fc8181',
      success: '#48bb78',
      warning: '#ed8936',
      shadow: '0 4px 12px rgba(0, 0, 0, 0.3)'
    }
  };

  const styles = themeStyles[theme];

  const actionTypes = [
    'Login', 'Logout', 'User Create', 'User Update', 'User Delete', 'Role Change',
    'Asset Create', 'Asset Update', 'Asset Delete', 'Asset Assign', 'Asset Transfer',
    'Asset Retire', 'Maintenance Request', 'Maintenance Update', 'Maintenance Complete',
    'RFID Scan', 'RFID Register', 'Settings Change', 'Backup Create', 'Backup Restore',
    'Data Export', 'Approval', 'Rejection'
  ];

  const moduleTypes = [
    'User Management', 'Asset Management', 'Assignment', 'Transfer', 'Maintenance',
    'RFID', 'Finance', 'Inventory', 'Notifications', 'Settings', 'Reports', 'Backup'
  ];

  useEffect(() => {
    fetchAuditLogs();
    fetchUsers();
  }, []);

  useEffect(() => {
    // Extract unique actions and modules from logs
    const uniqueActions = [...new Set(auditLogs.map(log => log.action))];
    const uniqueModules = [...new Set(auditLogs.map(log => log.module))];
    setActions(uniqueActions);
    setModules(uniqueModules);
  }, [auditLogs]);

  const fetchAuditLogs = async () => {
    setLoading(true);
    try {
      const response = await axios.get('/api/audit');
      const logs = response.data?.data || response.data?.logs || response.data || [];
      // Sort by date descending
      logs.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
      setAuditLogs(logs);
    } catch (error) {
      console.error('Error fetching audit logs:', error);
      toast.error('Failed to load audit logs');
    } finally {
      setLoading(false);
    }
  };

  const fetchUsers = async () => {
    try {
      const response = await axios.get('/api/users');
      setUsers(response.data?.data || response.data || []);
    } catch (error) {
      console.error('Error fetching users:', error);
    }
  };

  const handleExportPDF = () => {
    const element = document.createElement('div');
    element.innerHTML = `
      <h2>Audit Logs Report</h2>
      <p>Generated: ${new Date().toLocaleString()}</p>
      <table border="1" style="width: 100%; border-collapse: collapse;">
        <thead>
          <tr>
            <th>Date/Time</th>
            <th>User</th>
            <th>Role</th>
            <th>Action</th>
            <th>Module</th>
            <th>Result</th>
            <th>IP Address</th>
          </tr>
        </thead>
        <tbody>
          ${filteredLogs.map(log => `
            <tr>
              <td>${new Date(log.createdAt).toLocaleString()}</td>
              <td>${log.user?.username || 'N/A'}</td>
              <td>${log.userRole || 'N/A'}</td>
              <td>${log.action || 'N/A'}</td>
              <td>${log.module || 'N/A'}</td>
              <td>${log.result || 'N/A'}</td>
              <td>${log.ipAddress || 'N/A'}</td>
            </tr>
          `).join('')}
        </tbody>
      </table>
    `;
    
    const win = window.open('', '', 'width=800,height=600');
    win.document.write('<html><head><title>Audit Logs</title></head><body>');
    win.document.write(element.innerHTML);
    win.document.write('</body></html>');
    win.print();
    win.close();
  };

  const handleExportCSV = () => {
    const headers = ['Date/Time', 'User', 'Role', 'Action', 'Module', 'Record ID', 'IP Address', 'Description', 'Result'];
    const rows = filteredLogs.map(log => [
      new Date(log.createdAt).toLocaleString(),
      log.user?.username || 'N/A',
      log.userRole || 'N/A',
      log.action || 'N/A',
      log.module || 'N/A',
      log.recordId || 'N/A',
      log.ipAddress || 'N/A',
      log.description || 'N/A',
      log.result || 'N/A'
    ]);

    let csv = headers.join(',') + '\n';
    rows.forEach(row => {
      csv += row.map(cell => `"${cell}"`).join(',') + '\n';
    });

    const link = document.createElement('a');
    link.href = 'data:text/csv;charset=utf-8,' + encodeURIComponent(csv);
    link.download = `audit-logs-${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  const handleClearLogs = () => {
    if (window.confirm('This action cannot be undone. Are you sure you want to delete all audit logs?')) {
      // This would typically require admin confirmation and should be a separate API endpoint
      toast.info('Audit log deletion requires database backup. Contact your database administrator.');
    }
  };

  const filteredLogs = auditLogs.filter(log => {
    const matchesSearch = 
      (log.user?.username?.toLowerCase().includes(searchQuery.toLowerCase())) ||
      (log.action?.toLowerCase().includes(searchQuery.toLowerCase())) ||
      (log.module?.toLowerCase().includes(searchQuery.toLowerCase())) ||
      (log.ipAddress?.includes(searchQuery)) ||
      (log.description?.toLowerCase().includes(searchQuery.toLowerCase()));
    
    const matchesAction = filterAction === 'all' || log.action === filterAction;
    const matchesModule = filterModule === 'all' || log.module === filterModule;
    const matchesUser = filterUser === 'all' || log.userId === filterUser;
    
    let matchesDateRange = true;
    if (filterStartDate && filterEndDate) {
      const logDate = new Date(log.createdAt);
      const startDate = new Date(filterStartDate);
      const endDate = new Date(filterEndDate);
      endDate.setHours(23, 59, 59, 999);
      matchesDateRange = logDate >= startDate && logDate <= endDate;
    }

    return matchesSearch && matchesAction && matchesModule && matchesUser && matchesDateRange;
  });

  const paginatedLogs = filteredLogs.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  const totalPages = Math.ceil(filteredLogs.length / itemsPerPage);

  const getActionColor = (action) => {
    if (action.includes('Create') || action.includes('Login')) return styles.success;
    if (action.includes('Delete') || action.includes('Logout')) return styles.danger;
    if (action.includes('Update') || action.includes('Change')) return styles.warning;
    return styles.accent;
  };

  return (
    <div style={{ padding: '20px', backgroundColor: styles.bg, minHeight: '100vh' }}>
      <div style={{
        backgroundColor: styles.card,
        borderRadius: '12px',
        padding: '24px',
        boxShadow: styles.shadow,
        marginBottom: '20px'
      }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
          <h1 style={{ color: styles.text, margin: 0 }}>📋 Audit Logs & Activity</h1>
          <div style={{ display: 'flex', gap: '10px' }}>
            <button
              onClick={handleExportPDF}
              style={{
                padding: '10px 16px',
                backgroundColor: styles.accent,
                color: 'white',
                border: 'none',
                borderRadius: '6px',
                cursor: 'pointer',
                fontWeight: 600
              }}
            >
              📄 Export PDF
            </button>
            <button
              onClick={handleExportCSV}
              style={{
                padding: '10px 16px',
                backgroundColor: styles.accent,
                color: 'white',
                border: 'none',
                borderRadius: '6px',
                cursor: 'pointer',
                fontWeight: 600
              }}
            >
              📊 Export Excel
            </button>
            <button
              onClick={fetchAuditLogs}
              style={{
                padding: '10px 16px',
                backgroundColor: styles.accent,
                color: 'white',
                border: 'none',
                borderRadius: '6px',
                cursor: 'pointer',
                fontWeight: 600
              }}
            >
              🔄 Refresh
            </button>
          </div>
        </div>

        {/* Summary Stats */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))', gap: '12px', marginBottom: '20px' }}>
          <div style={{
            backgroundColor: isDark ? '#0d1b2a' : '#f8f9fa',
            padding: '15px',
            borderRadius: '8px',
            border: `1px solid ${styles.border}`
          }}>
            <div style={{ fontSize: '0.85rem', color: styles.subText }}>Total Events</div>
            <div style={{ fontSize: '1.5rem', fontWeight: 'bold', color: styles.text }}>{auditLogs.length}</div>
          </div>
          <div style={{
            backgroundColor: isDark ? '#0d1b2a' : '#f8f9fa',
            padding: '15px',
            borderRadius: '8px',
            border: `1px solid ${styles.border}`
          }}>
            <div style={{ fontSize: '0.85rem', color: styles.subText }}>Filtered Events</div>
            <div style={{ fontSize: '1.5rem', fontWeight: 'bold', color: styles.text }}>{filteredLogs.length}</div>
          </div>
          <div style={{
            backgroundColor: isDark ? '#0d1b2a' : '#f8f9fa',
            padding: '15px',
            borderRadius: '8px',
            border: `1px solid ${styles.border}`
          }}>
            <div style={{ fontSize: '0.85rem', color: styles.subText }}>Unique Users</div>
            <div style={{ fontSize: '1.5rem', fontWeight: 'bold', color: styles.text }}>{new Set(auditLogs.map(log => log.userId)).size}</div>
          </div>
          <div style={{
            backgroundColor: isDark ? '#0d1b2a' : '#f8f9fa',
            padding: '15px',
            borderRadius: '8px',
            border: `1px solid ${styles.border}`
          }}>
            <div style={{ fontSize: '0.85rem', color: styles.subText }}>Unique Actions</div>
            <div style={{ fontSize: '1.5rem', fontWeight: 'bold', color: styles.text }}>{actions.length}</div>
          </div>
        </div>

        {/* Filters */}
        <div style={{
          backgroundColor: isDark ? '#0d1b2a' : '#f8f9fa',
          padding: '15px',
          borderRadius: '8px',
          marginBottom: '20px',
          border: `1px solid ${styles.border}`
        }}>
          <div style={{ marginBottom: '10px', fontWeight: 600, color: styles.text }}>🔍 Filters</div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: '10px' }}>
            <input
              type="text"
              placeholder="Search user, action, module..."
              value={searchQuery}
              onChange={(e) => {
                setSearchQuery(e.target.value);
                setCurrentPage(1);
              }}
              style={{
                padding: '10px',
                backgroundColor: styles.card,
                color: styles.text,
                border: `1px solid ${styles.border}`,
                borderRadius: '6px'
              }}
            />
            <select
              value={filterUser}
              onChange={(e) => {
                setFilterUser(e.target.value);
                setCurrentPage(1);
              }}
              style={{
                padding: '10px',
                backgroundColor: styles.card,
                color: styles.text,
                border: `1px solid ${styles.border}`,
                borderRadius: '6px',
                cursor: 'pointer'
              }}
            >
              <option value="all">All Users</option>
              {users.map(u => (
                <option key={u.id} value={u.id}>{u.username}</option>
              ))}
            </select>
            <select
              value={filterAction}
              onChange={(e) => {
                setFilterAction(e.target.value);
                setCurrentPage(1);
              }}
              style={{
                padding: '10px',
                backgroundColor: styles.card,
                color: styles.text,
                border: `1px solid ${styles.border}`,
                borderRadius: '6px',
                cursor: 'pointer'
              }}
            >
              <option value="all">All Actions</option>
              {actions.map(action => (
                <option key={action} value={action}>{action}</option>
              ))}
            </select>
            <select
              value={filterModule}
              onChange={(e) => {
                setFilterModule(e.target.value);
                setCurrentPage(1);
              }}
              style={{
                padding: '10px',
                backgroundColor: styles.card,
                color: styles.text,
                border: `1px solid ${styles.border}`,
                borderRadius: '6px',
                cursor: 'pointer'
              }}
            >
              <option value="all">All Modules</option>
              {modules.map(module => (
                <option key={module} value={module}>{module}</option>
              ))}
            </select>
            <input
              type="date"
              value={filterStartDate}
              onChange={(e) => {
                setFilterStartDate(e.target.value);
                setCurrentPage(1);
              }}
              style={{
                padding: '10px',
                backgroundColor: styles.card,
                color: styles.text,
                border: `1px solid ${styles.border}`,
                borderRadius: '6px'
              }}
            />
            <input
              type="date"
              value={filterEndDate}
              onChange={(e) => {
                setFilterEndDate(e.target.value);
                setCurrentPage(1);
              }}
              style={{
                padding: '10px',
                backgroundColor: styles.card,
                color: styles.text,
                border: `1px solid ${styles.border}`,
                borderRadius: '6px'
              }}
            />
          </div>
        </div>

        {/* Logs Table */}
        {loading ? (
          <div style={{ textAlign: 'center', padding: '40px', color: styles.subText }}>
            <div style={{ fontSize: '1.5rem', marginBottom: '10px' }}>⏳</div>
            <div>Loading audit logs...</div>
          </div>
        ) : paginatedLogs.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '40px', color: styles.subText }}>
            <div style={{ fontSize: '2rem', marginBottom: '10px' }}>📭</div>
            <div>No audit logs found</div>
          </div>
        ) : (
          <>
            <div style={{ overflowX: 'auto' }}>
              <table style={{
                width: '100%',
                borderCollapse: 'collapse',
                fontSize: '0.85rem'
              }}>
                <thead>
                  <tr style={{ backgroundColor: isDark ? '#0d1b2a' : '#f8f9fa', borderBottom: `2px solid ${styles.border}` }}>
                    <th style={{ padding: '12px', textAlign: 'left', color: styles.text }}>Date/Time</th>
                    <th style={{ padding: '12px', textAlign: 'left', color: styles.text }}>User</th>
                    <th style={{ padding: '12px', textAlign: 'left', color: styles.text }}>Role</th>
                    <th style={{ padding: '12px', textAlign: 'left', color: styles.text }}>Action</th>
                    <th style={{ padding: '12px', textAlign: 'left', color: styles.text }}>Module</th>
                    <th style={{ padding: '12px', textAlign: 'left', color: styles.text }}>IP Address</th>
                    <th style={{ padding: '12px', textAlign: 'left', color: styles.text }}>Result</th>
                  </tr>
                </thead>
                <tbody>
                  {paginatedLogs.map(log => (
                    <tr key={log.id} style={{ borderBottom: `1px solid ${styles.border}` }}>
                      <td style={{ padding: '12px', color: styles.text }}>
                        <div style={{ fontSize: '0.8rem' }}>
                          {new Date(log.createdAt).toLocaleDateString()}
                        </div>
                        <div style={{ fontSize: '0.75rem', color: styles.subText }}>
                          {new Date(log.createdAt).toLocaleTimeString()}
                        </div>
                      </td>
                      <td style={{ padding: '12px', color: styles.text }}>{log.user?.username || 'N/A'}</td>
                      <td style={{ padding: '12px', color: styles.text }}>
                        <span style={{ fontSize: '0.8rem', backgroundColor: '#e0e7ff', padding: '2px 6px', borderRadius: '3px' }}>
                          {log.userRole || 'N/A'}
                        </span>
                      </td>
                      <td style={{ padding: '12px' }}>
                        <span style={{
                          padding: '4px 8px',
                          borderRadius: '4px',
                          fontSize: '0.75rem',
                          fontWeight: 600,
                          backgroundColor: getActionColor(log.action),
                          color: 'white'
                        }}>
                          {log.action || 'N/A'}
                        </span>
                      </td>
                      <td style={{ padding: '12px', color: styles.text }}>{log.module || 'N/A'}</td>
                      <td style={{ padding: '12px', color: styles.text, fontSize: '0.8rem', fontFamily: 'monospace' }}>
                        {log.ipAddress || 'N/A'}
                      </td>
                      <td style={{ padding: '12px' }}>
                        <span style={{
                          padding: '4px 8px',
                          borderRadius: '4px',
                          fontSize: '0.75rem',
                          fontWeight: 600,
                          backgroundColor: log.result === 'Success' ? '#c6f6d5' : '#fed7d7',
                          color: log.result === 'Success' ? '#22543d' : '#742a2a'
                        }}>
                          {log.result || 'N/A'}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Pagination */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '20px', color: styles.subText }}>
              <div>Showing {((currentPage - 1) * itemsPerPage) + 1} to {Math.min(currentPage * itemsPerPage, filteredLogs.length)} of {filteredLogs.length}</div>
              <div style={{ display: 'flex', gap: '5px' }}>
                <button
                  onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                  disabled={currentPage === 1}
                  style={{
                    padding: '6px 12px',
                    backgroundColor: currentPage === 1 ? '#e2e8f0' : styles.accent,
                    color: currentPage === 1 ? '#a0aec0' : 'white',
                    border: 'none',
                    borderRadius: '4px',
                    cursor: currentPage === 1 ? 'not-allowed' : 'pointer'
                  }}
                >
                  ← Prev
                </button>
                {Array.from({ length: Math.min(totalPages, 5) }, (_, i) => i + 1).map(page => (
                  <button
                    key={page}
                    onClick={() => setCurrentPage(page)}
                    style={{
                      padding: '6px 10px',
                      backgroundColor: page === currentPage ? styles.accent : isDark ? '#0d1b2a' : '#f8f9fa',
                      color: page === currentPage ? 'white' : styles.text,
                      border: `1px solid ${styles.border}`,
                      borderRadius: '4px',
                      cursor: 'pointer'
                    }}
                  >
                    {page}
                  </button>
                ))}
                {totalPages > 5 && <span style={{ color: styles.subText }}>...</span>}
                <button
                  onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                  disabled={currentPage === totalPages}
                  style={{
                    padding: '6px 12px',
                    backgroundColor: currentPage === totalPages ? '#e2e8f0' : styles.accent,
                    color: currentPage === totalPages ? '#a0aec0' : 'white',
                    border: 'none',
                    borderRadius: '4px',
                    cursor: currentPage === totalPages ? 'not-allowed' : 'pointer'
                  }}
                >
                  Next →
                </button>
              </div>
            </div>
          </>
        )}

        {/* Warning */}
        <div style={{
          marginTop: '20px',
          padding: '15px',
          backgroundColor: '#fef5e7',
          border: '1px solid #f9e79f',
          borderRadius: '6px',
          color: '#7d6608'
        }}>
          <strong>⚠️ Note:</strong> Audit logs are permanent records and cannot be edited. All system activities are recorded for security and compliance purposes. Logs older than 90 days are archived.
        </div>
      </div>
    </div>
  );
};

export default AdminAuditLogs;

import React, { useState, useEffect } from 'react';
import { useLanguage } from '../../contexts/UiContext';
import { toast } from 'react-toastify';
import axios from 'axios';

const AdminBackup = () => {
  const { language, theme } = useLanguage();
  const [backups, setBackups] = useState([]);
  const [loading, setLoading] = useState(true);
  const [creating, setCreating] = useState(false);
  const [restoring, setRestoring] = useState(null);
  const [filter, setFilter] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');

  const isDark = theme === 'dark';
  const t = language === 'en' ? englishTranslations : amharicTranslations;

  useEffect(() => {
    fetchBackups();
  }, []);

  const fetchBackups = async () => {
    setLoading(true);
    try {
      const response = await axios.get('/api/backups');
      setBackups(response.data.backups || []);
    } catch (error) {
      toast.error(t.loadFailed);
      setBackups([]);
    }
    setLoading(false);
  };

  const createBackup = async () => {
    setCreating(true);
    try {
      await axios.post('/api/backups');
      toast.success(t.backupCreated);
      fetchBackups();
    } catch (error) {
      toast.error(t.createFailed);
    }
    setCreating(false);
  };

  const downloadBackup = async (filename) => {
    try {
      window.open(`/api/backups/download/${filename}`, '_blank');
      toast.success(t.downloadStarted);
    } catch (error) {
      toast.error(t.downloadFailed);
    }
  };

  const restoreBackup = async (filename) => {
    if (!window.confirm(t.confirmRestore)) return;
    setRestoring(filename);
    try {
      await axios.post(`/api/backups/restore/${filename}`);
      toast.success(t.restoreSuccess);
      fetchBackups();
    } catch (error) {
      toast.error(t.restoreFailed);
    }
    setRestoring(null);
  };

  const deleteBackup = async (filename) => {
    if (!window.confirm(t.confirmDelete)) return;
    try {
      await axios.delete(`/api/backups/${filename}`);
      toast.success(t.deleteSuccess);
      fetchBackups();
    } catch (error) {
      toast.error(t.deleteFailed);
    }
  };

  const verifyBackup = async (filename) => {
    try {
      const response = await axios.get(`/api/backups/verify/${filename}`);
      if (response.data.valid) {
        toast.success(t.verifySuccess);
      } else {
        toast.warning(t.verifyFailed);
      }
    } catch (error) {
      toast.error(t.verifyError);
    }
  };

  const getFileSize = (bytes) => {
    if (!bytes) return '0 B';
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1048576) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / 1048576).toFixed(1) + ' MB';
  };

  const getStatusColor = (status) => {
    const colors = {
      'Completed': '#48bb78',
      'Failed': '#fc8181',
      'In Progress': '#4299e1',
      'Pending': '#ed8936'
    };
    return colors[status] || '#a0aec0';
  };

  const getStatusBadge = (status) => ({
    display: 'inline-block',
    padding: '3px 12px',
    borderRadius: '20px',
    fontSize: '0.75rem',
    fontWeight: 600,
    background: getStatusColor(status) + '20',
    color: getStatusColor(status)
  });

  const getTypeBadge = (type) => ({
    display: 'inline-block',
    padding: '2px 10px',
    borderRadius: '12px',
    fontSize: '0.7rem',
    fontWeight: 600,
    background: isDark ? '#32465f' : '#e8edf5',
    color: isDark ? '#c8dcf5' : '#1a365d'
  });

  const getFilteredBackups = () => {
    let filtered = backups;

    if (filter === 'completed') {
      filtered = filtered.filter(b => b.status === 'Completed');
    } else if (filter === 'failed') {
      filtered = filtered.filter(b => b.status === 'Failed');
    }

    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase();
      filtered = filtered.filter(b =>
        b.filename.toLowerCase().includes(query) ||
        b.created_by?.toLowerCase().includes(query) ||
        b.type?.toLowerCase().includes(query)
      );
    }

    return filtered;
  };

  const clearFilters = () => {
    setFilter('all');
    setSearchQuery('');
  };

  const getStats = () => {
    const total = backups.length;
    const completed = backups.filter(b => b.status === 'Completed').length;
    const failed = backups.filter(b => b.status === 'Failed').length;
    const totalSize = backups.reduce((sum, b) => sum + (b.size || 0), 0);
    return { total, completed, failed, totalSize };
  };

  const stats = getStats();
  const filtered = getFilteredBackups();

  const styles = {
    container: { padding: '20px', maxWidth: '1200px', margin: '0 auto' },
    header: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      flexWrap: 'wrap',
      gap: '16px',
      marginBottom: '24px'
    },
    title: {
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '1.75rem',
      fontWeight: 700,
      margin: 0
    },
    subtitle: {
      color: isDark ? '#8896b0' : '#4a5568',
      fontSize: '0.9rem',
      margin: '4px 0 0 0'
    },
    createButton: {
      padding: '10px 24px',
      background: 'linear-gradient(135deg, #48bb78, #38a169)',
      color: 'white',
      border: 'none',
      borderRadius: '8px',
      fontWeight: 600,
      cursor: 'pointer',
      fontSize: '0.95rem',
      transition: 'all 0.2s',
      display: 'flex',
      alignItems: 'center',
      gap: '8px'
    },
    createButtonDisabled: {
      padding: '10px 24px',
      background: '#a0aec0',
      color: 'white',
      border: 'none',
      borderRadius: '8px',
      fontWeight: 600,
      cursor: 'not-allowed',
      fontSize: '0.95rem',
      opacity: 0.7
    },
    statsBar: {
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fit, minmax(140px, 1fr))',
      gap: '12px',
      marginBottom: '16px',
      padding: '16px',
      background: isDark ? '#1a273a' : '#f7fafc',
      borderRadius: '12px',
      border: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`
    },
    statItem: {
      textAlign: 'center'
    },
    statNumber: {
      fontSize: '1.5rem',
      fontWeight: 700,
      color: isDark ? '#c8dcf5' : '#1a365d'
    },
    statLabel: {
      fontSize: '0.75rem',
      color: isDark ? '#8896b0' : '#4a5568'
    },
    filterBar: {
      display: 'flex',
      gap: '10px',
      flexWrap: 'wrap',
      alignItems: 'center',
      padding: '12px 16px',
      background: isDark ? '#141e2d' : '#f7fafc',
