      border: 'none',
      borderRadius: '8px',
      fontWeight: 600,
      cursor: 'pointer',
      fontSize: '0.9rem',
      transition: 'all 0.2s'
    })
  };

  return (
    <div style={styles.container}>
      {/* Header */}
      <div style={styles.header}>
        <div>
          <h1 style={styles.title}>💾 {t.backupManager}</h1>
          <p style={styles.subtitle}>{t.totalBackups}: {stats.total}</p>
        </div>
        <button
          style={creating ? styles.createButtonDisabled : styles.createButton}
          onClick={createBackup}
          disabled={creating}
        >
          {creating ? (
            <>⏳ {t.creating}</>
          ) : (
            <>➕ {t.createBackup}</>
          )}
        </button>
      </div>

      {/* Stats Bar */}
      {backups.length > 0 && (
        <div style={styles.statsBar}>
          <div style={styles.statItem}>
            <div style={styles.statNumber}>{stats.total}</div>
            <div style={styles.statLabel}>{t.total}</div>
          </div>
          <div style={styles.statItem}>
            <div style={{ ...styles.statNumber, color: '#48bb78' }}>{stats.completed}</div>
            <div style={styles.statLabel}>{t.completed}</div>
          </div>
          <div style={styles.statItem}>
            <div style={{ ...styles.statNumber, color: '#fc8181' }}>{stats.failed}</div>
            <div style={styles.statLabel}>{t.failed}</div>
          </div>
          <div style={styles.statItem}>
            <div style={styles.statNumber}>{getFileSize(stats.totalSize)}</div>
            <div style={styles.statLabel}>{t.totalSize}</div>
          </div>
        </div>
      )}

      {/* Filter Bar */}
      <div style={styles.filterBar}>
        <input
          type="text"
          style={styles.searchInput}
          placeholder={t.searchPlaceholder}
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
        />
        <select style={styles.select} value={filter} onChange={(e) => setFilter(e.target.value)}>
          <option value="all">{t.allBackups}</option>
          <option value="completed">{t.completedOnly}</option>
          <option value="failed">{t.failedOnly}</option>
        </select>
        {(filter !== 'all' || searchQuery) && (
          <button style={styles.clearButton} onClick={clearFilters}>
            {t.clearFilters}
          </button>
        )}
      </div>

      {/* Backup List */}
      {loading ? (
        <div style={styles.emptyState}>⏳ {t.loading}</div>
      ) : backups.length === 0 ? (
        <div style={styles.emptyState}>
          <div style={styles.emptyIcon}>📂</div>
          <h3 style={{ color: isDark ? '#c8dcf5' : '#1a365d', marginBottom: '8px' }}>{t.noBackups}</h3>
          <p>{t.noBackupsDesc}</p>
          <button style={{ ...styles.createButton, marginTop: '16px' }} onClick={createBackup}>
            ➕ {t.createFirstBackup}
          </button>
        </div>
      ) : filtered.length === 0 ? (
        <div style={styles.emptyState}>
          <div style={styles.emptyIcon}>🔍</div>
          <h3 style={{ color: isDark ? '#c8dcf5' : '#1a365d', marginBottom: '8px' }}>{t.noResults}</h3>
          <p>{t.noResultsDesc}</p>
          <button style={{ ...styles.clearButton, marginTop: '12px' }} onClick={clearFilters}>
            {t.clearFilters}
          </button>
        </div>
      ) : (
        filtered.map((backup, index) => (
          <div key={index} style={styles.card}>
            <div style={styles.backupInfo}>
              <span style={styles.backupIcon}>
                {backup.status === 'Completed' ? '✅' : '❌'}
              </span>
              <div style={styles.backupDetails}>
                <div style={styles.backupFilename}>{backup.filename}</div>
                <div style={styles.backupMeta}>
                  <span>📏 {getFileSize(backup.size)}</span>
                  <span>🕐 {new Date(backup.created_at).toLocaleString()}</span>
                  <span>👤 {t.createdBy}: {backup.created_by || 'System'}</span>
                  <span style={getStatusBadge(backup.status)}>{backup.status}</span>
                  <span style={getTypeBadge(backup.type || 'Full')}>{backup.type || 'Full'}</span>
                </div>
                {backup.notes && (
                  <div style={styles.backupNotes}>📝 {backup.notes}</div>
                )}
              </div>
            </div>
            <div style={styles.actions}>
              <button
                style={styles.actionButton('#48bb78')}
                onClick={() => verifyBackup(backup.filename)}
              >
                ✅ {t.verify}
              </button>
              <button
                style={styles.actionButton('#4299e1')}
                onClick={() => downloadBackup(backup.filename)}
              >
                📥 {t.download}
              </button>
              <button
                style={styles.actionButton('#ed8936', '#ffffff', restoring === backup.filename)}
                onClick={() => restoreBackup(backup.filename)}
                disabled={restoring === backup.filename}
              >
                {restoring === backup.filename ? '⏳' : '🔄'} {t.restore}
              </button>
              <button
                style={styles.actionButton('#fc8181')}
                onClick={() => deleteBackup(backup.filename)}
              >
                🗑️ {t.delete}
              </button>
            </div>
          </div>
        ))
      )}
    </div>
  );
};

