import React, { useState, useEffect } from 'react';
import { useLanguage } from '../../contexts/UiContext';
import { toast } from 'react-toastify';
import axios from 'axios';

const AdminDepartmentManagement = () => {
  const { language, theme } = useLanguage();
  const [departments, setDepartments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showCreate, setShowCreate] = useState(false);
  const [showEdit, setShowEdit] = useState(false);
  const [showAssets, setShowAssets] = useState(false);
  const [selectedDepartment, setSelectedDepartment] = useState(null);
  const [departmentAssets, setDepartmentAssets] = useState([]);
  const [users, setUsers] = useState([]);
  const [formData, setFormData] = useState({
    name: '',
    code: '',
    head: '',
    building: '',
    location: '',
    phone: '',
    email: '',
    description: '',
    status: 'Active'
  });

  const isDark = theme === 'dark';
  const t = language === 'en' ? englishTranslations : amharicTranslations;

  useEffect(() => {
    fetchDepartments();
    fetchUsers();
  }, []);

  const fetchDepartments = async () => {
    setLoading(true);
    try {
      const response = await axios.get('/api/departments');
      setDepartments(response.data.departments || []);
    } catch (error) {
      toast.error(t.loadFailed);
      setDepartments([]);
    }
    setLoading(false);
  };

  const fetchUsers = async () => {
    try {
      const response = await axios.get('/api/users');
      setUsers(response.data.users || []);
    } catch (error) {
      setUsers([]);
    }
  };

  const fetchDepartmentAssets = async (department) => {
    try {
      const response = await axios.get('/api/assets', { params: { department: department.name } });
      setDepartmentAssets(response.data.assets || []);
    } catch (error) {
      setDepartmentAssets([]);
    }
  };

  const handleCreate = async (e) => {
    e.preventDefault();
    try {
      await axios.post('/api/departments', formData);
      toast.success(t.deptCreated);
      setShowCreate(false);
      resetForm();
      fetchDepartments();
    } catch (error) {
      toast.error(error.response?.data?.message || t.createFailed);
    }
  };

  const handleUpdate = async (e) => {
    e.preventDefault();
    try {
      await axios.put(`/api/departments/${selectedDepartment.id}`, formData);
      toast.success(t.deptUpdated);
      setShowEdit(false);
      setSelectedDepartment(null);
      resetForm();
      fetchDepartments();
    } catch (error) {
      toast.error(error.response?.data?.message || t.updateFailed);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm(t.confirmDelete)) return;
    try {
      await axios.delete(`/api/departments/${id}`);
      toast.success(t.deptDeleted);
      fetchDepartments();
    } catch (error) {
      toast.error(t.deleteFailed);
    }
  };

  const handleViewAssets = async (dept) => {
    setSelectedDepartment(dept);
    await fetchDepartmentAssets(dept);
    setShowAssets(true);
  };

  const handleEditDepartment = (dept) => {
    setSelectedDepartment(dept);
    setFormData({
      name: dept.name,
      code: dept.code,
      head: dept.head || '',
      building: dept.building || '',
      location: dept.location || '',
      phone: dept.phone || '',
      email: dept.email || '',
      description: dept.description || '',
      status: dept.status || 'Active'
    });
    setShowEdit(true);
  };

  const resetForm = () => {
    setFormData({
      name: '',
      code: '',
      head: '',
      building: '',
      location: '',
      phone: '',
      email: '',
      description: '',
      status: 'Active'
    });
  };

  const getStatusColor = (status) => {
    return status === 'Active' ? '#48bb78' : '#fc8181';
  };

  const getStatusBadge = (status) => ({
    display: 'inline-block',
    padding: '3px 12px',
    borderRadius: '20px',
    fontSize: '0.75rem',
    fontWeight: 600,
    background: getStatusColor(status) + '20',
    color: getStatusColor(status)
  });

