import React, { useState, useEffect } from 'react';
import { useLanguage } from '../../contexts/UiContext';
import { toast } from 'react-toastify';
import axios from 'axios';

const AdminNotifications = () => {
  const { language, theme } = useLanguage();
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [filterType, setFilterType] = useState('all');
  const [filterPriority, setFilterPriority] = useState('all');

  const isDark = theme === 'dark';
  const t = language === 'en' ? englishTranslations : amharicTranslations;

  useEffect(() => {
    fetchNotifications();
  }, []);

  const fetchNotifications = async () => {
    setLoading(true);
    try {
      const response = await axios.get('/api/notifications');
      setNotifications(response.data.notifications || []);
    } catch (error) {
      setNotifications([]);
      toast.error('Failed to load notifications');
    }
    setLoading(false);
  };

  const handleMarkRead = async (id) => {
    try {
      await axios.put(`/api/notifications/${id}/read`);
      setNotifications(notifications.map(n => n.id === id ? { ...n, is_read: true } : n));
      toast.success(t.markedRead);
    } catch (error) {
      toast.error(t.markFailed || 'Failed to mark as read');
    }
  };

  const handleMarkAllRead = async () => {
    try {
      await axios.put('/api/notifications/read-all');
      setNotifications(notifications.map(n => ({ ...n, is_read: true })));
      toast.success(t.markedAllRead);
    } catch (error) {
      toast.error(t.markAllFailed || 'Failed to mark all as read');
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm(t.confirmDelete)) return;
    try {
      await axios.delete(`/api/notifications/${id}`);
      setNotifications(notifications.filter(n => n.id !== id));
      toast.success(t.deleted);
    } catch (error) {
      toast.error(t.deleteFailed || 'Failed to delete notification');
    }
  };

  const handleDeleteAll = async () => {
    if (!window.confirm(t.confirmDeleteAll)) return;
    try {
      await axios.delete('/api/notifications/all');
      setNotifications([]);
      toast.success(t.deletedAll);
    } catch (error) {
      toast.error(t.deleteAllFailed || 'Failed to delete notifications');
    }
  };

  const getPriorityColor = (priority) => {
    const colors = { 'Low': '#48bb78', 'Medium': '#4299e1', 'High': '#ed8936', 'Urgent': '#fc8181' };
    return colors[priority] || '#a0aec0';
  };

  const getPriorityLabel = (priority) => {
    const labels = { 'Low': t.low, 'Medium': t.medium, 'High': t.high, 'Urgent': t.urgent };
    return labels[priority] || priority;
  };

  const getTypeEmoji = (type) => {
    const emojis = {
      'Maintenance': '🔧',
      'Assignment': '📋',
      'Alert': '🚨',
      'Report': '📊',
      'System': '⚙️',
      'Reminder': '⏰',
      'Approval': '✅',
      'Security': '🔒',
      'Backup': '💾',
      'Inventory': '📦'
    };
    return emojis[type] || '📬';
  };

  const getFilteredNotifications = () => {
    let filtered = notifications;

    // Filter by read/unread
    if (filter === 'unread') {
      filtered = filtered.filter(n => !n.is_read);
    } else if (filter === 'read') {
      filtered = filtered.filter(n => n.is_read);
    }

    // Filter by type
    if (filterType !== 'all') {
      filtered = filtered.filter(n => n.type === filterType);
    }

    // Filter by priority
    if (filterPriority !== 'all') {
      filtered = filtered.filter(n => n.priority === filterPriority);
    }

    // Search
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase();
      filtered = filtered.filter(n =>
        n.title.toLowerCase().includes(query) ||
        n.message.toLowerCase().includes(query) ||
        n.type.toLowerCase().includes(query)
      );
    }

    return filtered;
  };

  const clearFilters = () => {
    setFilter('all');
    setFilterType('all');
    setFilterPriority('all');
    setSearchQuery('');
  };

  const getUniqueTypes = () => {
    const types = new Set(notifications.map(n => n.type));
    return ['all', ...Array.from(types)];
  };

  const getUniquePriorities = () => {
    const priorities = new Set(notifications.map(n => n.priority));
    return ['all', ...Array.from(priorities)];
  };

