      fontSize: '0.85rem',
      color: isDark ? '#8896b0' : '#4a5568'
    },
    statItem: {
      display: 'flex',
      alignItems: 'center',
      gap: '4px'
    },
    statNumber: {
      fontWeight: 700,
      color: isDark ? '#c8dcf5' : '#1a365d'
    },
    link: {
      color: '#2b6cb0',
      textDecoration: 'none',
      fontWeight: 500
    }
  };

  const filtered = getFilteredNotifications();
  const unreadCount = notifications.filter(n => !n.is_read).length;
  const totalCount = notifications.length;

  return (
    <div style={styles.container}>
      {/* Header */}
      <div style={styles.header}>
        <div>
          <h1 style={styles.title}>
            🔔 {t.notifications}
            {unreadCount > 0 && (
              <span style={styles.titleBadge}>{unreadCount} {t.unread}</span>
            )}
          </h1>
        </div>
        <div style={styles.controls}>
          {unreadCount > 0 && (
            <button style={styles.button('#4299e1')} onClick={handleMarkAllRead}>
              ✅ {t.markAllRead}
            </button>
          )}
          {totalCount > 0 && (
            <button style={styles.button('#fc8181')} onClick={handleDeleteAll}>
              🗑️ {t.deleteAll}
            </button>
          )}
          <button style={styles.button('#a0aec0')} onClick={fetchNotifications}>
            🔄 {t.refresh}
          </button>
        </div>
      </div>

      {/* Stats Bar */}
      {totalCount > 0 && (
        <div style={styles.statsBar}>
          <span style={styles.statItem}>
            📬 {t.total}: <span style={styles.statNumber}>{totalCount}</span>
          </span>
          <span style={styles.statItem}>
            🔵 {t.unread}: <span style={styles.statNumber}>{unreadCount}</span>
          </span>
          <span style={styles.statItem}>
            ✅ {t.read}: <span style={styles.statNumber}>{totalCount - unreadCount}</span>
          </span>
        </div>
      )}

      {/* Filter Bar */}
      <div style={styles.filterBar}>
        <input
          type="text"
          style={styles.searchInput}
          placeholder={t.searchPlaceholder}
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
        />
        <select style={styles.select} value={filter} onChange={(e) => setFilter(e.target.value)}>
          <option value="all">{t.allNotifications}</option>
          <option value="unread">{t.unreadOnly}</option>
          <option value="read">{t.readOnly}</option>
        </select>
        <select style={styles.select} value={filterType} onChange={(e) => setFilterType(e.target.value)}>
          <option value="all">{t.allTypes}</option>
          {getUniqueTypes().filter(t => t !== 'all').map(type => (
            <option key={type} value={type}>{type}</option>
          ))}
        </select>
        <select style={styles.select} value={filterPriority} onChange={(e) => setFilterPriority(e.target.value)}>
          <option value="all">{t.allPriorities}</option>
          <option value="Low">{t.low}</option>
          <option value="Medium">{t.medium}</option>
          <option value="High">{t.high}</option>
          <option value="Urgent">{t.urgent}</option>
        </select>
        {(filter !== 'all' || filterType !== 'all' || filterPriority !== 'all' || searchQuery) && (
          <button style={styles.button('#a0aec0')} onClick={clearFilters}>
            {t.clearFilters}
          </button>
        )}
      </div>

      {/* Notification List */}
      {loading ? (
        <div style={styles.emptyState}>⏳ {t.loading}</div>
      ) : totalCount === 0 ? (
        <div style={styles.emptyState}>
          <div style={styles.emptyIcon}>📬</div>
          <h3 style={{ color: isDark ? '#c8dcf5' : '#1a365d', marginBottom: '8px' }}>{t.noNotifications}</h3>
          <p>{t.noNotificationsDesc}</p>
        </div>
      ) : filtered.length === 0 ? (
        <div style={styles.emptyState}>
          <div style={styles.emptyIcon}>🔍</div>
          <h3 style={{ color: isDark ? '#c8dcf5' : '#1a365d', marginBottom: '8px' }}>{t.noResults}</h3>
          <p>{t.noResultsDesc}</p>
          <button style={{ ...styles.button('#2b6cb0'), marginTop: '12px' }} onClick={clearFilters}>
            {t.clearFilters}
          </button>
        </div>
      ) : (
        filtered.map(notification => (
          <div
            key={notification.id}
            style={styles.card(notification.is_read)}
            onClick={() => !notification.is_read && handleMarkRead(notification.id)}
          >
            <div style={styles.cardHeader}>
              <div style={styles.cardContent}>
                <div style={styles.cardTitle}>
                  {!notification.is_read && <span style={styles.unreadDot} />}
                  <span>{getTypeEmoji(notification.type)}</span>
                  {notification.title}
                  <span style={styles.priorityBadge(notification.priority)}>
                    {getPriorityLabel(notification.priority)}
                  </span>
                  <span style={styles.typeBadge}>{notification.type}</span>
                </div>
                <div style={styles.cardMessage}>{notification.message}</div>
                <div style={styles.cardMeta}>
                  <span>🕐 {new Date(notification.created_at).toLocaleString()}</span>
                  {notification.sender && <span>👤 {t.from}: {notification.sender}</span>}
                  {!notification.is_read && <span style={{ color: '#4299e1', fontSize: '0.7rem' }}>● {t.new}</span>}
                  {notification.link && (
                    <a
                      href={notification.link}
                      style={styles.link}
                      onClick={(e) => e.stopPropagation()}
                    >
                      {t.viewDetails} →
                    </a>
                  )}
                </div>
              </div>
              <div style={styles.actionButtons}>
                {!notification.is_read && (
                  <button
                    style={styles.actionBtn('#4299e1')}
                    onClick={(e) => { e.stopPropagation(); handleMarkRead(notification.id); }}
                  >
                    {t.markRead}
                  </button>
                )}
                <button
                  style={styles.actionBtn('#fc8181')}
                  onClick={(e) => { e.stopPropagation(); handleDelete(notification.id); }}
                >
                  🗑️
                </button>
              </div>
            </div>
          </div>
        ))
      )}
    </div>
  );
};

