import React, { useState, useEffect } from 'react';
import { useLanguage } from '../../contexts/UiContext';
import { toast } from 'react-toastify';
import axios from 'axios';

const AdminRFIDTracking = () => {
  const { language, theme } = useLanguage();
  const [logs, setLogs] = useState([]);
  const [realTimeData, setRealTimeData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({ totalScans: 0, anomalies: 0, activeAssets: 0, readers: 0 });
  const [filter, setFilter] = useState('');
  const [viewMode, setViewMode] = useState('monitor'); // 'monitor' | 'devices' | 'history'
  const [devices, setDevices] = useState([]);
  const [showDeviceModal, setShowDeviceModal] = useState(false);
  const [editingDevice, setEditingDevice] = useState(null);
  const [deviceForm, setDeviceForm] = useState({
    name: '',
    ip_address: '',
    location: '',
    status: 'Active',
    reader_id: ''
  });
  const [historyFilter, setHistoryFilter] = useState('');
  const [historyDateRange, setHistoryDateRange] = useState({ start: '', end: '' });

  const isDark = theme === 'dark';
  const t = language === 'en' ? englishTranslations : amharicTranslations;

  useEffect(() => {
    fetchLogs();
    fetchDevices();
  }, []);

  const fetchLogs = async () => {
    setLoading(true);
    try {
      const response = await axios.get('/api/rfid', { params: { limit: 200 } });
      const data = response.data.logs || [];
      setLogs(data);
      setStats({
        totalScans: data.length,
        anomalies: data.filter(l => l.isAnomaly).length,
        activeAssets: new Set(data.map(l => l.asset_id)).size,
        readers: new Set(data.map(l => l.reader_id)).size
      });
    } catch (error) {
      toast.error('Failed to load RFID data');
    }
    setLoading(false);
  };

  const fetchDevices = async () => {
    setDevices([]);
  };

  const handleDeviceSubmit = async (e) => {
    e.preventDefault();
    try {
      throw new Error('RFID device management is not available in the backend API');
    } catch (error) {
      toast.error(error.response?.data?.message || error.message || t.deviceSaveFailed);
    }
  };

  const handleDeleteDevice = async (id) => {
    if (!window.confirm(t.confirmDeleteDevice)) return;
    try {
      throw new Error('RFID device management is not available in the backend API');
    } catch (error) {
      toast.error(error.response?.data?.message || error.message || t.deviceDeleteFailed);
    }
  };

  const handleToggleDeviceStatus = async (id, currentStatus) => {
    const newStatus = currentStatus === 'Active' ? 'Inactive' : 'Active';
    try {
      await axios.put(`/api/rfid/devices/${id}/status`, { status: newStatus });
      toast.success(t.deviceStatusChanged);
      fetchDevices();
    } catch (error) {
      toast.error(t.deviceStatusFailed);
    }
  };

  const handleTestConnection = async (id) => {
    try {
      const response = await axios.post(`/api/rfid/devices/${id}/test`);
      if (response.data.success) {
        toast.success(t.connectionTestSuccess);
      } else {
        toast.error(t.connectionTestFailed);
      }
    } catch (error) {
      toast.error(t.connectionTestFailed);
    }
  };

  const handleEditDevice = (device) => {
    setEditingDevice(device);
    setDeviceForm({
      name: device.name,
      ip_address: device.ip_address,
      location: device.location,
      status: device.status,
      reader_id: device.reader_id || ''
    });
    setShowDeviceModal(true);
  };

  const getStatusColor = (isAnomaly) => isAnomaly ? '#fc8181' : '#48bb78';
  const getDeviceStatusColor = (status) => status === 'Active' ? '#48bb78' : '#fc8181';

  const filteredLogs = logs.filter(log =>
    log.asset_name?.toLowerCase().includes(filter.toLowerCase()) ||
    log.rfid_tag?.toLowerCase().includes(filter.toLowerCase()) ||
    log.reader_location?.toLowerCase().includes(filter.toLowerCase())
  );

  const filteredHistory = logs.filter(log => {
    const match = log.asset_name?.toLowerCase().includes(historyFilter.toLowerCase()) ||
                  log.rfid_tag?.toLowerCase().includes(historyFilter.toLowerCase());
    if (!historyDateRange.start && !historyDateRange.end) return match;
    const logDate = new Date(log.timestamp);
    const start = historyDateRange.start ? new Date(historyDateRange.start) : null;
    const end = historyDateRange.end ? new Date(historyDateRange.end) : null;
    if (start && logDate < start) return false;
    if (end) {
      const endDate = new Date(end);
      endDate.setHours(23, 59, 59);
      if (logDate > endDate) return false;
    }
    return match;
  });

