      borderRadius: '12px',
      border: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`
    },
    deviceCard: {
      background: isDark ? '#1e2d45' : '#ffffff',
      padding: '16px 20px',
      borderRadius: '12px',
      border: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      marginBottom: '12px',
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      flexWrap: 'wrap',
      gap: '12px',
      boxShadow: isDark ? '0 2px 8px rgba(0,0,0,0.2)' : '0 2px 8px rgba(0,0,100,0.04)'
    },
    deviceInfo: {
      display: 'flex',
      gap: '20px',
      flexWrap: 'wrap',
      alignItems: 'center'
    },
    deviceName: {
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontWeight: 600,
      fontSize: '1rem'
    },
    deviceDetail: {
      color: isDark ? '#8896b0' : '#4a5568',
      fontSize: '0.85rem'
    },
    statusBadge: (status) => ({
      display: 'inline-block',
      padding: '4px 12px',
      borderRadius: '20px',
      fontSize: '0.75rem',
      fontWeight: 600,
      background: getDeviceStatusColor(status) + '20',
      color: getDeviceStatusColor(status)
    }),
    dateRange: {
      display: 'flex',
      gap: '8px',
      alignItems: 'center',
      flexWrap: 'wrap'
    },
    dateInput: {
      padding: '8px 12px',
      borderRadius: '8px',
      border: `1px solid ${isDark ? '#32465f' : '#d0d8e8'}`,
      background: isDark ? '#0d1b2a' : '#ffffff',
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.85rem'
    },
    movementArrow: {
      color: isDark ? '#63b3ed' : '#2b6cb0',
      fontWeight: 700,
      margin: '0 8px'
    }
  };

  return (
    <div style={styles.container}>
      {/* Header */}
      <div style={styles.header}>
        <div>
          <h1 style={styles.title}>📡 {t.rfidTracking}</h1>
          <p style={styles.subtitle}>
            {viewMode === 'monitor' && t.monitorDescription}
            {viewMode === 'devices' && t.devicesDescription}
            {viewMode === 'history' && t.historyDescription}
          </p>
        </div>
        <div>
          {viewMode === 'devices' && (
            <button style={styles.button('#805ad5')} onClick={() => { setEditingDevice(null); setDeviceForm({ name: '', ip_address: '', location: '', status: 'Active', reader_id: '' }); setShowDeviceModal(true); }}>
              ➕ {t.addDevice}
            </button>
          )}
          <button style={{ ...styles.button('#a0aec0'), marginLeft: '8px' }} onClick={() => { fetchLogs(); fetchDevices(); }}>
            🔄 {t.refresh}
          </button>
        </div>
      </div>

      {/* View Tabs */}
      <div style={styles.viewTabs}>
        <button style={styles.viewTab(viewMode === 'monitor')} onClick={() => setViewMode('monitor')}>
          📡 {t.monitor}
        </button>
        <button style={styles.viewTab(viewMode === 'devices')} onClick={() => setViewMode('devices')}>
          📟 {t.devices}
        </button>
        <button style={styles.viewTab(viewMode === 'history')} onClick={() => setViewMode('history')}>
          📜 {t.history}
        </button>
      </div>

      {/* Stats */}
      <div style={styles.statsGrid}>
        <div style={styles.statCard}>
          <div style={styles.statNumber}>{stats.totalScans}</div>
          <div style={styles.statLabel}>{t.totalScans}</div>
        </div>
        <div style={styles.statCard}>
          <div style={{ ...styles.statNumber, color: '#fc8181' }}>{stats.anomalies}</div>
          <div style={styles.statLabel}>{t.anomalies}</div>
        </div>
        <div style={styles.statCard}>
          <div style={{ ...styles.statNumber, color: '#48bb78' }}>{stats.activeAssets}</div>
          <div style={styles.statLabel}>{t.activeAssets}</div>
        </div>
        <div style={styles.statCard}>
          <div style={{ ...styles.statNumber, color: '#4299e1' }}>{stats.readers}</div>
          <div style={styles.statLabel}>{t.readers}</div>
        </div>
      </div>

      {/* === VIEW: MONITOR === */}
      {viewMode === 'monitor' && (
        <>
          <div style={styles.realTimeCard}>
            <h3 style={{ color: isDark ? '#c8dcf5' : '#1a365d', marginBottom: '12px' }}>
              🔴 {t.realTimeFeed}
              <span style={{ ...styles.realTimeTag, marginLeft: '12px' }}>
                {t.live}
              </span>
            </h3>
            <div style={{ maxHeight: '180px', overflow: 'auto' }}>
              {realTimeData.length === 0 ? (
                <p style={{ textAlign: 'center', color: isDark ? '#8896b0' : '#4a5568' }}>{t.waitingForScans}</p>
              ) : (
                realTimeData.map((data, index) => (
                  <div key={index} style={styles.realTimeItem}>
                    <span>
                      <strong>{data.assetName || data.asset}</strong>
                      <span style={{ ...styles.realTimeTag, marginLeft: '8px' }}>
                        {data.rfidTag || data.rfid}
                      </span>
                    </span>
                    <span>
                      📍 {data.readerLocation || data.location}
                    </span>
                    <span style={{ color: getStatusColor(data.isAnomaly), fontWeight: 600 }}>
                      {data.isAnomaly ? '⚠️ ' + t.anomaly : '✅ ' + t.normal}
                    </span>
                    <span style={{ fontSize: '0.8rem', color: isDark ? '#8896b0' : '#4a5568' }}>
                      {new Date(data.timestamp).toLocaleTimeString()}
                    </span>
                  </div>
                ))
              )}
            </div>
          </div>

          <div style={styles.controls}>
            <input
              type="text"
              style={styles.input}
              placeholder={t.searchPlaceholder}
              value={filter}
              onChange={(e) => setFilter(e.target.value)}
            />
          </div>

          {loading ? (
            <div style={styles.emptyState}>⏳ {t.loading}</div>
          ) : (
            <div style={{ overflowX: 'auto' }}>
              <table style={styles.table}>
                <thead>
                  <tr>
                    <th style={styles.th}>{t.time}</th>
                    <th style={styles.th}>{t.asset}</th>
                    <th style={styles.th}>{t.rfidTag}</th>
                    <th style={styles.th}>{t.reader}</th>
                    <th style={styles.th}>{t.location}</th>
                    <th style={styles.th}>{t.status}</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredLogs.length === 0 ? (
                    <tr><td colSpan="6" style={styles.emptyState}>{t.noLogs}</td></tr>
                  ) : (
                    filteredLogs.slice(0, 100).map(log => (
                      <tr key={log.id}>
                        <td style={styles.td}>{new Date(log.timestamp).toLocaleString()}</td>
                        <td style={styles.td}>{log.asset_name || '-'}</td>
                        <td style={styles.td}>{log.rfid_tag || '-'}</td>
                        <td style={styles.td}>{log.reader_id || '-'}</td>
                        <td style={styles.td}>{log.reader_location || '-'}</td>
                        <td style={styles.td}>
                          <span style={{ color: getStatusColor(log.isAnomaly) }}>
                            {log.isAnomaly ? '⚠️ ' + t.anomaly : '✅ ' + t.normal}
                          </span>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          )}
        </>
      )}

      {/* === VIEW: DEVICES === */}
      {viewMode === 'devices' && (
        <>
          {loading ? (
            <div style={styles.emptyState}>⏳ {t.loading}</div>
          ) : devices.length === 0 ? (
            <div style={styles.emptyState}>{t.noDevices}</div>
          ) : (
            devices.map(device => (
              <div key={device.id} style={styles.deviceCard}>
                <div style={styles.deviceInfo}>
                  <span style={styles.deviceName}>📟 {device.name}</span>
                  <span style={styles.deviceDetail}>🆔 {device.reader_id || device.id}</span>
                  <span style={styles.deviceDetail}>🌐 {device.ip_address}</span>
                  <span style={styles.deviceDetail}>📍 {device.location || '-'}</span>
                  <span style={styles.deviceDetail}>
                    {t.lastConnected}: {device.last_connected ? new Date(device.last_connected).toLocaleString() : t.never}
                  </span>
                  <span style={styles.statusBadge(device.status)}>{device.status}</span>
                </div>
                <div style={{ display: 'flex', gap: '4px', flexWrap: 'wrap' }}>
                  <button style={styles.actionButton('#48bb78')} onClick={() => handleToggleDeviceStatus(device.id, device.status)}>
                    {device.status === 'Active' ? '🔴 ' + t.deactivate : '🟢 ' + t.activate}
