                  <button style={styles.actionButton('#4299e1')} onClick={() => handleTestConnection(device.id)}>
                    📡 {t.testConnection}
                  </button>
                  <button style={styles.actionButton('#ed8936')} onClick={() => handleEditDevice(device)}>
                    ✏️ {t.edit}
                  </button>
                  <button style={styles.actionButton('#fc8181')} onClick={() => handleDeleteDevice(device.id)}>
                    🗑️ {t.delete}
                  </button>
                </div>
              </div>
            ))
          )}
        </>
      )}

      {/* === VIEW: HISTORY === */}
      {viewMode === 'history' && (
        <>
          <div style={styles.controls}>
            <input
              type="text"
              style={styles.input}
              placeholder={t.searchHistory}
              value={historyFilter}
              onChange={(e) => setHistoryFilter(e.target.value)}
            />
            <div style={styles.dateRange}>
              <input
                type="date"
                style={styles.dateInput}
                value={historyDateRange.start}
                onChange={(e) => setHistoryDateRange({ ...historyDateRange, start: e.target.value })}
              />
              <span style={{ color: isDark ? '#8896b0' : '#4a5568' }}>{t.to}</span>
              <input
                type="date"
                style={styles.dateInput}
                value={historyDateRange.end}
                onChange={(e) => setHistoryDateRange({ ...historyDateRange, end: e.target.value })}
              />
              <button style={styles.button('#a0aec0')} onClick={() => setHistoryDateRange({ start: '', end: '' })}>
                {t.clear}
              </button>
            </div>
          </div>

          {loading ? (
            <div style={styles.emptyState}>⏳ {t.loading}</div>
