            <div style={{ overflowX: 'auto' }}>
              <table style={styles.table}>
                <thead>
                  <tr>
                    <th style={styles.th}>{t.dateTime}</th>
                    <th style={styles.th}>{t.asset}</th>
                    <th style={styles.th}>{t.rfidTag}</th>
                    <th style={styles.th}>{t.reader}</th>
                    <th style={styles.th}>{t.previousLocation}</th>
                    <th style={styles.th}>{t.newLocation}</th>
                    <th style={styles.th}>{t.movementType}</th>
                    <th style={styles.th}>{t.status}</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredHistory.length === 0 ? (
                    <tr><td colSpan="8" style={styles.emptyState}>{t.noHistoryRecords}</td></tr>
                  ) : (
                    filteredHistory.map(log => {
                      const prevLocation = log.previous_location || log.reader_location || '-';
                      const newLocation = log.new_location || log.reader_location || '-';
                      const movementType = log.movement_type || (log.previous_location && log.new_location && log.previous_location !== log.new_location ? t.transferred : t.scanned);
                      return (
                        <tr key={log.id}>
                          <td style={styles.td}>{new Date(log.timestamp).toLocaleString()}</td>
                          <td style={styles.td}>{log.asset_name || '-'}</td>
                          <td style={styles.td}>{log.rfid_tag || '-'}</td>
                          <td style={styles.td}>{log.reader_id || '-'}</td>
                          <td style={styles.td}>{prevLocation}</td>
                          <td style={styles.td}>
                            {prevLocation !== newLocation ? (
                              <>
                                <span style={styles.movementArrow}>→</span>
                                {newLocation}
                              </>
                            ) : newLocation}
                          </td>
                          <td style={styles.td}>
                            <span style={styles.realTimeTag}>
                              {movementType === t.transferred ? '🔄 ' : '📡 '}
                              {movementType}
                            </span>
                          </td>
                          <td style={styles.td}>
                            <span style={{ color: getStatusColor(log.isAnomaly) }}>
                              {log.isAnomaly ? '⚠️ ' + t.anomaly : '✅ ' + t.normal}
                            </span>
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>
          )}
        </>
      )}

      {/* Device Modal */}
      {showDeviceModal && (
        <div style={styles.modal} onClick={() => setShowDeviceModal(false)}>
          <div style={styles.modalContent} onClick={e => e.stopPropagation()}>
            <h2 style={styles.modalTitle}>
              {editingDevice ? '✏️ ' + t.editDevice : '➕ ' + t.addDevice}
            </h2>
            <form onSubmit={handleDeviceSubmit}>
              <input
                style={styles.modalInput}
                placeholder={t.deviceName}
                value={deviceForm.name}
                onChange={(e) => setDeviceForm({ ...deviceForm, name: e.target.value })}
                required
              />
              <input
                style={styles.modalInput}
                placeholder={t.ipAddress}
                value={deviceForm.ip_address}
                onChange={(e) => setDeviceForm({ ...deviceForm, ip_address: e.target.value })}
                required
              />
              <input
                style={styles.modalInput}
                placeholder={t.locationPlaceholder}
                value={deviceForm.location}
                onChange={(e) => setDeviceForm({ ...deviceForm, location: e.target.value })}
              />
              <input
                style={styles.modalInput}
                placeholder={t.readerId}
                value={deviceForm.reader_id}
                onChange={(e) => setDeviceForm({ ...deviceForm, reader_id: e.target.value })}
              />
              <select
                style={styles.modalSelect}
                value={deviceForm.status}
                onChange={(e) => setDeviceForm({ ...deviceForm, status: e.target.value })}
              >
                <option value="Active">{t.active}</option>
                <option value="Inactive">{t.inactive}</option>
                <option value="Maintenance">{t.maintenance}</option>
              </select>
              <div style={{ display: 'flex', gap: '12px', marginTop: '12px' }}>
                <button type="submit" style={styles.button('#805ad5')}>
                  {editingDevice ? t.update : t.add}
                </button>
                <button type="button" style={{ ...styles.button('#fc8181') }} onClick={() => setShowDeviceModal(false)}>
                  {t.cancel}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

