import React, { useState, useEffect, useRef } from 'react';
import { useLanguage } from '../../contexts/UiContext';
import { toast } from 'react-toastify';
import * as XLSX from 'xlsx';
import axios from 'axios';
import jsPDF from 'jspdf';
import 'jspdf-autotable';

const AdminReports = () => {
  const { language, theme } = useLanguage();
  const [loading, setLoading] = useState(true);
  const [reportType, setReportType] = useState('assets');
  const [reportCategory, setReportCategory] = useState('all');
  const [reportData, setReportData] = useState([]);
  const [summary, setSummary] = useState({});
  const [filters, setFilters] = useState({
    department: '',
    category: '',
    location: '',
    status: '',
    dateFrom: '',
    dateTo: ''
  });
  const [departments, setDepartments] = useState([]);
  const [categories, setCategories] = useState([]);
  const [locations, setLocations] = useState([]);
  const printRef = useRef();

  const isDark = theme === 'dark';
  const t = language === 'en' ? englishTranslations : amharicTranslations;

  // Report type groups
  const reportGroups = {
    assets: { label: 'Asset Reports', types: ['all', 'by_department', 'by_category', 'by_location', 'damaged', 'missing', 'disposed', 'active', 'under_maintenance'] },
    maintenance: { label: 'Maintenance Reports', types: ['all', 'pending', 'completed', 'cost', 'by_department', 'by_asset', 'technician_performance'] },
    rfid: { label: 'RFID Reports', types: ['asset_movement', 'rfid_activity', 'unauthorized_movement', 'location_history', 'device_activity'] },
    audit: { label: 'Audit Reports', types: ['all', 'asset_actions', 'user_actions', 'maintenance_actions', 'system_actions'] },
    financial: { label: 'Financial Reports', types: ['depreciation', 'total_value', 'by_category', 'by_department'] }
  };

  useEffect(() => {
    fetchFilters();
    fetchReport();
  }, [reportType, reportCategory, filters]);

  const fetchFilters = async () => {
    try {
      const [deptsRes, catsRes, locsRes] = await Promise.all([
        axios.get('/api/departments'),
        axios.get('/api/categories'),
        axios.get('/api/locations')
      ]);
      setDepartments(deptsRes.data.departments || []);
      setCategories(catsRes.data.categories || []);
      setLocations(locsRes.data.locations || []);
    } catch (error) {
      console.error('Failed to fetch filters');
    }
  };

  const fetchReport = async () => {
    setLoading(true);
    try {
      let endpoint = '';
      const params = new URLSearchParams();

      // Build endpoint and params based on report type
      switch (reportType) {
        case 'assets':
          endpoint = '/api/assets';
          params.append('limit', '1000');
          if (filters.department) params.append('department_id', filters.department);
          if (filters.category) params.append('category', filters.category);
          if (filters.location) params.append('location', filters.location);
          if (filters.status) params.append('status', filters.status);
          if (reportCategory === 'damaged') params.append('condition', 'Damaged');
          if (reportCategory === 'missing') params.append('status', 'Lost');
          if (reportCategory === 'disposed') params.append('status', 'Disposed');
          if (reportCategory === 'active') params.append('status', 'Active');
          if (reportCategory === 'under_maintenance') params.append('status', 'Under-Maintenance');
          break;

        case 'maintenance':
          endpoint = '/api/maintenance';
          params.append('limit', '1000');
          if (filters.department) params.append('department_id', filters.department);
          if (filters.dateFrom) params.append('from', filters.dateFrom);
          if (filters.dateTo) params.append('to', filters.dateTo);
          if (reportCategory === 'pending') params.append('status', 'Pending');
          if (reportCategory === 'completed') params.append('status', 'Completed');
          break;

        case 'rfid':
          endpoint = '/api/rfid';
          params.append('limit', '1000');
          if (filters.dateFrom) params.append('from', filters.dateFrom);
          if (filters.dateTo) params.append('to', filters.dateTo);
          if (reportCategory === 'unauthorized_movement') params.append('anomaly', 'true');
          break;

        case 'audit':
          endpoint = '/api/finance/audit';
          params.append('limit', '1000');
          if (filters.dateFrom) params.append('from', filters.dateFrom);
          if (filters.dateTo) params.append('to', filters.dateTo);
          if (reportCategory === 'asset_actions') params.append('module', 'assets');
          if (reportCategory === 'user_actions') params.append('module', 'users');
          if (reportCategory === 'maintenance_actions') params.append('module', 'maintenance');
          break;

        case 'financial':
          endpoint = '/api/finance/valuation';
          params.append('limit', '1000');
          if (filters.department) params.append('department_id', filters.department);
          if (filters.category) params.append('category', filters.category);
          break;

        default:
          endpoint = '/api/assets';
          params.append('limit', '1000');
      }

      const response = await axios.get(`${endpoint}?${params.toString()}`);
      let data = response.data.assets || response.data.logs || response.data.requests || response.data.audits || response.data.data || [];
      setReportData(data);
      calculateSummary(data);
    } catch (error) {
      toast.error(t.loadFailed);
      setReportData([]);
      calculateSummary([]);
    }
    setLoading(false);
  };

  const calculateSummary = (data) => {
    if (reportType === 'assets') {
      const total = data.length;
      const byStatus = data.reduce((acc, item) => {
        acc[item.status] = (acc[item.status] || 0) + 1;
        return acc;
      }, {});
      const totalValue = data.reduce((sum, item) => sum + (item.current_value || 0), 0);
      setSummary({ total, byStatus, totalValue });
    } else if (reportType === 'maintenance') {
      const total = data.length;
      const byStatus = data.reduce((acc, item) => {
        acc[item.status] = (acc[item.status] || 0) + 1;
        return acc;
      }, {});
      const totalCost = data.reduce((sum, item) => sum + (item.actual_cost || 0), 0);
      setSummary({ total, byStatus, totalCost });
    } else if (reportType === 'rfid') {
      const total = data.length;
      const anomalies = data.filter(item => item.isAnomaly).length;
      const uniqueAssets = new Set(data.map(item => item.asset_id)).size;
      setSummary({ total, anomalies, uniqueAssets });
    } else if (reportType === 'audit') {
      const total = data.length;
      const byAction = data.reduce((acc, item) => {
        acc[item.action] = (acc[item.action] || 0) + 1;
        return acc;
      }, {});
      setSummary({ total, byAction });
    } else if (reportType === 'financial') {
      const total = data.length;
      const totalValue = data.reduce((sum, item) => sum + (item.current_value || 0), 0);
      const totalPurchase = data.reduce((sum, item) => sum + (item.purchase_cost || 0), 0);
      const depreciation = totalPurchase - totalValue;
      setSummary({ total, totalValue, totalPurchase, depreciation });
    }
  };

  const exportToExcel = () => {
    const exportData = getExportData();
    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, reportType);
    XLSX.writeFile(wb, `${reportType}_report_${new Date().toISOString().split('T')[0]}.xlsx`);
    toast.success(t.exportSuccess);
  };

  const exportToCSV = () => {
    const exportData = getExportData();
    const ws = XLSX.utils.json_to_sheet(exportData);
    const csv = XLSX.utils.sheet_to_csv(ws);
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${reportType}_report_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
    toast.success(t.exportSuccess);
  };

  const exportToPDF = () => {
    const doc = new jsPDF('landscape', 'mm', 'a4');
    const exportData = getExportData();
    const headers = Object.keys(exportData[0] || {});
    const rows = exportData.map(item => Object.values(item));

    doc.text(`${t.reports} - ${getReportLabel()}`, 14, 15);
    doc.text(`${t.generated}: ${new Date().toLocaleString()}`, 14, 22);

    doc.autoTable({
      head: [headers],
      body: rows,
      startY: 30,
      styles: { fontSize: 7 },
      headStyles: { fillColor: [43, 108, 176] }
    });

    doc.save(`${reportType}_report_${new Date().toISOString().split('T')[0]}.pdf`);
    toast.success(t.exportSuccess);
  };

  const handlePrint = () => {
    window.print();
  };

  const getExportData = () => {
    let data = [];
    switch (reportType) {
      case 'assets':
        data = reportData.map(a => ({
          'Asset Tag': a.asset_tag,
          'Name': a.name,
          'Category': a.category || a.category_name || '',
          'Department': a.department_name || '',
          'Status': a.status,
          'Location': a.location || '',
          'Condition': a.condition || '',
          'Purchase Cost': a.purchase_cost || 0,
          'Current Value': a.current_value || 0,
          'Assigned To': a.assigned_to_name || ''
        }));
        break;
      case 'maintenance':
        data = reportData.map(m => ({
          'Request #': m.request_number,
          'Title': m.title,
          'Asset': m.asset_name || '',
          'Status': m.status,
          'Priority': m.priority,
          'Type': m.type,
          'Reported By': m.reported_by_name || '',
          'Created': new Date(m.created_at).toLocaleDateString(),
          'Actual Cost': m.actual_cost || 0
        }));
        break;
      case 'rfid':
        data = reportData.map(r => ({
          'Asset': r.asset_name || '',
          'RFID Tag': r.rfid_tag || '',
          'Reader': r.reader_id || '',
          'Location': r.reader_location || '',
          'Previous Location': r.previous_location || '',
          'New Location': r.new_location || '',
          'Status': r.isAnomaly ? 'Anomaly' : 'Normal',
          'Timestamp': new Date(r.timestamp).toLocaleString()
        }));
        break;
      case 'audit':
        data = reportData.map(a => ({
          'User': a.username,
          'Action': a.action,
          'Module': a.module,
          'Target': a.target_name || '',
          'Status': a.status,
          'IP Address': a.ip_address || '',
          'Timestamp': new Date(a.timestamp).toLocaleString()
        }));
        break;
      case 'financial':
        data = reportData.map(f => ({
          'Asset Tag': f.asset_tag,
          'Name': f.name,
          'Category': f.category || '',
          'Department': f.department_name || '',
          'Purchase Cost': f.purchase_cost || 0,
          'Current Value': f.current_value || 0,
          'Depreciation': (f.purchase_cost || 0) - (f.current_value || 0),
          'Depreciation %': f.purchase_cost > 0 ? ((((f.purchase_cost || 0) - (f.current_value || 0)) / (f.purchase_cost || 0)) * 100).toFixed(1) + '%' : '0%'
        }));
        break;
      default:
        data = reportData;
    }
    return data;
  };

  const getReportLabel = () => {
    const labels = {
      assets: t.assetReports,
      maintenance: t.maintenanceReports,
      rfid: t.rfidReports,
      audit: t.auditReports,
      financial: t.financialReports
    };
    return labels[reportType] || t.assetReports;
  };

  const getCategoryLabel = (cat) => {
    const labels = {
      all: t.allRecords,
      by_department: t.byDepartment,
      by_category: t.byCategory,
      by_location: t.byLocation,
      damaged: t.damaged,
      missing: t.missing,
      disposed: t.disposed,
      active: t.active,
      under_maintenance: t.underMaintenance,
      pending: t.pending,
      completed: t.completed,
      cost: t.cost,
      by_asset: t.byAsset,
      technician_performance: t.technicianPerformance,
      asset_movement: t.assetMovement,
      rfid_activity: t.rfidActivity,
      unauthorized_movement: t.unauthorizedMovement,
      location_history: t.locationHistory,
      device_activity: t.deviceActivity,
      asset_actions: t.assetActions,
      user_actions: t.userActions,
      maintenance_actions: t.maintenanceActions,
      system_actions: t.systemActions,
      depreciation: t.depreciation,
      total_value: t.totalValue,
      by_category: t.byCategory,
      by_department: t.byDepartment
    };
    return labels[cat] || cat;
  };

  const renderFilters = () => {
    const filterFields = [];
    if (reportType === 'assets' || reportType === 'financial') {
      filterFields.push(
        <select key="dept" style={styles.select} value={filters.department} onChange={(e) => setFilters({ ...filters, department: e.target.value })}>
          <option value="">{t.allDepartments}</option>
          {departments.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
        </select>,
        <select key="cat" style={styles.select} value={filters.category} onChange={(e) => setFilters({ ...filters, category: e.target.value })}>
          <option value="">{t.allCategories}</option>
          {categories.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
        </select>
      );
    }
    if (reportType === 'assets') {
      filterFields.push(
        <select key="loc" style={styles.select} value={filters.location} onChange={(e) => setFilters({ ...filters, location: e.target.value })}>
          <option value="">{t.allLocations}</option>
          {locations.map(l => <option key={l.id} value={l.name}>{l.name}</option>)}
        </select>,
        <select key="status" style={styles.select} value={filters.status} onChange={(e) => setFilters({ ...filters, status: e.target.value })}>
          <option value="">{t.allStatus}</option>
          <option value="Active">{t.active}</option>
          <option value="In-Use">{t.inUse}</option>
          <option value="Available">{t.available}</option>
          <option value="Under-Maintenance">{t.underMaintenance}</option>
          <option value="Disposed">{t.disposed}</option>
          <option value="Lost">{t.lost}</option>
        </select>
      );
    }
    if (reportType === 'maintenance' || reportType === 'rfid' || reportType === 'audit') {
      filterFields.push(
        <input key="from" type="date" style={styles.dateInput} value={filters.dateFrom} onChange={(e) => setFilters({ ...filters, dateFrom: e.target.value })} />,
        <input key="to" type="date" style={styles.dateInput} value={filters.dateTo} onChange={(e) => setFilters({ ...filters, dateTo: e.target.value })} />
      );
    }
    if (reportType === 'maintenance') {
      filterFields.push(
        <select key="dept2" style={styles.select} value={filters.department} onChange={(e) => setFilters({ ...filters, department: e.target.value })}>
          <option value="">{t.allDepartments}</option>
          {departments.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
        </select>
      );
    }
    return filterFields;
  };

  const renderSummary = () => {
    if (Object.keys(summary).length === 0) return null;
    return (
      <div style={styles.summaryGrid}>
        {reportType === 'assets' && (
          <>
            <div style={styles.summaryCard}><span style={styles.summaryLabel}>{t.totalAssets}</span><span style={styles.summaryValue}>{summary.total}</span></div>
            <div style={styles.summaryCard}><span style={styles.summaryLabel}>{t.totalValue}</span><span style={styles.summaryValue}>${summary.totalValue?.toLocaleString()}</span></div>
            {Object.entries(summary.byStatus || {}).map(([key, value]) => (
              <div key={key} style={styles.summaryCard}><span style={styles.summaryLabel}>{key}</span><span style={styles.summaryValue}>{value}</span></div>
            ))}
          </>
        )}
        {reportType === 'maintenance' && (
          <>
            <div style={styles.summaryCard}><span style={styles.summaryLabel}>{t.totalRequests}</span><span style={styles.summaryValue}>{summary.total}</span></div>
            <div style={styles.summaryCard}><span style={styles.summaryLabel}>{t.totalCost}</span><span style={styles.summaryValue}>${summary.totalCost?.toLocaleString()}</span></div>
            {Object.entries(summary.byStatus || {}).map(([key, value]) => (
              <div key={key} style={styles.summaryCard}><span style={styles.summaryLabel}>{key}</span><span style={styles.summaryValue}>{value}</span></div>
            ))}
          </>
        )}
        {reportType === 'rfid' && (
          <>
            <div style={styles.summaryCard}><span style={styles.summaryLabel}>{t.totalScans}</span><span style={styles.summaryValue}>{summary.total}</span></div>
            <div style={styles.summaryCard}><span style={styles.summaryLabel}>{t.anomalies}</span><span style={styles.summaryValue}>{summary.anomalies}</span></div>
            <div style={styles.summaryCard}><span style={styles.summaryLabel}>{t.uniqueAssets}</span><span style={styles.summaryValue}>{summary.uniqueAssets}</span></div>
          </>
        )}
        {reportType === 'audit' && (
          <>
            <div style={styles.summaryCard}><span style={styles.summaryLabel}>{t.totalAudits}</span><span style={styles.summaryValue}>{summary.total}</span></div>
            {Object.entries(summary.byAction || {}).slice(0, 5).map(([key, value]) => (
              <div key={key} style={styles.summaryCard}><span style={styles.summaryLabel}>{key}</span><span style={styles.summaryValue}>{value}</span></div>
            ))}
          </>
        )}
        {reportType === 'financial' && (
          <>
            <div style={styles.summaryCard}><span style={styles.summaryLabel}>{t.totalAssets}</span><span style={styles.summaryValue}>{summary.total}</span></div>
            <div style={styles.summaryCard}><span style={styles.summaryLabel}>{t.totalPurchase}</span><span style={styles.summaryValue}>${summary.totalPurchase?.toLocaleString()}</span></div>
            <div style={styles.summaryCard}><span style={styles.summaryLabel}>{t.totalCurrentValue}</span><span style={styles.summaryValue}>${summary.totalValue?.toLocaleString()}</span></div>
            <div style={styles.summaryCard}><span style={styles.summaryLabel}>{t.totalDepreciation}</span><span style={styles.summaryValue}>${summary.depreciation?.toLocaleString()}</span></div>
          </>
        )}
      </div>
    );
  };

  const renderTable = () => {
    const headers = getExportData()[0] || {};
    const headerKeys = Object.keys(headers);
    const rows = getExportData();

    return (
      <div style={{ overflowX: 'auto' }} ref={printRef}>
        <table style={styles.table}>
          <thead>
            <tr>
              {headerKeys.map(key => <th key={key} style={styles.th}>{key}</th>)}
            </tr>
          </thead>
          <tbody>
            {rows.slice(0, 200).map((row, index) => (
              <tr key={index}>
                {headerKeys.map(key => <td key={key} style={styles.td}>{row[key] ?? '-'}</td>)}
              </tr>
            ))}
          </tbody>
        </table>
        {rows.length > 200 && (
          <div style={{ textAlign: 'center', padding: '12px', color: isDark ? '#8896b0' : '#4a5568' }}>
            {t.showingFirst} 200 {t.of} {rows.length}
          </div>
        )}
      </div>
    );
  };

  const styles = {
    container: { padding: '20px', maxWidth: '1400px', margin: '0 auto' },
    header: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      flexWrap: 'wrap',
      gap: '16px',
      marginBottom: '24px'
    },
    title: {
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '1.75rem',
      fontWeight: 700,
      margin: 0
    },
    subtitle: {
      color: isDark ? '#8896b0' : '#4a5568',
      fontSize: '0.9rem',
      margin: '4px 0 0 0'
    },
    controls: {
      display: 'flex',
      gap: '10px',
      flexWrap: 'wrap',
      alignItems: 'center'
    },
    select: {
      padding: '8px 14px',
      borderRadius: '8px',
      border: `1px solid ${isDark ? '#32465f' : '#d0d8e8'}`,
      background: isDark ? '#0d1b2a' : '#ffffff',
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.85rem',
      cursor: 'pointer',
      minWidth: '140px'
    },
    dateInput: {
      padding: '8px 14px',
      borderRadius: '8px',
      border: `1px solid ${isDark ? '#32465f' : '#d0d8e8'}`,
      background: isDark ? '#0d1b2a' : '#ffffff',
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.85rem'
    },
    button: (bg, color = 'white') => ({
      padding: '8px 18px',
      background: bg || 'linear-gradient(135deg, #2b6cb0, #4299e1)',
      color: color,
      border: 'none',
      borderRadius: '8px',
      fontWeight: 600,
      cursor: 'pointer',
      fontSize: '0.85rem',
      transition: 'all 0.2s',
      whiteSpace: 'nowrap'
    }),
    filterBar: {
      display: 'flex',
      gap: '10px',
      flexWrap: 'wrap',
      alignItems: 'center',
      padding: '16px',
      background: isDark ? '#1a273a' : '#f7fafc',
      borderRadius: '12px',
      border: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      marginBottom: '16px'
    },
    summaryGrid: {
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))',
      gap: '12px',
      marginBottom: '20px'
    },
    summaryCard: {
      background: isDark ? '#1e2d45' : '#ffffff',
      padding: '12px 16px',
      borderRadius: '10px',
      border: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      textAlign: 'center'
    },
    summaryLabel: {
      display: 'block',
      fontSize: '0.75rem',
      color: isDark ? '#8896b0' : '#4a5568'
    },
    summaryValue: {
      display: 'block',
      fontSize: '1.3rem',
      fontWeight: 700,
      color: isDark ? '#c8dcf5' : '#1a365d'
    },
    table: {
      width: '100%',
      borderCollapse: 'collapse',
      background: isDark ? '#1e2d45' : '#ffffff',
      borderRadius: '12px',
      overflow: 'hidden',
      boxShadow: isDark ? '0 4px 12px rgba(0,0,0,0.3)' : '0 4px 12px rgba(0,0,100,0.06)'
    },
    th: {
      padding: '10px 14px',
      textAlign: 'left',
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontWeight: 600,
      borderBottom: `2px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      background: isDark ? '#141e2d' : '#f7fafc',
      fontSize: '0.8rem',
      whiteSpace: 'nowrap'
    },
    td: {
      padding: '10px 14px',
      borderBottom: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.85rem'
    },
    emptyState: {
      textAlign: 'center',
      padding: '60px 20px',
      color: isDark ? '#8896b0' : '#4a5568',
      background: isDark ? '#1e2d45' : '#ffffff',
      borderRadius: '12px',
      border: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`
    },
    exportGroup: {
      display: 'flex',
      gap: '6px',
      flexWrap: 'wrap'
    },
    tabGroup: {
      display: 'flex',
      gap: '4px',
      flexWrap: 'wrap',
      marginBottom: '16px'
    },
    tab: (active) => ({
      padding: '8px 16px',
      borderRadius: '8px',
      border: 'none',
      cursor: 'pointer',
      fontWeight: 500,
      fontSize: '0.85rem',
      background: active ? (isDark ? '#2b6cb0' : '#2b6cb0') : (isDark ? '#1a273a' : '#e8edf5'),
      color: active ? '#ffffff' : (isDark ? '#8896b0' : '#4a5568'),
      transition: 'all 0.2s'
    })
  };

  return (
    <div style={styles.container}>
      {/* Header */}
      <div style={styles.header}>
        <div>
          <h1 style={styles.title}>📊 {t.reports}</h1>
          <p style={styles.subtitle}>{getReportLabel()} - {getCategoryLabel(reportCategory)}</p>
        </div>
        <div style={styles.controls}>
          <div style={styles.exportGroup}>
            <button style={styles.button('#48bb78')} onClick={exportToExcel}>📥 {t.excel}</button>
            <button style={styles.button('#4299e1')} onClick={exportToCSV}>📄 {t.csv}</button>
            <button style={styles.button('#e53e3e')} onClick={exportToPDF}>📕 {t.pdf}</button>
            <button style={styles.button('#805ad5')} onClick={handlePrint}>🖨️ {t.print}</button>
          </div>
          <button style={styles.button('#a0aec0')} onClick={fetchReport}>🔄 {t.refresh}</button>
        </div>
      </div>

      {/* Report Type Tabs */}
      <div style={styles.tabGroup}>
        {Object.keys(reportGroups).map(key => (
          <button key={key} style={styles.tab(reportType === key)} onClick={() => { setReportType(key); setReportCategory('all'); }}>
            {reportGroups[key].label}
          </button>
        ))}
      </div>

      {/* Category Sub-tabs */}
      <div style={{ ...styles.tabGroup, marginBottom: '16px' }}>
        {reportGroups[reportType]?.types.map(cat => (
          <button key={cat} style={styles.tab(reportCategory === cat)} onClick={() => setReportCategory(cat)}>
            {getCategoryLabel(cat)}
          </button>
        ))}
      </div>

      {/* Filters */}
      <div style={styles.filterBar}>
        {renderFilters()}
        <button style={styles.button('linear-gradient(135deg, #2b6cb0, #4299e1)')} onClick={fetchReport}>
          🔍 {t.applyFilters}
        </button>
        <button style={styles.button('#a0aec0')} onClick={() => {
          setFilters({ department: '', category: '', location: '', status: '', dateFrom: '', dateTo: '' });
          setReportCategory('all');
        }}>
          {t.clearFilters}
        </button>
      </div>

      {/* Summary */}
      {!loading && renderSummary()}

      {/* Data Table */}
      {loading ? (
        <div style={styles.emptyState}>⏳ {t.loading}</div>
      ) : reportData.length === 0 ? (
        <div style={styles.emptyState}>{t.noData}</div>
      ) : (
        renderTable()
      )}
    </div>
  );
};

