import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useLanguage } from '../../contexts/UiContext';
import { toast } from 'react-toastify';
import axios from 'axios';

const AdminSettings = () => {
  const { user, updateUser } = useAuth();
  const { language, theme } = useLanguage();
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState('system'); // 'system' | 'security' | 'profile'
  const fileInputRef = useRef(null);

  // System Settings
  const [settings, setSettings] = useState({
    university_name: 'Smart University',
    logo_url: '',
    address: '123 University Avenue, Campus City',
    contact_phone: '+251911000000',
    contact_email: 'info@university.edu',
    asset_code_format: 'AST-{YYYY}-{SEQ}',
    default_currency: 'USD',
    date_format: 'MM/DD/YYYY',
    notification_enabled: true,
    notification_email: 'admin@university.edu',
    notification_sms: false,
    timezone: 'Africa/Addis_Ababa'
  });

  // Security Settings
  const [securitySettings, setSecuritySettings] = useState({
    password_min_length: 8,
    password_require_uppercase: true,
    password_require_lowercase: true,
    password_require_numbers: true,
    password_require_special: true,
    session_timeout: 60,
    max_login_attempts: 5,
    account_lockout_duration: 30,
    two_factor_auth: false,
    jwt_expiry: 7,
    ip_whitelist: '',
    enable_audit_log: true
  });

  // Profile
  const [profileData, setProfileData] = useState({
    full_name: '',
    email: '',
    phone: '',
    profile_photo: null,
    photo_preview: null
  });
  const [passwordData, setPasswordData] = useState({
    current_password: '',
    new_password: '',
    confirm_password: ''
  });

  const isDark = theme === 'dark';
  const t = language === 'en' ? englishTranslations : amharicTranslations;

  useEffect(() => {
    fetchSettings();
    if (user) {
      setProfileData({
        full_name: user.full_name || '',
        email: user.email || '',
        phone: user.phone_number || '',
        profile_photo: null,
        photo_preview: user.profile_photo || null
      });
    }
  }, [user]);

  const fetchSettings = async () => {
    try {
      const response = await axios.get('/api/settings');
      const data = response.data.settings || {};
      setSettings({ ...settings, ...data });
      if (data.security) setSecuritySettings({ ...securitySettings, ...data.security });
    } catch (error) {
      console.log('Using default settings');
    }
  };

  const handleSettingsChange = (e) => {
    const { name, value, type, checked } = e.target;
    setSettings({ ...settings, [name]: type === 'checkbox' ? checked : value });
  };

  const handleSecurityChange = (e) => {
    const { name, value, type, checked } = e.target;
    setSecuritySettings({ ...securitySettings, [name]: type === 'checkbox' ? checked : value });
  };

  const handleProfileChange = (e) => {
    const { name, value } = e.target;
    setProfileData({ ...profileData, [name]: value });
  };

  const handlePhotoChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = () => {
        setProfileData({ ...profileData, profile_photo: file, photo_preview: reader.result });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveSettings = async () => {
    setLoading(true);
    try {
      await axios.put('/api/settings', { ...settings, security: securitySettings });
      toast.success(t.settingsSaved);
    } catch (error) {
      toast.error(t.saveFailed);
    }
    setLoading(false);
  };

  const handleSaveProfile = async () => {
    setLoading(true);
    try {
      const formData = new FormData();
      formData.append('full_name', profileData.full_name);
      formData.append('email', profileData.email);
      formData.append('phone', profileData.phone);
      if (profileData.profile_photo) {
        formData.append('profile_photo', profileData.profile_photo);
      }
      const response = await axios.put('/api/users/profile', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      toast.success(t.profileUpdated);
      if (updateUser) updateUser(response.data.user);
    } catch (error) {
      toast.error(t.profileUpdateFailed);
    }
    setLoading(false);
  };

  const handlePasswordChange = async (e) => {
    e.preventDefault();
    if (passwordData.new_password !== passwordData.confirm_password) {
      toast.error(t.passwordsMismatch);
      return;
    }
    if (passwordData.new_password.length < securitySettings.password_min_length) {
      toast.error(t.passwordMinLength.replace('{min}', securitySettings.password_min_length));
      return;
    }
    setLoading(true);
    try {
      await axios.put('/api/auth/change-password', {
        currentPassword: passwordData.current_password,
        newPassword: passwordData.new_password
      });
      toast.success(t.passwordChanged);
      setPasswordData({ current_password: '', new_password: '', confirm_password: '' });
    } catch (error) {
      toast.error(error.response?.data?.message || t.passwordChangeFailed);
    }
    setLoading(false);
  };

  const renderSystemSettings = () => (
    <>
      <div style={styles.row}>
        <div style={styles.col}>
