            placeholder="AST-{YYYY}-{SEQ}"
          />
          <div style={{ fontSize: '0.75rem', color: isDark ? '#8896b0' : '#4a5568', marginTop: '-8px', marginBottom: '12px' }}>
            {t.codeFormatHint}
          </div>
        </div>
        <div style={styles.col}>
          <label style={styles.label}>{t.defaultCurrency}</label>
          <select
            name="default_currency"
            style={styles.select}
            value={settings.default_currency}
            onChange={handleSettingsChange}
