            <option value="Europe/London">Europe/London</option>
            <option value="Asia/Dubai">Asia/Dubai</option>
          </select>
        </div>
      </div>

      <div style={styles.divider} />

      <h4 style={styles.subSectionTitle}>{t.notificationSettings}</h4>
      <div style={{ display: 'flex', gap: '24px', flexWrap: 'wrap', marginBottom: '12px' }}>
        <label style={styles.checkboxLabel}>
          <input
            type="checkbox"
            name="notification_enabled"
            style={styles.checkbox}
            checked={settings.notification_enabled}
            onChange={handleSettingsChange}
          />
          {t.enableNotifications}
        </label>
        <label style={styles.checkboxLabel}>
          <input
            type="checkbox"
            name="notification_sms"
            style={styles.checkbox}
            checked={settings.notification_sms}
            onChange={handleSettingsChange}
          />
          {t.enableSms}
        </label>
      </div>
      <div style={styles.row}>
        <div style={styles.col}>
          <label style={styles.label}>{t.notificationEmail}</label>
          <input
            type="email"
            name="notification_email"
            style={styles.input}
            value={settings.notification_email}
            onChange={handleSettingsChange}
          />
        </div>
      </div>
    </>
  );

  const renderSecuritySettings = () => (
    <>
      <h4 style={styles.subSectionTitle}>{t.passwordPolicy}</h4>
      <div style={styles.row}>
        <div style={styles.col}>
          <label style={styles.label}>{t.minPasswordLength}</label>
          <input
            type="number"
            name="password_min_length"
            style={styles.input}
            value={securitySettings.password_min_length}
            onChange={handleSecurityChange}
            min="6"
            max="20"
          />
        </div>
      </div>
      <div style={{ display: 'flex', gap: '24px', flexWrap: 'wrap', marginBottom: '16px' }}>
        <label style={styles.checkboxLabel}>
          <input
            type="checkbox"
            name="password_require_uppercase"
            style={styles.checkbox}
            checked={securitySettings.password_require_uppercase}
            onChange={handleSecurityChange}
          />
          {t.requireUppercase}
        </label>
        <label style={styles.checkboxLabel}>
          <input
            type="checkbox"
            name="password_require_lowercase"
            style={styles.checkbox}
            checked={securitySettings.password_require_lowercase}
            onChange={handleSecurityChange}
          />
          {t.requireLowercase}
        </label>
        <label style={styles.checkboxLabel}>
          <input
            type="checkbox"
            name="password_require_numbers"
            style={styles.checkbox}
            checked={securitySettings.password_require_numbers}
            onChange={handleSecurityChange}
          />
          {t.requireNumbers}
        </label>
        <label style={styles.checkboxLabel}>
          <input
            type="checkbox"
            name="password_require_special"
            style={styles.checkbox}
            checked={securitySettings.password_require_special}
            onChange={handleSecurityChange}
          />
          {t.requireSpecial}
        </label>
      </div>

      <div style={styles.divider} />

      <h4 style={styles.subSectionTitle}>{t.sessionSecurity}</h4>
      <div style={styles.row}>
        <div style={styles.col}>
          <label style={styles.label}>{t.sessionTimeout} ({t.minutes})</label>
