    fetchAssets();
    fetchDepartments();
  }, []);

  const fetchTransfers = async () => {
    setLoading(true);
    try {
      const response = await axios.get('/api/transfers');
      setTransfers(response.data?.data || response.data || []);
    } catch (error) {
      console.error('Error fetching transfers:', error);
      toast.error('Failed to load transfers');
    } finally {
      setLoading(false);
    }
  };

  const fetchAssets = async () => {
    try {
      const response = await axios.get('/api/assets');
      setAssets(response.data?.data || response.data || []);
    } catch (error) {
      console.error('Error fetching assets:', error);
    }
  };

  const fetchDepartments = async () => {
    try {
      const response = await axios.get('/api/departments');
      setDepartments(response.data?.data || response.data?.departments || response.data || []);
    } catch (error) {
      console.error('Error fetching departments:', error);
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editingId) {
        await axios.put(`/api/transfers/${editingId}`, formData);
        toast.success('Transfer updated successfully');
      } else {
        await axios.post('/api/transfers', formData);
        toast.success('Transfer created successfully');
      }
      fetchTransfers();
      resetForm();
      setShowForm(false);
    } catch (error) {
      toast.error('Error saving transfer');
    }
  };

  const handleApprove = async (id) => {
    try {
      await axios.patch(`/api/transfers/${id}`, { status: 'Approved' });
      toast.success('Transfer approved');
      fetchTransfers();
    } catch (error) {
      toast.error('Error approving transfer');
    }
  };

  const handleReject = async (id) => {
    try {
      await axios.patch(`/api/transfers/${id}`, { status: 'Rejected' });
      toast.success('Transfer rejected');
      fetchTransfers();
    } catch (error) {
      toast.error('Error rejecting transfer');
    }
  };

  const handleComplete = async (id) => {
    try {
      await axios.patch(`/api/transfers/${id}`, { status: 'Completed' });
      toast.success('Transfer completed');
      fetchTransfers();
    } catch (error) {
      toast.error('Error completing transfer');
    }
  };

  const handleCancel = async (id) => {
    if (window.confirm('Are you sure you want to cancel this transfer?')) {
      try {
        await axios.patch(`/api/transfers/${id}`, { status: 'Cancelled' });
        toast.success('Transfer cancelled');
        fetchTransfers();
      } catch (error) {
        toast.error('Error cancelling transfer');
      }
    }
  };

  const handleEdit = (transfer) => {
    setFormData(transfer);
    setEditingId(transfer.id);
    setShowForm(true);
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this transfer record?')) {
      try {
        await axios.delete(`/api/transfers/${id}`);
        toast.success('Transfer deleted');
        fetchTransfers();
      } catch (error) {
        toast.error('Error deleting transfer');
      }
    }
  };

  const resetForm = () => {
    setFormData({
      assetId: '',
      sourceDepartment: '',
      destinationDepartment: '',
      currentLocation: '',
      newLocation: '',
      transferReason: '',
      transferDate: new Date().toISOString().split('T')[0],
      status: 'Pending',
      notes: ''
    });
    setEditingId(null);
  };

  const filteredTransfers = transfers.filter(transfer => {
    const matchesSearch = 
      (transfer.asset?.name?.toLowerCase().includes(searchQuery.toLowerCase())) ||
      (transfer.sourceDepartment?.toLowerCase().includes(searchQuery.toLowerCase())) ||
      (transfer.destinationDepartment?.toLowerCase().includes(searchQuery.toLowerCase()));
    
    const matchesFilter = filterStatus === 'all' || transfer.status === filterStatus;
    return matchesSearch && matchesFilter;
  });

  const paginatedTransfers = filteredTransfers.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  const totalPages = Math.ceil(filteredTransfers.length / itemsPerPage);

  const getStatusColor = (status) => {
    const statusInfo = transferStatuses.find(s => s.value === status);
    return statusInfo?.color || '#e2e8f0';
  };

  return (
    <div style={{ padding: '20px', backgroundColor: styles.bg, minHeight: '100vh' }}>
      <div style={{
        backgroundColor: styles.card,
        borderRadius: '12px',
        padding: '24px',
        boxShadow: styles.shadow,
        marginBottom: '20px'
      }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
          <h1 style={{ color: styles.text, margin: 0 }}>🔄 Asset Transfer Management</h1>
          <button
            onClick={() => {
              setShowForm(!showForm);
              resetForm();
            }}
            style={{
              padding: '10px 16px',
              backgroundColor: styles.accent,
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              cursor: 'pointer',
              fontWeight: 600
            }}
          >
            {showForm ? '✕ Close' : '➕ New Transfer'}
          </button>
        </div>

        {/* Search and Filter */}
        <div style={{ display: 'flex', gap: '12px', marginBottom: '20px', flexWrap: 'wrap' }}>
          <input
            type="text"
            placeholder="Search by asset or department..."
            value={searchQuery}
            onChange={(e) => {
              setSearchQuery(e.target.value);
              setCurrentPage(1);
            }}
            style={{
              flex: 1,
              minWidth: '200px',
              padding: '10px 12px',
              backgroundColor: isDark ? '#0d1b2a' : '#f8f9fa',
              border: `1px solid ${styles.border}`,
              borderRadius: '6px',
              color: styles.text
            }}
          />
          <select
            value={filterStatus}
            onChange={(e) => {
              setFilterStatus(e.target.value);
              setCurrentPage(1);
            }}
            style={{
              padding: '10px 12px',
              backgroundColor: isDark ? '#0d1b2a' : '#f8f9fa',
              border: `1px solid ${styles.border}`,
              borderRadius: '6px',
              color: styles.text,
              cursor: 'pointer'
            }}
          >
            <option value="all">All Status</option>
            {transferStatuses.map(s => (
              <option key={s.value} value={s.value}>{s.label}</option>
            ))}
          </select>
        </div>

        {/* Form */}
        {showForm && (
          <form onSubmit={handleSubmit} style={{
            backgroundColor: isDark ? '#0d1b2a' : '#f8f9fa',
            padding: '20px',
            borderRadius: '8px',
            marginBottom: '20px',
            border: `1px solid ${styles.border}`
          }}>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '15px', marginBottom: '15px' }}>
              <div>
                <label style={{ color: styles.text, fontWeight: 600, marginBottom: '5px', display: 'block' }}>Asset *</label>
                <select
                  name="assetId"
                  value={formData.assetId}
                  onChange={handleInputChange}
                  required
                  style={{
                    width: '100%',
                    padding: '10px',
                    backgroundColor: styles.card,
                    color: styles.text,
                    border: `1px solid ${styles.border}`,
                    borderRadius: '6px',
                    cursor: 'pointer'
                  }}
                >
                  <option value="">Select Asset</option>
                  {assets.map(asset => (
                    <option key={asset.id} value={asset.id}>{asset.name} ({asset.code})</option>
                  ))}
                </select>
              </div>

              <div>
                <label style={{ color: styles.text, fontWeight: 600, marginBottom: '5px', display: 'block' }}>Source Department *</label>
                <select
                  name="sourceDepartment"
                  value={formData.sourceDepartment}
                  onChange={handleInputChange}
                  required
                  style={{
                    width: '100%',
                    padding: '10px',
                    backgroundColor: styles.card,
                    color: styles.text,
                    border: `1px solid ${styles.border}`,
                    borderRadius: '6px',
                    cursor: 'pointer'
                  }}
                >
                  <option value="">Select Department</option>
                  {departments.map(dept => (
                    <option key={dept.id} value={dept.id}>{dept.name}</option>
                  ))}
                </select>
              </div>

              <div>
                <label style={{ color: styles.text, fontWeight: 600, marginBottom: '5px', display: 'block' }}>Destination Department *</label>
                <select
                  name="destinationDepartment"
                  value={formData.destinationDepartment}
                  onChange={handleInputChange}
                  required
                  style={{
                    width: '100%',
                    padding: '10px',
                    backgroundColor: styles.card,
                    color: styles.text,
                    border: `1px solid ${styles.border}`,
                    borderRadius: '6px',
                    cursor: 'pointer'
                  }}
                >
                  <option value="">Select Department</option>
                  {departments.map(dept => (
                    <option key={dept.id} value={dept.id}>{dept.name}</option>
                  ))}
                </select>
              </div>

              <div>
                <label style={{ color: styles.text, fontWeight: 600, marginBottom: '5px', display: 'block' }}>Current Location</label>
                <input
                  type="text"
                  name="currentLocation"
                  value={formData.currentLocation}
                  onChange={handleInputChange}
                  style={{
                    width: '100%',
                    padding: '10px',
                    backgroundColor: styles.card,
                    color: styles.text,
                    border: `1px solid ${styles.border}`,
                    borderRadius: '6px'
                  }}
                />
              </div>

              <div>
                <label style={{ color: styles.text, fontWeight: 600, marginBottom: '5px', display: 'block' }}>New Location *</label>
                <input
                  type="text"
                  name="newLocation"
                  value={formData.newLocation}
                  onChange={handleInputChange}
                  required
                  style={{
                    width: '100%',
                    padding: '10px',
                    backgroundColor: styles.card,
                    color: styles.text,
                    border: `1px solid ${styles.border}`,
                    borderRadius: '6px'
                  }}
                />
              </div>

              <div>
                <label style={{ color: styles.text, fontWeight: 600, marginBottom: '5px', display: 'block' }}>Transfer Date *</label>
                <input
                  type="date"
                  name="transferDate"
                  value={formData.transferDate}
                  onChange={handleInputChange}
                  required
                  style={{
                    width: '100%',
                    padding: '10px',
                    backgroundColor: styles.card,
                    color: styles.text,
                    border: `1px solid ${styles.border}`,
                    borderRadius: '6px'
                  }}
                />
              </div>
            </div>

            <div style={{ marginBottom: '15px' }}>
              <label style={{ color: styles.text, fontWeight: 600, marginBottom: '5px', display: 'block' }}>Transfer Reason *</label>
              <textarea
                name="transferReason"
                value={formData.transferReason}
                onChange={handleInputChange}
                required
                rows="3"
                style={{
                  width: '100%',
                  padding: '10px',
                  backgroundColor: styles.card,
                  color: styles.text,
                  border: `1px solid ${styles.border}`,
                  borderRadius: '6px',
                  fontFamily: 'inherit'
                }}
              />
            </div>

            <div style={{ marginBottom: '15px' }}>
              <label style={{ color: styles.text, fontWeight: 600, marginBottom: '5px', display: 'block' }}>Notes</label>
              <textarea
                name="notes"
                value={formData.notes}
                onChange={handleInputChange}
                rows="2"
                style={{
                  width: '100%',
                  padding: '10px',
                  backgroundColor: styles.card,
                  color: styles.text,
                  border: `1px solid ${styles.border}`,
                  borderRadius: '6px',
                  fontFamily: 'inherit'
                }}
              />
            </div>

            <div style={{ display: 'flex', gap: '10px' }}>
              <button
                type="submit"
                style={{
                  padding: '10px 20px',
                  backgroundColor: styles.success,
                  color: 'white',
                  border: 'none',
                  borderRadius: '6px',
                  cursor: 'pointer',
                  fontWeight: 600
                }}
              >
                {editingId ? '💾 Update' : '✔️ Create'} Transfer
              </button>
              <button
                type="button"
                onClick={() => {
                  setShowForm(false);
                  resetForm();
                }}
                style={{
                  padding: '10px 20px',
                  backgroundColor: styles.border,
                  color: styles.text,
                  border: 'none',
                  borderRadius: '6px',
                  cursor: 'pointer',
                  fontWeight: 600
                }}
              >
                Cancel
              </button>
            </div>
          </form>
        )}

        {/* Transfers Table */}
        {loading ? (
          <div style={{ textAlign: 'center', padding: '40px', color: styles.subText }}>
            <div style={{ fontSize: '1.5rem', marginBottom: '10px' }}>⏳</div>
            <div>Loading transfers...</div>
          </div>
        ) : paginatedTransfers.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '40px', color: styles.subText }}>
            <div style={{ fontSize: '2rem', marginBottom: '10px' }}>📭</div>
            <div>No transfers found</div>
          </div>
        ) : (
          <>
            <div style={{ overflowX: 'auto' }}>
              <table style={{
                width: '100%',
                borderCollapse: 'collapse',
                fontSize: '0.9rem'
              }}>
                <thead>
                  <tr style={{ backgroundColor: isDark ? '#0d1b2a' : '#f8f9fa', borderBottom: `2px solid ${styles.border}` }}>
                    <th style={{ padding: '12px', textAlign: 'left', color: styles.text }}>Asset</th>
                    <th style={{ padding: '12px', textAlign: 'left', color: styles.text }}>From</th>
                    <th style={{ padding: '12px', textAlign: 'left', color: styles.text }}>To</th>
                    <th style={{ padding: '12px', textAlign: 'left', color: styles.text }}>Date</th>
                    <th style={{ padding: '12px', textAlign: 'left', color: styles.text }}>Status</th>
                    <th style={{ padding: '12px', textAlign: 'center', color: styles.text }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {paginatedTransfers.map(transfer => (
                    <tr key={transfer.id} style={{ borderBottom: `1px solid ${styles.border}` }}>
                      <td style={{ padding: '12px', color: styles.text }}>{transfer.asset?.name || 'N/A'}</td>
                      <td style={{ padding: '12px', color: styles.text }}>{transfer.sourceDepartment || 'N/A'}</td>
                      <td style={{ padding: '12px', color: styles.text }}>{transfer.destinationDepartment || 'N/A'}</td>
                      <td style={{ padding: '12px', color: styles.text }}>{new Date(transfer.transferDate).toLocaleDateString()}</td>
                      <td style={{ padding: '12px' }}>
                        <span style={{
                          padding: '4px 8px',
                          borderRadius: '4px',
                          fontSize: '0.8rem',
                          fontWeight: 600,
                          backgroundColor: getStatusColor(transfer.status),
                          color: '#1a365d'
                        }}>
                          {transfer.status}
                        </span>
                      </td>
                      <td style={{ padding: '12px', textAlign: 'center', fontSize: '0.85rem' }}>
                        <button
                          onClick={() => handleEdit(transfer)}
                          style={{
                            padding: '4px 8px',
                            marginRight: '4px',
                            backgroundColor: styles.accent,
                            color: 'white',
                            border: 'none',
                            borderRadius: '4px',
                            cursor: 'pointer'
                          }}
                        >
                          ✏️
                        </button>
                        {transfer.status === 'Pending' && (
                          <>
                            <button
                              onClick={() => handleApprove(transfer.id)}
                              style={{
                                padding: '4px 8px',
                                marginRight: '4px',
                                backgroundColor: styles.success,
                                color: 'white',
                                border: 'none',
                                borderRadius: '4px',
                                cursor: 'pointer'
                              }}
                            >
                              ✔️
                            </button>
                            <button
                              onClick={() => handleReject(transfer.id)}
                              style={{
                                padding: '4px 8px',
                                marginRight: '4px',
                                backgroundColor: styles.danger,
                                color: 'white',
                                border: 'none',
                                borderRadius: '4px',
                                cursor: 'pointer'
                              }}
                            >
                              ✕
                            </button>
                          </>
                        )}
                        {transfer.status === 'Approved' && (
                          <button
                            onClick={() => handleComplete(transfer.id)}
                            style={{
                              padding: '4px 8px',
                              marginRight: '4px',
                              backgroundColor: styles.success,
                              color: 'white',
                              border: 'none',
                              borderRadius: '4px',
                              cursor: 'pointer'
                            }}
                          >
                            ✅
                          </button>
                        )}
                        {['Pending', 'Approved', 'In Progress'].includes(transfer.status) && (
                          <button
                            onClick={() => handleCancel(transfer.id)}
                            style={{
                              padding: '4px 8px',
                              marginRight: '4px',
                              backgroundColor: styles.warning,
                              color: 'white',
                              border: 'none',
                              borderRadius: '4px',
                              cursor: 'pointer'
                            }}
                          >
                            ⛔
                          </button>
                        )}
                        <button
                          onClick={() => handleDelete(transfer.id)}
                          style={{
                            padding: '4px 8px',
                            backgroundColor: '#cbd5e0',
                            color: '#1a365d',
                            border: 'none',
                            borderRadius: '4px',
                            cursor: 'pointer'
                          }}
                        >
                          🗑️
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Pagination */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '20px', color: styles.subText }}>
              <div>Showing {((currentPage - 1) * itemsPerPage) + 1} to {Math.min(currentPage * itemsPerPage, filteredTransfers.length)} of {filteredTransfers.length}</div>
              <div style={{ display: 'flex', gap: '5px' }}>
                <button
                  onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                  disabled={currentPage === 1}
                  style={{
                    padding: '6px 12px',
                    backgroundColor: currentPage === 1 ? '#e2e8f0' : styles.accent,
                    color: currentPage === 1 ? '#a0aec0' : 'white',
                    border: 'none',
                    borderRadius: '4px',
                    cursor: currentPage === 1 ? 'not-allowed' : 'pointer'
                  }}
                >
                  ← Prev
                </button>
                {Array.from({ length: totalPages }, (_, i) => i + 1).map(page => (
                  <button
                    key={page}
                    onClick={() => setCurrentPage(page)}
                    style={{
                      padding: '6px 10px',
                      backgroundColor: page === currentPage ? styles.accent : isDark ? '#0d1b2a' : '#f8f9fa',
                      color: page === currentPage ? 'white' : styles.text,
                      border: `1px solid ${styles.border}`,
                      borderRadius: '4px',
                      cursor: 'pointer'
                    }}
                  >
                    {page}
                  </button>
                ))}
                <button
                  onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                  disabled={currentPage === totalPages}
                  style={{
                    padding: '6px 12px',
                    backgroundColor: currentPage === totalPages ? '#e2e8f0' : styles.accent,
                    color: currentPage === totalPages ? '#a0aec0' : 'white',
                    border: 'none',
                    borderRadius: '4px',
                    cursor: currentPage === totalPages ? 'not-allowed' : 'pointer'
                  }}
                >
                  Next →
                </button>
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default AdminTransfer;

import React, { useState, useEffect } from 'react';
import { useLanguage } from '../../contexts/UiContext';
import { toast } from 'react-toastify';
import axios from 'axios';
import { getDepartmentLabel } from '../../utils/department';

const AdminUserManagement = () => {
  const { language, theme } = useLanguage();
  const [users, setUsers] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showCreate, setShowCreate] = useState(false);
  const [showEdit, setShowEdit] = useState(false);
  const [showRoles, setShowRoles] = useState(false);
  const [showActivityLogs, setShowActivityLogs] = useState(false);
  const [selectedUser, setSelectedUser] = useState(null);
  const [activityLogs, setActivityLogs] = useState([]);
  const [viewMode, setViewMode] = useState('users'); // 'users' | 'roles' | 'activity'
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    password: '',
    full_name: '',
    role: 'staff',
    department: '',
    phone_number: '',
    is_active: true
  });
  const [roles, setRoles] = useState([
    { id: 'admin', name: 'Admin', permissions: ['CREATE', 'READ', 'UPDATE', 'DELETE', 'APPROVE', 'TRANSFER', 'REPORT', 'MANAGE_USERS'] },
    { id: 'ict_officer', name: 'ICT / Property Officer', permissions: ['CREATE', 'READ', 'UPDATE', 'DELETE', 'APPROVE', 'TRANSFER', 'REPORT'] },
    { id: 'store_manager', name: 'Store Manager', permissions: ['CREATE', 'READ', 'UPDATE', 'REPORT'] },
    { id: 'finance', name: 'Finance & Audit', permissions: ['READ', 'REPORT'] },
    { id: 'department_head', name: 'Department Head', permissions: ['CREATE', 'READ', 'UPDATE', 'APPROVE'] },
    { id: 'maintenance', name: 'Maintenance Team', permissions: ['READ', 'UPDATE', 'APPROVE'] },
    { id: 'staff', name: 'Staff', permissions: ['READ'] }
  ]);

  const isDark = theme === 'dark';
  const t = language === 'en' ? englishTranslations : amharicTranslations;

  const authConfig = {
    headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
  };

  const normalizeUser = (userData) => ({
    ...userData,
    full_name: userData.full_name || userData.fullName || '',
    phone_number: userData.phone_number || userData.phone || '',
    is_active: userData.is_active ?? userData.active ?? true,
    created_at: userData.created_at || userData.createdAt,
    last_login: userData.last_login || userData.lastLogin
  });

  useEffect(() => {
    fetchUsers();
    fetchDepartments();
  }, []);

  const fetchUsers = async () => {
    setLoading(true);
    try {
      const response = await axios.get('/api/users', authConfig);
      setUsers((response.data.data || response.data.users || []).map(normalizeUser));
    } catch (error) {
      toast.error(t.loadFailed);
      setUsers([]);
    }
    setLoading(false);
  };

  const fetchDepartments = async () => {
    try {
      const response = await axios.get('/api/departments', authConfig);
      setDepartments(response.data.departments || []);
    } catch (error) {
      setDepartments([]);
    }
  };

  const fetchActivityLogs = async (userId) => {
    try {
      const response = await axios.get(`/api/users/${userId}/activity`, authConfig);
      setActivityLogs(response.data.logs || []);
    } catch (error) {
      setActivityLogs([]);
    }
  };

  const handleCreate = async (e) => {
    e.preventDefault();
    try {
      await axios.post('/api/users', {
        username: formData.username,
        email: formData.email,
        password: formData.password,
        fullName: formData.full_name,
        role: formData.role,
        department: formData.department,
        phone: formData.phone_number,
        active: formData.is_active
      }, authConfig);
      toast.success(t.userCreated);
      setShowCreate(false);
      resetForm();
      fetchUsers();
    } catch (error) {
      toast.error(error.response?.data?.message || t.createFailed);
    }
  };

  const handleUpdate = async (e) => {
    e.preventDefault();
    try {
      const updateData = { ...formData };
      if (!updateData.password) delete updateData.password;
      await axios.put(`/api/users/${selectedUser.id}`, {
        ...updateData,
        fullName: updateData.full_name,
        phone: updateData.phone_number,
        active: updateData.is_active
      }, authConfig);
      toast.success(t.userUpdated);
      setShowEdit(false);
      setSelectedUser(null);
      resetForm();
      fetchUsers();
    } catch (error) {
      toast.error(error.response?.data?.message || t.updateFailed);
    }
  };

  const handleToggleActive = async (id, isActive) => {
    try {
      await axios.put(`/api/users/${id}`, { active: !isActive }, authConfig);
      toast.success(t.statusUpdated);
      fetchUsers();
    } catch (error) {
      toast.error(t.statusUpdateFailed);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm(t.confirmDelete)) return;
    try {
      await axios.delete(`/api/users/${id}`, authConfig);
      toast.success(t.userDeleted);
      fetchUsers();
    } catch (error) {
      toast.error(t.deleteFailed);
    }
  };

  const handleResetPassword = async (id) => {
    const newPassword = prompt(t.enterNewPassword);
    if (!newPassword || newPassword.length < 6) {
      toast.warning(t.passwordMinLength);
      return;
    }
    try {
      await axios.put(`/api/users/${id}`, { password: newPassword }, authConfig);
      toast.success(t.passwordReset);
    } catch (error) {
      toast.error(t.passwordResetFailed);
    }
  };

  const handleEditUser = (user) => {
    setSelectedUser(user);
    setFormData({
      username: user.username,
      email: user.email,
      password: '',
      full_name: user.full_name || '',
      role: user.role,
      department: user.department || '',
      phone_number: user.phone_number || '',
      is_active: user.is_active
    });
    setShowEdit(true);
  };

  const handleViewActivity = async (user) => {
    setSelectedUser(user);
    await fetchActivityLogs(user.id);
    setShowActivityLogs(true);
  };

  const resetForm = () => {
    setFormData({
      username: '',
      email: '',
      password: '',
      full_name: '',
      role: 'staff',
      department: '',
      phone_number: '',
      is_active: true
    });
  };

  const getRoleLabel = (role) => {
    const labels = {
      'admin': '👑 Admin',
      'ict_officer': '💻 ICT Officer',
      'department_head': '📋 Department Head',
      'store_manager': '🏪 Store Manager',
      'finance': '💰 Finance',
      'maintenance': '🔧 Maintenance',
      'staff': '👤 Staff'
    };
    return labels[role] || role;
  };

  const getRolePermissions = (role) => {
    const found = roles.find(r => r.id === role);
    return found ? found.permissions : [];
  };

  const getPermissionColor = (permission) => {
    const colors = {
      'CREATE': '#48bb78',
      'READ': '#4299e1',
      'UPDATE': '#ed8936',
      'DELETE': '#fc8181',
      'APPROVE': '#805ad5',
      'TRANSFER': '#9f7aea',
      'REPORT': '#38a169',
      'MANAGE_USERS': '#e53e3e'
    };
    return colors[permission] || '#a0aec0';
  };

  const getActivityIcon = (action) => {
    const icons = {
      'LOGIN': '🔐',
      'LOGOUT': '🚪',
      'CREATE_ASSET': '📦',
      'UPDATE_ASSET': '✏️',
      'DELETE_ASSET': '🗑️',
      'ASSIGN_ASSET': '📋',
      'TRANSFER_ASSET': '🔄',
      'APPROVE_MAINTENANCE': '✅',
      'CREATE_USER': '👤',
      'CHANGE_SETTINGS': '⚙️',
      'RESTORE_BACKUP': '💾'
    };
    return icons[action] || '📌';
  };

  const styles = {
    container: { padding: '20px', maxWidth: '1400px', margin: '0 auto' },
    header: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      flexWrap: 'wrap',
      gap: '16px',
      marginBottom: '24px'
    },
    title: {
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '1.75rem',
      fontWeight: 700,
      margin: 0
    },
    subtitle: {
      color: isDark ? '#8896b0' : '#4a5568',
      fontSize: '0.9rem',
      margin: '4px 0 0 0'
    },
    viewTabs: {
      display: 'flex',
      gap: '8px',
      background: isDark ? '#1a273a' : '#f0f4f8',
      padding: '4px',
      borderRadius: '10px',
      marginBottom: '16px'
    },
    viewTab: (active) => ({
      padding: '10px 20px',
      borderRadius: '8px',
      border: 'none',
      cursor: 'pointer',
      fontWeight: 600,
      fontSize: '0.9rem',
      background: active ? (isDark ? '#2b6cb0' : '#2b6cb0') : 'transparent',
      color: active ? '#ffffff' : (isDark ? '#8896b0' : '#4a5568'),
      transition: 'all 0.2s'
    }),
    createButton: {
      padding: '10px 20px',
      background: 'linear-gradient(135deg, #2b6cb0, #4299e1)',
      color: 'white',
      border: 'none',
      borderRadius: '8px',
      fontWeight: 600,
      cursor: 'pointer',
      fontSize: '0.9rem',
      transition: 'all 0.2s'
    },
    card: {
      background: isDark ? '#1e2d45' : '#ffffff',
      padding: '16px 20px',
      borderRadius: '12px',
      border: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      marginBottom: '12px',
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      flexWrap: 'wrap',
      gap: '12px',
      boxShadow: isDark ? '0 2px 8px rgba(0,0,0,0.2)' : '0 2px 8px rgba(0,0,100,0.04)',
      transition: 'transform 0.2s'
    },
    userInfo: {
      display: 'flex',
      alignItems: 'center',
      gap: '16px'
    },
    avatar: {
      width: '48px',
      height: '48px',
      borderRadius: '50%',
      background: 'linear-gradient(135deg, #2b6cb0, #4299e1)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      color: 'white',
      fontSize: '1.2rem',
      fontWeight: 700,
      flexShrink: 0
    },
    userName: {
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontWeight: 600,
      fontSize: '1rem'
    },
    userDetail: {
      color: isDark ? '#8896b0' : '#4a5568',
      fontSize: '0.85rem'
    },
    statusBadge: (active) => ({
      padding: '4px 12px',
      borderRadius: '20px',
      fontSize: '0.75rem',
      fontWeight: 600,
      background: active ? '#48bb7820' : '#fc818120',
      color: active ? '#48bb78' : '#fc8181'
    }),
    actionButton: (bg, color = 'white') => ({
      padding: '6px 12px',
      borderRadius: '6px',
      border: 'none',
      cursor: 'pointer',
      fontSize: '0.75rem',
      marginRight: '4px',
      background: bg,
      color: color,
      transition: 'all 0.2s'
    }),
    modal: {
      position: 'fixed',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      background: 'rgba(0,0,0,0.6)',
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      zIndex: 1000,
      padding: '20px'
    },
    modalContent: {
      background: isDark ? '#1e2d45' : '#ffffff',
      padding: '30px',
      borderRadius: '16px',
      maxWidth: '550px',
      width: '100%',
      maxHeight: '85vh',
      overflow: 'auto',
      boxShadow: '0 20px 60px rgba(0,0,0,0.4)'
    },
    modalTitle: {
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '1.3rem',
      fontWeight: 700,
      marginBottom: '20px'
    },
    input: {
      width: '100%',
      padding: '10px 14px',
      borderRadius: '8px',
      border: `1px solid ${isDark ? '#32465f' : '#d0d8e8'}`,
      background: isDark ? '#0d1b2a' : '#ffffff',
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.95rem',
      marginBottom: '12px',
      boxSizing: 'border-box'
    },
    select: {
      width: '100%',
      padding: '10px 14px',
      borderRadius: '8px',
      border: `1px solid ${isDark ? '#32465f' : '#d0d8e8'}`,
      background: isDark ? '#0d1b2a' : '#ffffff',
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.95rem',
      marginBottom: '12px',
      cursor: 'pointer',
      boxSizing: 'border-box'
    },
    emptyState: {
      textAlign: 'center',
      padding: '60px 20px',
      color: isDark ? '#8896b0' : '#4a5568',
      background: isDark ? '#1e2d45' : '#ffffff',
      borderRadius: '12px',
      border: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`
    },
    // Roles styles
    roleCard: {
      background: isDark ? '#1e2d45' : '#ffffff',
      padding: '16px 20px',
      borderRadius: '12px',
      border: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      marginBottom: '12px',
      boxShadow: isDark ? '0 2px 8px rgba(0,0,0,0.2)' : '0 2px 8px rgba(0,0,100,0.04)'
    },
    roleName: {
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontWeight: 600,
      fontSize: '1.05rem'
    },
    permissionPill: (perm) => ({
      display: 'inline-block',
      padding: '2px 10px',
      borderRadius: '12px',
      fontSize: '0.7rem',
      fontWeight: 600,
      marginRight: '4px',
      marginBottom: '4px',
      background: getPermissionColor(perm) + '20',
      color: getPermissionColor(perm)
    }),
    // Activity styles
    activityItem: {
      padding: '10px 14px',
      borderBottom: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      flexWrap: 'wrap',
      gap: '8px'
    },
    activityIcon: { fontSize: '1.1rem', marginRight: '8px' },
    activityAction: { color: isDark ? '#c8dcf5' : '#1a365d', fontWeight: 500 },
    activityMeta: { color: isDark ? '#8896b0' : '#4a5568', fontSize: '0.8rem' },
    formRow: {
      display: 'grid',
      gridTemplateColumns: '1fr 1fr',
      gap: '12px'
    }
  };

  // Render Users View
  const renderUsers = () => (
    <>
      {loading ? (
        <div style={styles.emptyState}>⏳ {t.loading}</div>
      ) : users.length === 0 ? (
        <div style={styles.emptyState}>{t.noUsers}</div>
      ) : (
        users.map(u => (
          <div key={u.id} style={styles.card}>
            <div style={styles.userInfo}>
              <div style={styles.avatar}>{u.full_name?.charAt(0).toUpperCase() || u.username?.charAt(0).toUpperCase()}</div>
              <div>
                <div style={styles.userName}>{u.full_name || u.username}</div>
                <div style={styles.userDetail}>
                  @{u.username} • {getRoleLabel(u.role)}
                  {u.department && ` • ${getDepartmentLabel(u.department)}`}
                </div>
                <div style={styles.userDetail}>
                  {u.email} • {u.phone_number || '-'}
                  <span style={{ marginLeft: '12px' }}>
                    {t.created}: {new Date(u.created_at).toLocaleDateString()}
                  </span>
                  {u.last_login && (
                    <span style={{ marginLeft: '12px' }}>
                      {t.lastLogin}: {new Date(u.last_login).toLocaleString()}
                    </span>
                  )}
                </div>
              </div>
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '6px', flexWrap: 'wrap' }}>
              <span style={styles.statusBadge(u.is_active)}>
                {u.is_active ? '✅ Active' : '❌ Inactive'}
              </span>
              <button
                style={styles.actionButton(u.is_active ? '#fc8181' : '#48bb78')}
                onClick={() => handleToggleActive(u.id, u.is_active)}
              >
                {u.is_active ? t.deactivate : t.activate}
              </button>
              <button style={styles.actionButton('#ed8936')} onClick={() => handleEditUser(u)}>
                ✏️ {t.edit}
              </button>
              <button style={styles.actionButton('#805ad5')} onClick={() => handleResetPassword(u.id)}>
                🔑 {t.resetPassword}
              </button>
              <button style={styles.actionButton('#4299e1')} onClick={() => handleViewActivity(u)}>
                📜 {t.activity}
              </button>
              <button style={styles.actionButton('#fc8181')} onClick={() => handleDelete(u.id)}>
                🗑️ {t.delete}
              </button>
            </div>
          </div>
        ))
      )}
    </>
  );

  // Render Roles & Permissions View
  const renderRoles = () => (
    <>
      {roles.map(role => (
        <div key={role.id} style={styles.roleCard}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '8px' }}>
            <div>
              <div style={styles.roleName}>{getRoleLabel(role.id)}</div>
              <div style={{ color: isDark ? '#8896b0' : '#4a5568', fontSize: '0.85rem' }}>
                {role.id}
              </div>
            </div>
            <div>
              {role.permissions.map(perm => (
                <span key={perm} style={styles.permissionPill(perm)}>{perm}</span>
              ))}
            </div>
          </div>
        </div>
      ))}
    </>
  );

  // Render Activity Logs Modal
  const renderActivityModal = () => (
    <div style={styles.modal} onClick={() => setShowActivityLogs(false)}>
      <div style={{ ...styles.modalContent, maxWidth: '700px' }} onClick={e => e.stopPropagation()}>
        <h2 style={styles.modalTitle}>
          📜 {t.activityLogs} - {selectedUser?.full_name || selectedUser?.username}
        </h2>
        {activityLogs.length === 0 ? (
          <p style={{ color: isDark ? '#8896b0' : '#4a5568' }}>{t.noActivity}</p>
        ) : (
          activityLogs.map(log => (
            <div key={log.id} style={styles.activityItem}>
              <div>
                <span style={styles.activityIcon}>{getActivityIcon(log.action)}</span>
                <span style={styles.activityAction}>{log.action}</span>
                <span style={{ ...styles.activityMeta, marginLeft: '8px' }}>
                  {log.module} • {log.details}
                </span>
              </div>
              <div style={{ textAlign: 'right' }}>
                <span style={{
                  display: 'inline-block',
                  padding: '2px 10px',
                  borderRadius: '12px',
                  fontSize: '0.7rem',
                  fontWeight: 600,
                  background: log.status === 'SUCCESS' ? '#48bb7820' : '#fc818120',
                  color: log.status === 'SUCCESS' ? '#48bb78' : '#fc8181'
                }}>
                  {log.status}
                </span>
                <div style={styles.activityMeta}>
                  {log.ip_address} • {new Date(log.created_at).toLocaleString()}
                </div>
              </div>
            </div>
          ))
        )}
        <div style={{ marginTop: '16px' }}>
          <button style={styles.createButton} onClick={() => setShowActivityLogs(false)}>
            {t.close}
          </button>
        </div>
      </div>
    </div>
  );

  // Render Create/Edit Modal
  const renderUserModal = (isEdit) => {
    const handleSubmit = isEdit ? handleUpdate : handleCreate;
    const title = isEdit ? t.editUser : t.addUser;
    const buttonText = isEdit ? t.update : t.create;

    return (
      <div style={styles.modal} onClick={() => { setShowCreate(false); setShowEdit(false); }}>
        <div style={styles.modalContent} onClick={e => e.stopPropagation()}>
          <h2 style={styles.modalTitle}>{isEdit ? '✏️' : '➕'} {title}</h2>
          <form onSubmit={handleSubmit}>
            <input
              type="text"
              style={styles.input}
              placeholder={t.username}
              value={formData.username}
              onChange={(e) => setFormData({ ...formData, username: e.target.value })}
              required
              disabled={isEdit}
            />
            <div style={styles.formRow}>
              <input
                type="text"
                style={styles.input}
                placeholder={t.fullName}
                value={formData.full_name}
                onChange={(e) => setFormData({ ...formData, full_name: e.target.value })}
                required
              />
              <input
                type="email"
                style={styles.input}
                placeholder={t.email}
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                required
              />
            </div>
            {!isEdit && (
              <input
                type="password"
                style={styles.input}
                placeholder={t.password}
                value={formData.password}
                onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                required={!isEdit}
                minLength="6"
              />
            )}
            {isEdit && (
              <input
                type="password"
                style={styles.input}
                placeholder={t.newPasswordOptional}
                value={formData.password}
                onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                minLength="6"
              />
            )}
            <div style={styles.formRow}>
              <select
                style={styles.select}
                value={formData.role}
                onChange={(e) => setFormData({ ...formData, role: e.target.value })}
              >
                <option value="admin">👑 Admin</option>
                <option value="ict_officer">💻 ICT Officer</option>
                <option value="department_head">📋 Department Head</option>
                <option value="finance">💰 Finance & Audit</option>
                <option value="store_manager">🏪 Store Manager</option>
                <option value="maintenance">🔧 Maintenance Team</option>
                <option value="staff">👤 Staff</option>
              </select>
              <select
                style={styles.select}
                value={formData.department}
                onChange={(e) => setFormData({ ...formData, department: e.target.value })}
              >
                <option value="">{t.selectDepartment}</option>
                {departments.map(d => (
                  <option key={d.id} value={d.id}>{d.name}</option>
                ))}
              </select>
            </div>
            <input
              type="text"
              style={styles.input}
              placeholder={t.phoneNumber}
              value={formData.phone_number}
              onChange={(e) => setFormData({ ...formData, phone_number: e.target.value })}
            />
            {isEdit && (
              <div style={{ marginBottom: '12px' }}>
                <label style={{ color: isDark ? '#c8dcf5' : '#1a365d', fontSize: '0.85rem', display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <input
                    type="checkbox"
                    checked={formData.is_active}
                    onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
                  />
                  {t.active}
                </label>
              </div>
            )}
            <div style={{ display: 'flex', gap: '12px', marginTop: '12px' }}>
              <button type="submit" style={styles.createButton}>{buttonText}</button>
              <button
                type="button"
                style={{ ...styles.createButton, background: '#fc8181' }}
                onClick={() => { setShowCreate(false); setShowEdit(false); resetForm(); }}
              >
                {t.cancel}
              </button>
            </div>
          </form>
        </div>
      </div>
    );
  };

  return (
    <div style={styles.container}>
      {/* Header */}
      <div style={styles.header}>
        <div>
          <h1 style={styles.title}>👥 {t.userManagement}</h1>
          <p style={styles.subtitle}>
            {viewMode === 'users' && t.manageUsersDesc}
            {viewMode === 'roles' && t.manageRolesDesc}
            {viewMode === 'activity' && t.viewActivityDesc}
          </p>
        </div>
        <div>
          {viewMode === 'users' && (
            <button style={styles.createButton} onClick={() => { resetForm(); setShowCreate(true); }}>
              ➕ {t.addUser}
            </button>
          )}
        </div>
      </div>

      {/* View Tabs */}
      <div style={styles.viewTabs}>
        <button style={styles.viewTab(viewMode === 'users')} onClick={() => setViewMode('users')}>
          👥 {t.users}
        </button>
        <button style={styles.viewTab(viewMode === 'roles')} onClick={() => setViewMode('roles')}>
          🛡️ {t.rolesPermissions}
        </button>
        <button style={styles.viewTab(viewMode === 'activity')} onClick={() => { setViewMode('activity'); fetchActivityLogs('all'); }}>
          📜 {t.activityLogs}
        </button>
      </div>

      {/* Content */}
      {viewMode === 'users' && renderUsers()}
      {viewMode === 'roles' && renderRoles()}
      {viewMode === 'activity' && (
        <div style={{ ...styles.card, flexDirection: 'column', alignItems: 'stretch' }}>
          <h3 style={{ color: isDark ? '#c8dcf5' : '#1a365d', marginBottom: '12px' }}>{t.recentActivity}</h3>
          {activityLogs.length === 0 ? (
            <p style={{ color: isDark ? '#8896b0' : '#4a5568' }}>{t.noActivity}</p>
          ) : (
            activityLogs.slice(0, 30).map(log => (
              <div key={log.id} style={styles.activityItem}>
                <div>
                  <span style={styles.activityIcon}>{getActivityIcon(log.action)}</span>
                  <span style={styles.activityAction}>{log.action}</span>
                  <span style={{ ...styles.activityMeta, marginLeft: '8px' }}>
                    {log.module} • {log.details || log.action}
                    {log.user_name && ` • ${log.user_name}`}
                  </span>
                </div>
                <div style={{ textAlign: 'right' }}>
                  <span style={{
                    display: 'inline-block',
                    padding: '2px 10px',
                    borderRadius: '12px',
                    fontSize: '0.7rem',
                    fontWeight: 600,
                    background: log.status === 'SUCCESS' ? '#48bb7820' : '#fc818120',
                    color: log.status === 'SUCCESS' ? '#48bb78' : '#fc8181'
                  }}>
                    {log.status}
                  </span>
                  <div style={styles.activityMeta}>
                    {log.ip_address || '-'} • {new Date(log.created_at).toLocaleString()}
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      )}

      {/* Modals */}
      {showCreate && renderUserModal(false)}
      {showEdit && renderUserModal(true)}
      {showActivityLogs && renderActivityModal()}
    </div>
  );
};

