            const purchaseYear = a.purchase_date ? new Date(a.purchase_date).getFullYear() : 0;
            return purchaseYear <= year;
          });
          return yearAssets.reduce((sum, a) => sum + (a.depreciation?.annualDepreciation || 0), 0);
        }).reverse(),
