                </div>
                <div style={styles.infoItem}>
                  <div style={styles.infoLabel}>{t.yearsRemaining}</div>
                  <div style={styles.infoValue}>{selectedAsset.depreciation?.yearsRemaining || 0} {t.years}</div>
