import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useLanguage } from '../../contexts/UiContext';
import { useAuth } from '../../contexts/AuthContext';
import { toast } from 'react-toastify';
import axios from 'axios';
import * as XLSX from 'xlsx';

const FinanceValuation = () => {
  const { language, theme } = useLanguage();
  const { user } = useAuth();
  const [assets, setAssets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedAsset, setSelectedAsset] = useState(null);
  const [showModal, setShowModal] = useState(false);
  const [modalMode, setModalMode] = useState('view'); // view, edit, revalue, addCost
  const [valuationHistory, setValuationHistory] = useState([]);
  const [showHistory, setShowHistory] = useState(false);
  const [filters, setFilters] = useState({
    department: '',
    category: '',
    status: '',
    valuationStatus: ''
  });

  // Form state for editing/revaluation
  const [formData, setFormData] = useState({
    purchase_cost: 0,
    additional_costs: 0,
    residual_value: 0,
    useful_life: 5,
    current_value: 0,
    acquisition_date: '',
    depreciation_method: 'straight-line',
    valuation_date: '',
    notes: ''
  });

  const isDark = theme === 'dark';
  const t = language === 'en' ? englishTranslations : amharicTranslations;

  useEffect(() => {
    fetchAssets();
  }, []);

  const fetchAssets = async () => {
    setLoading(true);
    try {
      const response = await axios.get('/api/finance/valuation', { 
        params: { 
          limit: 1000,
          include_financial: true 
        } 
      });
      const assetData = response.data.assets || [];
      // Enrich assets with calculated financial data
      const enrichedAssets = assetData.map(asset => ({
        ...asset,
        financial: calculateFinancialData(asset)
      }));
      setAssets(enrichedAssets);
    } catch (error) {
      toast.error(t.fetchError || 'Failed to load assets');
      setAssets([]);
    }
    setLoading(false);
  };

  const calculateFinancialData = (asset) => {
    const purchaseCost = asset.purchase_cost || 0;
    const additionalCosts = asset.additional_costs || 0;
    const totalCost = purchaseCost + additionalCosts;
    const residualValue = asset.residual_value || (totalCost * 0.1);
    const usefulLife = asset.useful_life || 5;

    // Calculate depreciation based on straight-line method
    const yearsSincePurchase = asset.purchase_date 
      ? Math.max(0, (Date.now() - new Date(asset.purchase_date).getTime()) / (1000 * 60 * 60 * 24 * 365))
      : 0;

    const annualDepreciation = (totalCost - residualValue) / usefulLife;
    const accumulatedDepreciation = Math.min(annualDepreciation * yearsSincePurchase, totalCost - residualValue);
    const bookValue = Math.max(totalCost - accumulatedDepreciation, residualValue);
    const depreciationPercentage = totalCost > 0 ? (accumulatedDepreciation / totalCost) * 100 : 0;

    return {
      totalCost,
      residualValue,
      usefulLife,
      annualDepreciation,
      accumulatedDepreciation: Math.round(accumulatedDepreciation),
      bookValue: Math.round(bookValue),
      depreciationPercentage: depreciationPercentage.toFixed(1),
      remainingLife: Math.max(0, usefulLife - yearsSincePurchase),
      yearsSincePurchase: yearsSincePurchase.toFixed(1)
    };
  };

  const generateFallbackAssets = () => {
    const departments = ['IT', 'Facilities', 'HR', 'Finance', 'Operations', 'Marketing', 'Production'];
    const categories = ['Hardware', 'Software', 'Vehicles', 'Furniture', 'Machinery', 'Electronics', 'Building'];
    const statuses = ['Active', 'Under Maintenance', 'Inactive', 'Disposed'];

    return Array.from({ length: 50 }, (_, i) => {
      const purchaseCost = 50000 + Math.random() * 2000000;
      const additionalCosts = Math.round(Math.random() * 10000);
      const totalCost = purchaseCost + additionalCosts;
      const usefulLife = 3 + Math.floor(Math.random() * 7);
      const residualValue = Math.round(totalCost * (0.05 + Math.random() * 0.15));
      const purchaseDate = new Date(2018 + Math.floor(Math.random() * 6), Math.floor(Math.random() * 12), Math.floor(Math.random() * 28));
      const yearsSincePurchase = Math.max(0, (Date.now() - purchaseDate.getTime()) / (1000 * 60 * 60 * 24 * 365));
      const annualDepreciation = (totalCost - residualValue) / usefulLife;
      const accumulatedDepreciation = Math.min(annualDepreciation * yearsSincePurchase, totalCost - residualValue);
      const bookValue = Math.max(totalCost - accumulatedDepreciation, residualValue);

      return {
        id: `asset_${i + 1}`,
        asset_tag: `ICT-${String(i + 1).padStart(4, '0')}`,
        name: `${categories[i % categories.length]} ${i + 1}`,
        description: `Description for asset ${i + 1}`,
        department_name: departments[i % departments.length],
        category_name: categories[i % categories.length],
        status: statuses[i % statuses.length],
        purchase_cost: purchaseCost,
        additional_costs: additionalCosts,
        residual_value: residualValue,
        useful_life: usefulLife,
        purchase_date: purchaseDate.toISOString(),
        current_value: bookValue,
        valuation_status: i % 5 === 0 ? 'Due' : i % 7 === 0 ? 'Overdue' : 'Current',
        financial: {
          totalCost,
          residualValue,
          usefulLife,
          annualDepreciation,
          accumulatedDepreciation: Math.round(accumulatedDepreciation),
          bookValue: Math.round(bookValue),
          depreciationPercentage: ((accumulatedDepreciation / totalCost) * 100).toFixed(1),
          remainingLife: Math.max(0, usefulLife - yearsSincePurchase),
          yearsSincePurchase: yearsSincePurchase.toFixed(1)
        }
      };
    });
  };

  const handleAssetSelect = (asset) => {
    setSelectedAsset(asset);
    setFormData({
      purchase_cost: asset.purchase_cost || 0,
      additional_costs: asset.additional_costs || 0,
      residual_value: asset.residual_value || 0,
      useful_life: asset.useful_life || 5,
      current_value: asset.current_value || 0,
      acquisition_date: asset.purchase_date || '',
      depreciation_method: 'straight-line',
      valuation_date: new Date().toISOString().split('T')[0],
      notes: ''
    });
    setModalMode('view');
    setShowModal(true);
    fetchValuationHistory(asset.id);
  };

  const fetchValuationHistory = async (assetId) => {
    try {
      const response = await axios.get(`/api/finance/assets/${assetId}/valuation-history`);
      setValuationHistory(response.data.history || []);
    } catch (error) {
      setValuationHistory([]);
    }
  };

  const handleSaveValuation = async () => {
    try {
      const updatedAsset = {
        ...selectedAsset,
        purchase_cost: formData.purchase_cost,
        additional_costs: formData.additional_costs,
        residual_value: formData.residual_value,
        useful_life: formData.useful_life,
        current_value: formData.current_value,
        purchase_date: formData.acquisition_date,
        valuation_date: formData.valuation_date,
        valuation_notes: formData.notes
      };

      await axios.put(`/api/finance/valuation/${selectedAsset.id}`, updatedAsset);

      toast.success(t.valuationSaved || 'Valuation updated successfully');
      setShowModal(false);
      fetchAssets();
    } catch (error) {
      toast.error(t.saveError || 'Failed to save valuation');
    }
  };

  const handleRevalue = async () => {
    try {
      const newValue = formData.current_value;
      // In a real app, make API call here
      // await axios.post(`/api/assets/${selectedAsset.id}/revalue`, { value: newValue, notes: formData.notes });

