import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { useLanguage } from '../../contexts/UiContext';
import { toast } from 'react-toastify';
import axios from 'axios';
import { QRCodeCanvas } from 'qrcode.react';
import * as XLSX from 'xlsx';
import jsPDF from 'jspdf';
import 'jspdf-autotable';

const ICTAssets = () => {
  const navigate = useNavigate();
  const { language, theme } = useLanguage();

  // State
  const [assets, setAssets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedAsset, setSelectedAsset] = useState(null);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showQRModal, setShowQRModal] = useState(false);
  const [departments, setDepartments] = useState([]);
  const [categories, setCategories] = useState([]);
  const [editingAsset, setEditingAsset] = useState(null);

  // Filters
  const [filters, setFilters] = useState({
    search: '',
    category: 'all',
    status: 'all',
    condition: 'all',
    department: 'all',
    location: 'all',
    dateFrom: '',
    dateTo: '',
    warrantyStatus: 'all'
  });

  // Pagination
  const [pagination, setPagination] = useState({
    currentPage: 1,
    itemsPerPage: 20,
    totalItems: 0,
    totalPages: 0
  });

  const isDark = theme === 'dark';
  const t = language === 'en' ? englishTranslations : amharicTranslations;

  // Fetch assets with filters
  const fetchAssets = useCallback(async () => {
    setLoading(true);
    try {
      const params = {
        limit: pagination.itemsPerPage,
        offset: (pagination.currentPage - 1) * pagination.itemsPerPage,
        ...filters
      };

      // Remove 'all' values
      Object.keys(params).forEach(key => {
        if (params[key] === 'all' || params[key] === '') {
          delete params[key];
        }
      });

      const response = await axios.get('/api/assets', { params });
      setAssets(response.data.assets || []);
      setPagination(prev => ({
        ...prev,
        totalItems: response.data.total || 0,
        totalPages: Math.ceil((response.data.total || 0) / prev.itemsPerPage)
      }));
    } catch (error) {
      toast.error('Failed to load assets');
    }
    setLoading(false);
  }, [filters, pagination.currentPage, pagination.itemsPerPage]);

  // Fetch options
  useEffect(() => {
    const fetchOptions = async () => {
      try {
        const [deptsRes, catsRes] = await Promise.all([
          axios.get('/api/departments'),
          axios.get('/api/categories')
        ]);
        setDepartments(deptsRes.data.departments || []);
        setCategories(catsRes.data.categories || []);
      } catch (error) {
        console.error('Failed to load options');
      }
    };
    fetchOptions();
  }, []);

  useEffect(() => {
    fetchAssets();
  }, [fetchAssets]);

  // Handle filter changes
  const handleFilterChange = (key, value) => {
    setFilters(prev => ({ ...prev, [key]: value }));
    setPagination(prev => ({ ...prev, currentPage: 1 }));
  };

  // Handle search
  const handleSearch = (e) => {
    e.preventDefault();
    fetchAssets();
  };

  // View asset details
  const handleViewAsset = async (assetId) => {
    try {
      const response = await axios.get(`/api/assets/${assetId}`);
      setSelectedAsset(response.data.asset);
      setShowDetailModal(true);
    } catch (error) {
      toast.error('Failed to load asset details');
    }
  };

  // Edit asset
  const handleEditAsset = (asset) => {
    setEditingAsset({ ...asset });
    setShowEditModal(true);
  };

  const handleEditSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      await axios.put(`/api/assets/${editingAsset.id}`, editingAsset);
      toast.success('Asset updated successfully');
      setShowEditModal(false);
      fetchAssets();
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to update asset');
    }
    setLoading(false);
  };

  // Delete asset
  const handleDeleteAsset = async (assetId) => {
    if (!window.confirm('Are you sure you want to delete this asset?')) return;
    try {
      await axios.delete(`/api/assets/${assetId}`);
      toast.success('Asset deleted successfully');
      fetchAssets();
    } catch (error) {
      toast.error('Failed to delete asset');
    }
  };

  // Export to Excel
  const exportToExcel = () => {
    const exportData = assets.map(asset => ({
      'Asset ID': asset.id,
      'Name': asset.name,
      'Category': asset.category_name,
      'Brand': asset.brand,
      'Model': asset.model,
      'Serial Number': asset.serial_number,
      'RFID': asset.rfid_tag,
      'Status': asset.status,
      'Condition': asset.condition_status,
      'Department': asset.department_name,
      'Location': asset.location,
      'Purchase Date': asset.purchase_date,
      'Purchase Cost': asset.purchase_cost,
      'Warranty Expiry': asset.warranty_expiry
    }));

    const wb = XLSX.utils.book_new();
    const ws = XLSX.utils.json_to_sheet(exportData);
    XLSX.utils.book_append_sheet(wb, ws, 'ICT Assets');
    XLSX.writeFile(wb, `ICT_Assets_${new Date().toISOString().split('T')[0]}.xlsx`);
    toast.success('Export successful');
  };

  // Export to PDF
  const exportToPDF = () => {
    const doc = new jsPDF();
    doc.text('ICT Assets Report', 14, 15);
