      fontWeight: 700,
      color: isDark ? '#c8dcf5' : '#1a365d',
      margin: '16px 0 12px 0',
      paddingBottom: '8px',
      borderBottom: `2px solid ${isDark ? '#32465f' : '#e8edf5'}`
