          <div style={styles.statNumber}>{users.length}</div>
          <div style={styles.statLabel}>{t.totalUsers}</div>
        </div>
      </div>

      {/* Assign Form */}
      <div style={styles.card}>
        <h3 style={{ color: isDark ? '#c8dcf5' : '#1a365d', marginBottom: '16px' }}>
