    },
    statusBadge: (status) => {
      const colors = {
        'Pending': { bg: 'rgba(237, 137, 54, 0.15)', text: '#ed8936' },
        'Approved': { bg: 'rgba(43, 108, 176, 0.15)', text: '#4299e1' },
        'Assigned': { bg: 'rgba(43, 108, 176, 0.15)', text: '#4299e1' },
        'In Progress': { bg: 'rgba(237, 137, 54, 0.15)', text: '#ed8936' },
