        'Completed': { bg: 'rgba(72, 187, 120, 0.15)', text: '#48bb78' },
        'Rejected': { bg: 'rgba(252, 129, 129, 0.15)', text: '#fc8181' },
        'Cancelled': { bg: 'rgba(252, 129, 129, 0.15)', text: '#fc8181' }
      };
      const color = colors[status] || { bg: 'rgba(128, 90, 213, 0.15)', text: '#805ad5' };
      return {
