      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.95rem',
      marginBottom: '4px'
    },
    textarea: {
      width: '100%',
      padding: '10px 14px',
      borderRadius: '8px',
      border: `1px solid ${isDark ? '#32465f' : '#d0d8e8'}`,
      background: isDark ? '#0d1b2a' : '#f7fafc',
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.95rem',
      minHeight: '60px',
      resize: 'vertical',
      marginBottom: '4px'
    },
    select: {
      width: '100%',
      padding: '10px 14px',
      borderRadius: '8px',
      border: `1px solid ${isDark ? '#32465f' : '#d0d8e8'}`,
      background: isDark ? '#0d1b2a' : '#f7fafc',
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.95rem',
      cursor: 'pointer',
      marginBottom: '4px'
    },
    actionButton: (color) => ({
      padding: '4px 10px',
      borderRadius: '4px',
      border: 'none',
      cursor: 'pointer',
      fontSize: '12px',
      background: color,
      color: 'white',
      marginRight: '4px'
    }),
    emptyState: {
      textAlign: 'center',
      padding: '40px',
      color: isDark ? '#8896b0' : '#4a5568'
    }
  };

  const filteredRequests = getFilteredRequests();

  if (loading) {
    return <div style={styles.emptyState}>⏳ {t.loading}</div>;
  }

  return (
    <div style={styles.container}>
      {/* Header */}
      <div style={styles.header}>
        <div>
          <h1 style={styles.title}>🔧 {t.maintenance}</h1>
          <p style={styles.subtitle}>{t.maintenanceDesc}</p>
        </div>
        <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
          <button style={styles.button()} onClick={() => setShowCreateModal(true)}>
            ➕ {t.newRequest}
          </button>
          <button style={styles.button('linear-gradient(135deg, #48bb78, #68d391)')} onClick={exportToPDF}>
            📊 {t.exportPDF}
