        </div>
        <div style={styles.statCard}>
          <div style={styles.statNumber}>{stats.readers}</div>
          <div style={styles.statLabel}>{t.readers}</div>
        </div>
        <div style={styles.statCard}>
          <div style={styles.statNumber}>{stats.locations}</div>
          <div style={styles.statLabel}>{t.locations}</div>
