                  {reportType === 'inventory' && (
                    <>
                      <td style={styles.td}>{item.name}</td>
                      <td style={styles.td}>{item.category || '-'}</td>
                      <td style={styles.td}>{item.quantity || 0}</td>
                      <td style={styles.td}>{item.min_quantity || 0}</td>
                      <td style={styles.td}>
                        <span style={styles.statusBadge(
