import React, { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useLanguage } from '../../contexts/UiContext';
import { toast } from 'react-toastify';
import axios from 'axios';
import jsPDF from 'jspdf';
import 'jspdf-autotable';

const MaintAssigned = () => {
  const { user } = useAuth();
  const { language, theme } = useLanguage();

  // State
  const [tasks, setTasks] = useState([]);
  const [allRequests, setAllRequests] = useState([]);
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedTask, setSelectedTask] = useState(null);
  const [showDetail, setShowDetail] = useState(false);
  const [showReassign, setShowReassign] = useState(false);
  const [showComplete, setShowComplete] = useState(false);
  const [showAddDiagnosis, setShowAddDiagnosis] = useState(false);
  const [filterStatus, setFilterStatus] = useState('');
  const [filterPriority, setFilterPriority] = useState('');
  const [reassignData, setReassignData] = useState({ technician: '', reason: '' });
  const [completeData, setCompleteData] = useState({
    resolution: '',
    actual_cost: '',
    parts_used: '',
    notes: ''
  });
  const [diagnosisData, setDiagnosisData] = useState({
    diagnosis: '',
    repair_details: '',
    parts_used: '',
    estimated_completion: ''
  });

  const isDark = theme === 'dark';
  const t = language === 'en' ? englishTranslations : amharicTranslations;

  // Status options
  const statuses = ['Assigned', 'In Progress', 'Waiting for Parts', 'Testing', 'Completed', 'On Hold'];
  const priorities = ['Low', 'Medium', 'High', 'Critical'];

  useEffect(() => {
    fetchTasks();
  }, [filterStatus, filterPriority]);

  const fetchTasks = async () => {
    setLoading(true);
    try {
      const params = { limit: 500, scope: 'assigned' };
      if (filterStatus) params.status = filterStatus;
      if (filterPriority) params.priority = filterPriority;

      const response = await axios.get('/api/maintenance', { params });
      const requests = response.data.requests || [];

      // Filter tasks assigned to current user or all assigned tasks (for ICT Officer view)
      const assignedTasks = requests.filter(r => 
        r.assigned_to === user?.id || 
        (r.status !== 'Pending' && r.status !== 'Approved' && r.status !== 'Rejected' && r.status !== 'Cancelled')
      );

      setTasks(assignedTasks);
      setAllRequests(requests);

      // Get users for reassignment
      const usersRes = await axios.get('/api/users', { params: { limit: 500 } });
      setUsers(usersRes.data.users || []);
    } catch (error) {
      console.error('Fetch error:', error);
      toast.error('Failed to load assigned tasks');
    }
    setLoading(false);
  };

  // Update task status
  const updateStatus = async (id, status) => {
    try {
      await axios.patch(`/api/maintenance/${id}/status`, { status });
      toast.success(`Task status updated to ${status}`);
      fetchTasks();
    } catch (error) {
      toast.error('Failed to update status');
    }
  };

  // Start work on task
  const startWork = async (id) => {
    try {
      await axios.patch(`/api/maintenance/${id}/start`);
      toast.success('Work started on task');
      fetchTasks();
    } catch (error) {
      toast.error('Failed to start work');
    }
  };

  // Add diagnosis
  const addDiagnosis = async (e) => {
    e.preventDefault();
    try {
      await axios.post(`/api/maintenance/${selectedTask.id}/diagnosis`, diagnosisData);
      toast.success('Diagnosis added successfully');
      setShowAddDiagnosis(false);
      fetchTasks();
    } catch (error) {
      toast.error('Failed to add diagnosis');
    }
  };

  // Complete task
  const completeTask = async (e) => {
    e.preventDefault();
    try {
      await axios.post(`/api/maintenance/${selectedTask.id}/complete`, completeData);
      toast.success('Task completed successfully');
      setShowComplete(false);
      fetchTasks();
    } catch (error) {
      toast.error('Failed to complete task');
    }
  };

  // Reassign task
  const reassignTask = async (e) => {
    e.preventDefault();
    try {
      await axios.post(`/api/maintenance/${selectedTask.id}/reassign`, reassignData);
      toast.success('Task reassigned successfully');
      setShowReassign(false);
      fetchTasks();
    } catch (error) {
      toast.error('Failed to reassign task');
    }
  };

  // View task details
  const viewDetails = (task) => {
    setSelectedTask(task);
    setShowDetail(true);
  };

  // Get status color
  const getStatusColor = (status) => {
    const colors = {
      'Assigned': '#4299e1',
      'In Progress': '#ed8936',
      'Waiting for Parts': '#ed8936',
      'Testing': '#805ad5',
      'Completed': '#48bb78',
      'On Hold': '#fc8181'
    };
    return colors[status] || '#a0aec0';
  };

  // Get priority color
  const getPriorityColor = (priority) => {
    const colors = {
      'Low': '#48bb78',
      'Medium': '#4299e1',
      'High': '#ed8936',
      'Critical': '#fc8181'
    };
    return colors[priority] || '#a0aec0';
  };

  // Get status badge
  const getStatusBadge = (status) => ({
    display: 'inline-block',
    padding: '4px 12px',
    borderRadius: '20px',
    fontSize: '12px',
    fontWeight: 600,
    background: `${getStatusColor(status)}20`,
    color: getStatusColor(status),
    border: `1px solid ${getStatusColor(status)}40`
  });

  // Get priority badge
  const getPriorityBadge = (priority) => ({
    display: 'inline-block',
    padding: '2px 10px',
    borderRadius: '4px',
    fontSize: '11px',
    fontWeight: 700,
    background: `${getPriorityColor(priority)}20`,
    color: getPriorityColor(priority)
  });

  // Calculate stats
  const stats = {
    total: tasks.length,
    assigned: tasks.filter(t => t.status === 'Assigned').length,
    inProgress: tasks.filter(t => t.status === 'In Progress').length,
    waitingParts: tasks.filter(t => t.status === 'Waiting for Parts').length,
    testing: tasks.filter(t => t.status === 'Testing').length,
    completed: tasks.filter(t => t.status === 'Completed').length
  };

  // Styles
  const styles = {
    container: { padding: '20px', maxWidth: '1400px', margin: '0 auto' },
    header: { 
      display: 'flex', 
      justifyContent: 'space-between', 
      alignItems: 'center', 
      flexWrap: 'wrap', 
      gap: '16px', 
      marginBottom: '24px' 
    },
    title: { 
      color: isDark ? '#c8dcf5' : '#1a365d', 
      fontSize: '1.75rem', 
      fontWeight: 700,
      margin: 0
    },
    subtitle: {
      color: isDark ? '#8896b0' : '#4a5568',
      margin: '4px 0 0 0'
    },
    statsRow: {
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fit, minmax(100px, 1fr))',
      gap: '12px',
      marginBottom: '20px'
    },
    statCard: {
      background: isDark ? '#1e2d45' : '#ffffff',
      padding: '12px 16px',
      borderRadius: '8px',
