    statLabel: {
      fontSize: '0.75rem',
      color: isDark ? '#8896b0' : '#4a5568'
    },
    controls: {
      display: 'flex',
      gap: '12px',
      flexWrap: 'wrap',
      marginBottom: '16px'
    },
    select: {
      padding: '10px 16px',
      borderRadius: '8px',
      border: `1px solid ${isDark ? '#32465f' : '#d0d8e8'}`,
      background: isDark ? '#0d1b2a' : '#f7fafc',
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.95rem',
      cursor: 'pointer',
      minWidth: '140px'
