      boxShadow: isDark ? '0 4px 12px rgba(0,0,0,0.3)' : '0 4px 12px rgba(0,0,100,0.06)',
      marginBottom: '16px',
      transition: 'all 0.2s ease',
      cursor: 'pointer'
    },
    cardHeader: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'flex-start',
      flexWrap: 'wrap',
      gap: '12px'
    },
    cardTitle: {
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '1.1rem',
      fontWeight: 600
    },
    metaInfo: {
      display: 'flex',
      gap: '16px',
      flexWrap: 'wrap',
      marginTop: '8px'
    },
    metaItem: {
      color: isDark ? '#8896b0' : '#4a5568',
      fontSize: '0.85rem'
    },
    description: {
      color: isDark ? '#c8dcf5' : '#1a365d',
      marginTop: '8px',
      fontSize: '0.95rem'
    },
    actionButtons: {
      display: 'flex',
      gap: '6px',
      flexWrap: 'wrap',
      marginTop: '12px'
    },
    actionBtn: (bg) => ({
      padding: '6px 14px',
      borderRadius: '4px',
      border: 'none',
      cursor: 'pointer',
      fontSize: '12px',
      fontWeight: 600,
      background: bg,
      color: 'white'
    }),
    modal: {
      position: 'fixed',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      background: 'rgba(0,0,0,0.6)',
      backdropFilter: 'blur(4px)',
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      zIndex: 1000,
      padding: '20px'
    },
    modalContent: {
      background: isDark ? '#1e2d45' : '#ffffff',
      padding: '30px',
      borderRadius: '16px',
      maxWidth: '600px',
      width: '100%',
      maxHeight: '90vh',
      overflow: 'auto'
    },
    modalHeader: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      marginBottom: '20px',
      borderBottom: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      paddingBottom: '16px'
    },
    modalTitle: {
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '1.25rem',
      fontWeight: 700
    },
    modalClose: {
      background: 'none',
      border: 'none',
      fontSize: '1.5rem',
      cursor: 'pointer',
      color: isDark ? '#8896b0' : '#4a5568'
    },
    modalLabel: {
      display: 'block',
      marginBottom: '4px',
      color: isDark ? '#c8dcf5' : '#2d3748',
      fontWeight: 600,
      fontSize: '0.85rem'
    },
    modalInput: {
      width: '100%',
      padding: '10px 14px',
      borderRadius: '8px',
      border: `1px solid ${isDark ? '#32465f' : '#d0d8e8'}`,
      background: isDark ? '#0d1b2a' : '#f7fafc',
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.95rem',
      marginBottom: '12px'
    },
    modalSelect: {
      width: '100%',
      padding: '10px 14px',
      borderRadius: '8px',
      border: `1px solid ${isDark ? '#32465f' : '#d0d8e8'}`,
      background: isDark ? '#0d1b2a' : '#f7fafc',
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.95rem',
      marginBottom: '12px',
      cursor: 'pointer'
    },
    modalTextarea: {
      width: '100%',
      padding: '10px 14px',
      borderRadius: '8px',
      border: `1px solid ${isDark ? '#32465f' : '#d0d8e8'}`,
      background: isDark ? '#0d1b2a' : '#f7fafc',
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.95rem',
      minHeight: '80px',
      resize: 'vertical',
      marginBottom: '12px'
    },
    grid: {
      display: 'grid',
      gridTemplateColumns: '1fr 1fr',
      gap: '16px'
    },
    fullWidth: {
      gridColumn: '1 / -1'
    },
    emptyState: {
      textAlign: 'center',
      padding: '60px 20px',
      color: isDark ? '#8896b0' : '#4a5568'
    },
    progressBar: {
      width: '100%',
      height: '6px',
      background: isDark ? '#32465f' : '#e8edf5',
      borderRadius: '3px',
      marginTop: '8px',
      overflow: 'hidden'
    },
    progressFill: (percentage) => ({
      width: `${percentage}%`,
      height: '100%',
      background: 'linear-gradient(90deg, #4299e1, #48bb78)',
      borderRadius: '3px',
      transition: 'width 0.3s ease'
    })
  };

  // Get progress percentage based on status
  const getProgress = (status) => {
    const progress = {
      'Assigned': 10,
      'In Progress': 40,
      'Waiting for Parts': 30,
      'Testing': 70,
      'Completed': 100,
      'On Hold': 20
    };
    return progress[status] || 0;
  };

  if (loading) {
    return <div style={styles.emptyState}>⏳ {t.loading}</div>;
  }

  return (
    <div style={styles.container}>
      {/* Header */}
      <div style={styles.header}>
        <div>
          <h1 style={styles.title}>📋 {t.assignedTasks}</h1>
          <p style={styles.subtitle}>{t.tasksDesc}</p>
        </div>
      </div>

      {/* Stats */}
      <div style={styles.statsRow}>
        <div style={styles.statCard}>
          <div style={styles.statNumber}>{stats.total}</div>
          <div style={styles.statLabel}>{t.total}</div>
        </div>
        <div style={styles.statCard}>
          <div style={{...styles.statNumber, color: '#4299e1'}}>{stats.assigned}</div>
          <div style={styles.statLabel}>{t.assigned}</div>
        </div>
        <div style={styles.statCard}>
          <div style={{...styles.statNumber, color: '#ed8936'}}>{stats.inProgress}</div>
          <div style={styles.statLabel}>{t.inProgress}</div>
        </div>
        <div style={styles.statCard}>
          <div style={{...styles.statNumber, color: '#805ad5'}}>{stats.waitingParts}</div>
          <div style={styles.statLabel}>{t.waitingParts}</div>
        </div>
        <div style={styles.statCard}>
          <div style={{...styles.statNumber, color: '#48bb78'}}>{stats.completed}</div>
          <div style={styles.statLabel}>{t.completed}</div>
        </div>
      </div>

      {/* Controls */}
      <div style={styles.controls}>
        <select style={styles.select} value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)}>
          <option value="">{t.allStatus}</option>
          {statuses.map(status => (
            <option key={status} value={status}>{status}</option>
          ))}
        </select>

        <select style={styles.select} value={filterPriority} onChange={(e) => setFilterPriority(e.target.value)}>
          <option value="">{t.allPriority}</option>
          {priorities.map(priority => (
            <option key={priority} value={priority}>{priority}</option>
          ))}
        </select>

        <button style={styles.refreshButton} onClick={fetchTasks}>
          🔄 {t.refresh}
        </button>
      </div>

      {/* Task Cards */}
      {tasks.length === 0 ? (
        <div style={styles.emptyState}>
          <div style={{ fontSize: '3rem', marginBottom: '16px' }}>✅</div>
          <h3>{t.noTasks}</h3>
          <p>{t.noTasksDesc}</p>
        </div>
      ) : (
        tasks.map(task => {
          const progress = getProgress(task.status);
          return (
            <div 
              key={task.id} 
              style={styles.card}
              onMouseEnter={(e) => e.currentTarget.style.borderColor = isDark ? '#63b3ed' : '#2b6cb0'}
              onMouseLeave={(e) => e.currentTarget.style.borderColor = isDark ? '#32465f' : '#e8edf5'}
              onClick={() => viewDetails(task)}
            >
              <div style={styles.cardHeader}>
                <div style={{ flex: 1 }}>
                  <div style={styles.cardTitle}>
                    #{task.request_number || task.id} - {task.title}
                  </div>
                  <div style={styles.metaInfo}>
                    <span style={styles.metaItem}>📦 {task.asset_name || 'N/A'}</span>
                    <span style={{...styles.metaItem, ...getPriorityBadge(task.priority)}}>
                      {task.priority}
                    </span>
                    <span style={{...styles.metaItem, ...getStatusBadge(task.status)}}>
                      {task.status}
                    </span>
                    <span style={styles.metaItem}>📋 {task.type}</span>
                  </div>
                  <div style={styles.description}>
                    {task.description?.substring(0, 100)}{task.description?.length > 100 ? '...' : ''}
                  </div>
                  <div style={styles.metaInfo}>
                    <span style={styles.metaItem}>👤 {task.assigned_to_name || 'Unassigned'}</span>
                    <span style={styles.metaItem}>📅 {new Date(task.created_at).toLocaleDateString()}</span>
                    {task.scheduled_date && (
                      <span style={styles.metaItem}>📆 {new Date(task.scheduled_date).toLocaleDateString()}</span>
                    )}
                  </div>

                  {/* Progress Bar */}
                  <div style={styles.progressBar}>
                    <div style={styles.progressFill(progress)} />
                  </div>
                  <span style={{ fontSize: '11px', color: isDark ? '#8896b0' : '#4a5568' }}>
                    {progress}% {t.complete}
                  </span>
                </div>
              </div>

              {/* Action Buttons */}
              <div style={styles.actionButtons} onClick={(e) => e.stopPropagation()}>
                <button style={styles.actionBtn('#4299e1')} onClick={() => viewDetails(task)}>
                  👁️ {t.view}
                </button>

                {task.status === 'Assigned' && (
                  <button style={styles.actionBtn('#ed8936')} onClick={() => startWork(task.id)}>
                    ▶️ {t.startWork}
                  </button>
                )}

                {task.status !== 'Completed' && task.status !== 'On Hold' && (
                  <>
                    <button style={styles.actionBtn('#805ad5')} onClick={() => {
                      setSelectedTask(task);
                      setShowAddDiagnosis(true);
                    }}>
                      📝 {t.addDiagnosis}
                    </button>
                    <button style={styles.actionBtn('#48bb78')} onClick={() => {
                      setSelectedTask(task);
                      setShowComplete(true);
                    }}>
                      ✅ {t.complete}
                    </button>
                  </>
                )}

                <button style={styles.actionBtn('#ed8936')} onClick={() => {
                  setSelectedTask(task);
                  setShowReassign(true);
                }}>
                  🔄 {t.reassign}
                </button>

                <select 
                  style={{...styles.select, padding: '4px 8px', fontSize: '11px', minWidth: '120px'}}
                  onChange={(e) => updateStatus(task.id, e.target.value)}
                  value={task.status}
                  onClick={(e) => e.stopPropagation()}
                >
                  {statuses.map(status => (
                    <option key={status} value={status}>{status}</option>
                  ))}
                </select>
              </div>
            </div>
          );
        })
      )}

      {/* Detail Modal */}
      {showDetail && selectedTask && (
        <div style={styles.modal} onClick={() => setShowDetail(false)}>
          <div style={styles.modalContent} onClick={e => e.stopPropagation()}>
            <div style={styles.modalHeader}>
              <h3 style={styles.modalTitle}>📋 {t.taskDetails}</h3>
              <button style={styles.modalClose} onClick={() => setShowDetail(false)}>✕</button>
            </div>

            <div style={styles.grid}>
              <div>
                <label style={styles.modalLabel}>{t.taskNumber}</label>
                <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc'}}>
                  #{selectedTask.request_number || selectedTask.id}
                </div>
              </div>
              <div>
                <label style={styles.modalLabel}>{t.status}</label>
                <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc'}}>
                  <span style={getStatusBadge(selectedTask.status)}>{selectedTask.status}</span>
                </div>
              </div>
              <div style={styles.fullWidth}>
                <label style={styles.modalLabel}>{t.title}</label>
                <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc', fontWeight: 600}}>
                  {selectedTask.title}
                </div>
              </div>
              <div style={styles.fullWidth}>
                <label style={styles.modalLabel}>{t.description}</label>
                <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc', minHeight: '60px'}}>
                  {selectedTask.description}
                </div>
              </div>
              <div>
                <label style={styles.modalLabel}>{t.asset}</label>
                <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc'}}>
                  {selectedTask.asset_name} ({selectedTask.asset_tag})
                </div>
              </div>
              <div>
                <label style={styles.modalLabel}>{t.priority}</label>
                <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc'}}>
                  <span style={getPriorityBadge(selectedTask.priority)}>{selectedTask.priority}</span>
                </div>
              </div>
              <div>
                <label style={styles.modalLabel}>{t.type}</label>
                <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc'}}>
                  {selectedTask.type}
                </div>
              </div>
              <div>
                <label style={styles.modalLabel}>{t.technician}</label>
                <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc'}}>
                  {selectedTask.assigned_to_name || 'Unassigned'}
                </div>
              </div>
              <div>
                <label style={styles.modalLabel}>{t.created}</label>
                <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc'}}>
                  {new Date(selectedTask.created_at).toLocaleString()}
                </div>
              </div>
              <div>
                <label style={styles.modalLabel}>{t.scheduledDate}</label>
                <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc'}}>
                  {selectedTask.scheduled_date ? new Date(selectedTask.scheduled_date).toLocaleDateString() : 'N/A'}
                </div>
              </div>
              {selectedTask.diagnosis && (
                <div style={styles.fullWidth}>
                  <label style={styles.modalLabel}>{t.diagnosis}</label>
                  <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc', minHeight: '40px'}}>
                    {selectedTask.diagnosis}
                  </div>
                </div>
              )}
              {selectedTask.repair && (
                <div style={styles.fullWidth}>
                  <label style={styles.modalLabel}>{t.repairDetails}</label>
                  <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc', minHeight: '40px'}}>
                    {selectedTask.repair}
                  </div>
                </div>
              )}
              {selectedTask.parts_used && (
                <div>
                  <label style={styles.modalLabel}>{t.partsUsed}</label>
                  <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc'}}>
                    {selectedTask.parts_used}
                  </div>
                </div>
              )}
              {selectedTask.actual_cost && (
                <div>
                  <label style={styles.modalLabel}>{t.actualCost}</label>
                  <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc'}}>
                    ${selectedTask.actual_cost}
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Reassign Modal */}
      {showReassign && selectedTask && (
        <div style={styles.modal} onClick={() => setShowReassign(false)}>
          <div style={styles.modalContent} onClick={e => e.stopPropagation()}>
            <div style={styles.modalHeader}>
              <h3 style={styles.modalTitle}>🔄 {t.reassignTask}</h3>
              <button style={styles.modalClose} onClick={() => setShowReassign(false)}>✕</button>
            </div>

            <form onSubmit={reassignTask}>
              <label style={styles.modalLabel}>{t.selectTechnician} *</label>
              <select 
                style={styles.modalSelect}
                value={reassignData.technician}
                onChange={(e) => setReassignData({...reassignData, technician: e.target.value})}
                required
              >
                <option value="">{t.selectTechnician}</option>
                {users.filter(u => u.id !== user?.id).map(u => (
                  <option key={u.id} value={u.id}>{u.full_name || u.username}</option>
                ))}
              </select>

              <label style={styles.modalLabel}>{t.reason}</label>
              <textarea 
                style={styles.modalTextarea}
                placeholder={t.reasonPlaceholder}
                value={reassignData.reason}
                onChange={(e) => setReassignData({...reassignData, reason: e.target.value})}
              />

              <div style={{ display: 'flex', gap: '12px', marginTop: '12px' }}>
                <button type="submit" style={{...styles.actionBtn('#ed8936'), padding: '10px 24px', fontSize: '14px'}}>
                  ✅ {t.confirmReassign}
                </button>
                <button type="button" style={{...styles.actionBtn('#fc8181'), padding: '10px 24px', fontSize: '14px'}} onClick={() => setShowReassign(false)}>
                  ❌ {t.cancel}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Add Diagnosis Modal */}
      {showAddDiagnosis && selectedTask && (
        <div style={styles.modal} onClick={() => setShowAddDiagnosis(false)}>
          <div style={styles.modalContent} onClick={e => e.stopPropagation()}>
            <div style={styles.modalHeader}>
              <h3 style={styles.modalTitle}>📝 {t.addDiagnosis}</h3>
              <button style={styles.modalClose} onClick={() => setShowAddDiagnosis(false)}>✕</button>
            </div>

            <form onSubmit={addDiagnosis}>
              <label style={styles.modalLabel}>{t.diagnosis} *</label>
              <textarea 
                style={styles.modalTextarea}
                placeholder={t.diagnosisPlaceholder}
                value={diagnosisData.diagnosis}
                onChange={(e) => setDiagnosisData({...diagnosisData, diagnosis: e.target.value})}
                required
              />

              <label style={styles.modalLabel}>{t.repairDetails}</label>
              <textarea 
                style={styles.modalTextarea}
                placeholder={t.repairPlaceholder}
                value={diagnosisData.repair_details}
                onChange={(e) => setDiagnosisData({...diagnosisData, repair_details: e.target.value})}
              />

              <label style={styles.modalLabel}>{t.partsUsed}</label>
              <input 
                type="text"
                style={styles.modalInput}
                placeholder={t.partsPlaceholder}
                value={diagnosisData.parts_used}
                onChange={(e) => setDiagnosisData({...diagnosisData, parts_used: e.target.value})}
              />

              <label style={styles.modalLabel}>{t.estimatedCompletion}</label>
              <input 
                type="date"
                style={styles.modalInput}
                value={diagnosisData.estimated_completion}
                onChange={(e) => setDiagnosisData({...diagnosisData, estimated_completion: e.target.value})}
              />

              <div style={{ display: 'flex', gap: '12px', marginTop: '12px' }}>
                <button type="submit" style={{...styles.actionBtn('#805ad5'), padding: '10px 24px', fontSize: '14px'}}>
                  ✅ {t.saveDiagnosis}
                </button>
                <button type="button" style={{...styles.actionBtn('#fc8181'), padding: '10px 24px', fontSize: '14px'}} onClick={() => setShowAddDiagnosis(false)}>
                  ❌ {t.cancel}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Complete Modal */}
      {showComplete && selectedTask && (
        <div style={styles.modal} onClick={() => setShowComplete(false)}>
          <div style={styles.modalContent} onClick={e => e.stopPropagation()}>
            <div style={styles.modalHeader}>
              <h3 style={styles.modalTitle}>✅ {t.completeTask}</h3>
              <button style={styles.modalClose} onClick={() => setShowComplete(false)}>✕</button>
            </div>

            <form onSubmit={completeTask}>
              <label style={styles.modalLabel}>{t.resolution} *</label>
              <textarea 
                style={styles.modalTextarea}
                placeholder={t.resolutionPlaceholder}
                value={completeData.resolution}
                onChange={(e) => setCompleteData({...completeData, resolution: e.target.value})}
                required
              />

              <label style={styles.modalLabel}>{t.actualCost}</label>
              <input 
                type="number"
                style={styles.modalInput}
                placeholder="0.00"
                value={completeData.actual_cost}
                onChange={(e) => setCompleteData({...completeData, actual_cost: e.target.value})}
                step="0.01"
                min="0"
              />

              <label style={styles.modalLabel}>{t.partsUsed}</label>
              <input 
                type="text"
                style={styles.modalInput}
                placeholder={t.partsPlaceholder}
                value={completeData.parts_used}
                onChange={(e) => setCompleteData({...completeData, parts_used: e.target.value})}
              />

              <label style={styles.modalLabel}>{t.notes}</label>
              <textarea 
                style={styles.modalTextarea}
                placeholder={t.notesPlaceholder}
                value={completeData.notes}
                onChange={(e) => setCompleteData({...completeData, notes: e.target.value})}
              />

              <div style={{ display: 'flex', gap: '12px', marginTop: '12px' }}>
                <button type="submit" style={{...styles.actionBtn('#48bb78'), padding: '10px 24px', fontSize: '14px'}}>
                  ✅ {t.confirmComplete}
                </button>
                <button type="button" style={{...styles.actionBtn('#fc8181'), padding: '10px 24px', fontSize: '14px'}} onClick={() => setShowComplete(false)}>
                  ❌ {t.cancel}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

