import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useLanguage } from '../../contexts/UiContext';
import { Chart as ChartJS, CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend, ArcElement, PointElement, LineElement, Filler } from 'chart.js';
import { Bar, Doughnut, Line } from 'react-chartjs-2';
import { toast } from 'react-toastify';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend, ArcElement, PointElement, LineElement, Filler);

const MaintDashboard = () => {
  const { user } = useAuth();
  const { language, theme } = useLanguage();
  const navigate = useNavigate();

  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({
    totalRequests: 0,
    pending: 0,
    approved: 0,
    assigned: 0,
    inProgress: 0,
    completed: 0,
    rejected: 0,
    overdue: 0,
    emergency: 0,
    totalCost: 0,
    avgCompletionTime: 0,
    byPriority: {},
    byType: {},
    monthlyTrends: [],
    recentRequests: [],
    technicianWorkload: [],
    assetConditionSummary: []
  });

  const isDark = theme === 'dark';
  const t = language === 'en' ? englishTranslations : amharicTranslations;

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    setLoading(true);
    try {
      const response = await axios.get('/api/maintenance/dashboard');
      const data = response.data;

      // If API doesn't have dedicated dashboard endpoint, calculate from requests
      if (!data || !data.totalRequests) {
        const requestsRes = await axios.get('/api/maintenance', { params: { limit: 1000 } });
        const requests = requestsRes.data.requests || [];

        // Calculate statistics
        const byPriority = requests.reduce((acc, m) => {
          acc[m.priority] = (acc[m.priority] || 0) + 1;
          return acc;
        }, {});

        const byType = requests.reduce((acc, m) => {
          acc[m.maintenance_type || m.type] = (acc[m.maintenance_type || m.type] || 0) + 1;
          return acc;
        }, {});

        const now = new Date();
        const overdue = requests.filter(r => 
          r.status !== 'Completed' && 
          r.status !== 'Rejected' && 
          r.status !== 'Cancelled' &&
          r.scheduled_date && 
          new Date(r.scheduled_date) < now
        ).length;

        const totalCost = requests.reduce((sum, r) => sum + (parseFloat(r.cost) || 0), 0);

        // Technician workload
        const technicianMap = {};
        requests.forEach(r => {
          if (r.assigned_to_name && r.status !== 'Completed' && r.status !== 'Rejected') {
            technicianMap[r.assigned_to_name] = (technicianMap[r.assigned_to_name] || 0) + 1;
          }
        });
        const technicianWorkload = Object.entries(technicianMap).map(([name, count]) => ({ name, count }));

        // Monthly trends (last 6 months)
        const monthlyTrends = [];
        for (let i = 5; i >= 0; i--) {
          const date = new Date();
          date.setMonth(date.getMonth() - i);
          const month = date.toLocaleString('default', { month: 'short' });
          const year = date.getFullYear();
          const monthStart = new Date(year, date.getMonth(), 1);
          const monthEnd = new Date(year, date.getMonth() + 1, 0);

          const count = requests.filter(r => {
            const created = new Date(r.created_at);
            return created >= monthStart && created <= monthEnd;
          }).length;

          monthlyTrends.push({ month: `${month} ${year}`, count });
        }

        setStats({
          totalRequests: requests.length,
          pending: requests.filter(r => r.status === 'Pending').length,
          approved: requests.filter(r => r.status === 'Approved').length,
          assigned: requests.filter(r => r.status === 'Assigned').length,
          inProgress: requests.filter(r => r.status === 'In Progress' || r.status === 'In-Progress').length,
          completed: requests.filter(r => r.status === 'Completed').length,
          rejected: requests.filter(r => r.status === 'Rejected' || r.status === 'Cancelled').length,
          overdue: overdue,
          emergency: requests.filter(r => r.priority === 'Critical' && r.status !== 'Completed').length,
          totalCost: totalCost,
          avgCompletionTime: calculateAvgCompletionTime(requests),
          byPriority: byPriority,
          byType: byType,
          monthlyTrends: monthlyTrends,
          recentRequests: requests.slice(0, 10),
          technicianWorkload: technicianWorkload.slice(0, 5),
          assetConditionSummary: []
        });
      } else {
        setStats(data);
      }
    } catch (error) {
      console.error('Dashboard fetch error:', error);
      toast.error('Failed to load dashboard data');
    }
    setLoading(false);
  };

  const calculateAvgCompletionTime = (requests) => {
    const completed = requests.filter(r => 
      r.status === 'Completed' && r.completed_at && r.created_at
    );
    if (completed.length === 0) return 0;

    const totalDays = completed.reduce((sum, r) => {
      const days = (new Date(r.completed_at) - new Date(r.created_at)) / (1000 * 60 * 60 * 24);
      return sum + days;
    }, 0);

    return totalDays / completed.length;
  };

  const getPriorityColor = (priority) => {
    const colors = {
      'Critical': '#fc8181',
      'High': '#ed8936',
      'Medium': '#4299e1',
      'Low': '#48bb78'
    };
    return colors[priority] || '#718096';
  };

  const getStatusColor = (status) => {
    const colors = {
      'Pending': '#ed8936',
      'Approved': '#4299e1',
      'Assigned': '#4299e1',
      'In Progress': '#ed8936',
      'In-Progress': '#ed8936',
      'Waiting for Parts': '#ed8936',
      'Completed': '#48bb78',
      'Rejected': '#fc8181',
      'Cancelled': '#fc8181'
    };
    return colors[status] || '#718096';
  };

  // Chart data
  const priorityChartData = {
    labels: Object.keys(stats.byPriority).length ? Object.keys(stats.byPriority) : ['No Data'],
    datasets: [{
      label: 'Requests by Priority',
      data: Object.keys(stats.byPriority).length ? Object.values(stats.byPriority) : [0],
      backgroundColor: ['#fc8181', '#ed8936', '#4299e1', '#48bb78'],
      borderColor: isDark ? '#1e2d45' : '#ffffff',
      borderWidth: 2
    }]
  };

  const typeChartData = {
    labels: Object.keys(stats.byType).length ? Object.keys(stats.byType) : ['No Data'],
    datasets: [{
      label: 'Requests by Type',
      data: Object.keys(stats.byType).length ? Object.values(stats.byType) : [0],
      backgroundColor: ['#2b6cb0', '#48bb78', '#ed8936', '#805ad5'],
      borderColor: isDark ? '#1e2d45' : '#ffffff',
      borderWidth: 2
    }]
  };

  const trendChartData = {
    labels: stats.monthlyTrends.map(item => item.month),
    datasets: [{
      label: 'Maintenance Requests',
      data: stats.monthlyTrends.map(item => item.count),
      borderColor: '#4299e1',
      backgroundColor: isDark ? 'rgba(66, 153, 225, 0.2)' : 'rgba(66, 153, 225, 0.1)',
      fill: true,
      tension: 0.4
    }]
  };

  const chartOptions = {
    responsive: true,
    plugins: {
      legend: {
        position: 'bottom',
        labels: {
          color: isDark ? '#c8dcf5' : '#1a365d',
          padding: 20
        }
      }
    },
    scales: {
      y: {
        ticks: { color: isDark ? '#8896b0' : '#4a5568' },
        grid: { color: isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.05)' }
      },
      x: {
        ticks: { color: isDark ? '#8896b0' : '#4a5568' },
        grid: { color: isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.05)' }
      }
    }
  };

  const styles = {
    container: { padding: '20px', maxWidth: '1400px', margin: '0 auto' },
    header: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px', flexWrap: 'wrap', gap: '16px' },
    title: { color: isDark ? '#c8dcf5' : '#1a365d', fontSize: '1.75rem', fontWeight: 700, margin: 0 },
    subtitle: { color: isDark ? '#8896b0' : '#4a5568', margin: '4px 0 0 0' },
    dateTime: { fontSize: '0.85rem', color: isDark ? '#8896b0' : '#4a5568' },
    statsGrid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))', gap: '16px', marginBottom: '30px' },
    statCard: { 
      background: isDark ? '#1e2d45' : '#ffffff', 
      padding: '16px 20px', 
      borderRadius: '12px', 
      border: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      boxShadow: isDark ? '0 4px 12px rgba(0,0,0,0.3)' : '0 4px 12px rgba(0,0,100,0.06)',
      display: 'flex',
      alignItems: 'center',
      gap: '16px',
      cursor: 'pointer',
      transition: 'all 0.2s ease'
    },
    statIcon: (bg) => ({ 
      background: bg, 
      borderRadius: '10px', 
      padding: '12px', 
      color: 'white', 
      fontSize: '1.5rem',
      minWidth: '44px',
      textAlign: 'center'
    }),
    statNumber: { fontSize: '1.75rem', fontWeight: 700, color: isDark ? '#c8dcf5' : '#1a365d' },
    statLabel: { fontSize: '0.85rem', color: isDark ? '#8896b0' : '#4a5568' },
    statSubLabel: { fontSize: '0.7rem', color: isDark ? '#8896b0' : '#4a5568', opacity: 0.7 },
    chartsGrid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(350px, 1fr))', gap: '24px', marginBottom: '30px' },
    chartCard: { 
      background: isDark ? '#1e2d45' : '#ffffff', 
      padding: '20px', 
      borderRadius: '12px', 
      border: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      boxShadow: isDark ? '0 4px 12px rgba(0,0,0,0.3)' : '0 4px 12px rgba(0,0,100,0.06)'
    },
    chartTitle: { color: isDark ? '#c8dcf5' : '#1a365d', fontSize: '1rem', marginBottom: '16px', fontWeight: 600 },
    activityCard: { 
      background: isDark ? '#1e2d45' : '#ffffff', 
      padding: '20px', 
      borderRadius: '12px', 
      border: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      boxShadow: isDark ? '0 4px 12px rgba(0,0,0,0.3)' : '0 4px 12px rgba(0,0,100,0.06)',
      marginBottom: '30px'
    },
    activityItem: { 
      display: 'flex', 
      alignItems: 'center', 
      justifyContent: 'space-between', 
      padding: '12px 16px', 
      borderBottom: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      color: isDark ? '#c8dcf5' : '#1a365d',
      transition: 'all 0.2s ease',
      cursor: 'pointer'
    },
    statusBadge: (status) => ({
      padding: '2px 10px',
      borderRadius: '12px',
      fontSize: '0.75rem',
      fontWeight: 600,
      background: `${getStatusColor(status)}20`,
      color: getStatusColor(status),
      border: `1px solid ${getStatusColor(status)}40`
    }),
    priorityBadge: (priority) => ({
      padding: '2px 8px',
      borderRadius: '4px',
      fontSize: '0.7rem',
      fontWeight: 700,
      background: `${getPriorityColor(priority)}20`,
      color: getPriorityColor(priority)
    }),
    emptyState: { textAlign: 'center', padding: '40px', color: isDark ? '#8896b0' : '#4a5568' },
    alert: (bg) => ({
      background: bg,
      padding: '12px 16px',
      borderRadius: '8px',
      marginBottom: '12px',
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center'
    }),
    alertText: { color: isDark ? '#c8dcf5' : '#1a365d', fontSize: '0.9rem' },
    alertLink: { color: '#4299e1', cursor: 'pointer', fontWeight: 600, textDecoration: 'underline' }
  };

  if (loading) {
    return <div style={styles.emptyState}>⏳ {t.loading}</div>;
  }

  return (
    <div style={styles.container}>
      {/* Header */}
      <div style={styles.header}>
        <div>
          <h1 style={styles.title}>🔧 {t.dashboard}</h1>
          <p style={styles.subtitle}>{t.welcome}, {user?.fullName || user?.username} 👋</p>
        </div>
        <div style={{ textAlign: 'right' }}>
          <div style={styles.dateTime}>
            📅 {new Date().toLocaleDateString()} {new Date().toLocaleTimeString()}
          </div>
        </div>
      </div>

      {/* Overdue Alert */}
      {stats.overdue > 0 && (
        <div style={styles.alert('rgba(252, 129, 129, 0.1)')}>
          <span style={styles.alertText}>
            ⚠️ {stats.overdue} {t.overdueAlerts}
          </span>
          <span style={styles.alertLink} onClick={() => navigate('/ict/maintenance/requests?filter=overdue')}>
            {t.viewOverdue} →
          </span>
        </div>
      )}

      {/* Emergency Alert */}
      {stats.emergency > 0 && (
        <div style={styles.alert('rgba(252, 129, 129, 0.15)')}>
          <span style={styles.alertText}>
            🚨 {stats.emergency} {t.emergencyJobs}
          </span>
          <span style={styles.alertLink} onClick={() => navigate('/ict/maintenance/requests?priority=Critical')}>
            {t.viewEmergency} →
          </span>
        </div>
      )}

      {/* Stats Grid */}
      <div style={styles.statsGrid}>
        <div style={styles.statCard} onClick={() => navigate('/ict/maintenance/requests')}>
          <div style={styles.statIcon('linear-gradient(135deg, #2b6cb0, #4299e1)')}>📋</div>
          <div>
            <div style={styles.statNumber}>{stats.totalRequests}</div>
            <div style={styles.statLabel}>{t.totalRequests}</div>
          </div>
        </div>

        <div style={styles.statCard} onClick={() => navigate('/ict/maintenance/requests?status=Pending')}>
          <div style={styles.statIcon('linear-gradient(135deg, #ed8936, #f6ad55)')}>⏳</div>
          <div>
            <div style={styles.statNumber}>{stats.pending}</div>
            <div style={styles.statLabel}>{t.pending}</div>
          </div>
        </div>

        <div style={styles.statCard} onClick={() => navigate('/ict/maintenance/requests?status=Approved')}>
          <div style={styles.statIcon('linear-gradient(135deg, #4299e1, #63b3ed)')}>✅</div>
          <div>
            <div style={styles.statNumber}>{stats.approved}</div>
