          <div>
            <div style={styles.statNumber}>{stats.assigned}</div>
            <div style={styles.statLabel}>{t.assigned}</div>
          </div>
        </div>

        <div style={styles.statCard} onClick={() => navigate('/ict/maintenance/requests?status=In%20Progress')}>
