        <div style={styles.chartCard}>
          <h3 style={styles.chartTitle}>{t.technicianWorkload}</h3>
          {stats.technicianWorkload.length === 0 ? (
            <div style={styles.emptyState}>{t.noTechnicians}</div>
          ) : (
            <div>
              {stats.technicianWorkload.map((tech, idx) => (
                <div key={idx} style={{ 
                  display: 'flex', 
                  justifyContent: 'space-between', 
                  padding: '8px 0',
                  borderBottom: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`
                }}>
                  <span style={{ color: isDark ? '#c8dcf5' : '#1a365d' }}>{tech.name}</span>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                    <div style={{ 
                      width: '100px', 
                      height: '8px', 
                      background: isDark ? '#32465f' : '#e8edf5',
                      borderRadius: '4px',
                      overflow: 'hidden'
                    }}>
                      <div style={{ 
                        width: `${Math.min(100, (tech.count / Math.max(...stats.technicianWorkload.map(t => t.count))) * 100)}%`,
                        height: '100%',
                        background: '#4299e1',
                        borderRadius: '4px'
                      }} />
                    </div>
                    <span style={{ fontWeight: 600, color: isDark ? '#c8dcf5' : '#1a365d' }}>
                      {tech.count}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Recent Requests */}
      <div style={styles.activityCard}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
          <h3 style={styles.chartTitle}>{t.recentRequests}</h3>
          <span 
            style={{ color: '#4299e1', cursor: 'pointer', fontSize: '0.9rem', fontWeight: 600 }}
            onClick={() => navigate('/ict/maintenance/requests')}
          >
            {t.viewAll} →
          </span>
        </div>
        {stats.recentRequests.length === 0 ? (
          <p style={styles.emptyState}>{t.noRecent}</p>
        ) : (
          stats.recentRequests.map(req => (
            <div 
              key={req.id} 
              style={styles.activityItem}
              onClick={() => navigate(`/ict/maintenance/requests/${req.id}`)}
              onMouseEnter={(e) => e.currentTarget.style.background = isDark ? 'rgba(255,255,255,0.03)' : 'rgba(0,0,0,0.02)'}
              onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
            >
              <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                <span style={styles.priorityBadge(req.priority)}>{req.priority}</span>
                <span style={{ fontWeight: 600 }}>{req.title || req.problem}</span>
                <span style={{ fontSize: '0.85rem', color: isDark ? '#8896b0' : '#4a5568' }}>
                  {req.asset_name}
                </span>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                <span style={styles.statusBadge(req.status)}>{req.status}</span>
                <span style={{ fontSize: '0.8rem', color: isDark ? '#8896b0' : '#4a5568' }}>
                  {req.created_at ? new Date(req.created_at).toLocaleDateString() : ''}
                </span>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

