import React, { useState, useEffect, useCallback } from 'react';
import { useLanguage } from '../../contexts/UiContext';
import { toast } from 'react-toastify';
import axios from 'axios';
import jsPDF from 'jspdf';
import 'jspdf-autotable';
import * as XLSX from 'xlsx';

const MaintHistory = () => {
  const { language, theme } = useLanguage();

  // State
  const [history, setHistory] = useState([]);
  const [filteredHistory, setFilteredHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [filterAsset, setFilterAsset] = useState('');
  const [filterTechnician, setFilterTechnician] = useState('');
  const [filterDateFrom, setFilterDateFrom] = useState('');
  const [filterDateTo, setFilterDateTo] = useState('');
  const [filterDepartment, setFilterDepartment] = useState('');
  const [filterPriority, setFilterPriority] = useState('');
  const [assets, setAssets] = useState([]);
  const [technicians, setTechnicians] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [selectedRecord, setSelectedRecord] = useState(null);
  const [showDetail, setShowDetail] = useState(false);
  const [showPrint, setShowPrint] = useState(false);
  const [showCompare, setShowCompare] = useState(false);
  const [compareRecords, setCompareRecords] = useState([]);

  const isDark = theme === 'dark';
  const t = language === 'en' ? englishTranslations : amharicTranslations;

  // Statistics
  const [stats, setStats] = useState({
    total: 0,
    totalCost: 0,
    averageCost: 0,
    byType: {},
    byPriority: {},
    byTechnician: {}
  });

  useEffect(() => {
    fetchHistory();
  }, []);

  const fetchHistory = async () => {
    setLoading(true);
    try {
      const response = await axios.get('/api/maintenance', {
        params: { status: 'Completed', limit: 500 }
      });

      const data = response.data.requests || [];
      setHistory(data);
      setFilteredHistory(data);

      // Extract filter options
      const assetsList = [...new Set(data.map(item => item.asset_id).filter(Boolean))];
      const techs = [...new Set(data.map(item => item.assigned_to_name).filter(Boolean))];
      const depts = [...new Set(data.map(item => item.department).filter(Boolean))];

      // Get asset details
      const assetsRes = await axios.get('/api/assets', { params: { limit: 500 } });
      setAssets(assetsRes.data.assets || []);
      setTechnicians(techs);
      setDepartments(depts);

      // Calculate statistics
      calculateStats(data);

    } catch (error) {
      console.error('Fetch error:', error);
      toast.error('Failed to load history');
    }
    setLoading(false);
  };

  const calculateStats = (data) => {
    const totalCost = data.reduce((sum, item) => sum + (parseFloat(item.actual_cost) || 0), 0);

    const byType = data.reduce((acc, item) => {
      const type = item.type || 'Unknown';
      acc[type] = (acc[type] || 0) + 1;
      return acc;
    }, {});

    const byPriority = data.reduce((acc, item) => {
      const priority = item.priority || 'Unknown';
      acc[priority] = (acc[priority] || 0) + 1;
      return acc;
    }, {});

    const byTechnician = data.reduce((acc, item) => {
      const tech = item.assigned_to_name || 'Unknown';
      acc[tech] = (acc[tech] || 0) + 1;
      return acc;
    }, {});

    setStats({
      total: data.length,
      totalCost: totalCost,
      averageCost: data.length > 0 ? totalCost / data.length : 0,
      byType: byType,
      byPriority: byPriority,
      byTechnician: byTechnician
    });
  };

  // Apply filters
  const applyFilters = useCallback(() => {
    let filtered = [...history];

    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      filtered = filtered.filter(item =>
        item.title?.toLowerCase().includes(query) ||
        item.request_number?.toLowerCase().includes(query) ||
        item.asset_name?.toLowerCase().includes(query) ||
        item.assigned_to_name?.toLowerCase().includes(query) ||
        item.description?.toLowerCase().includes(query)
      );
    }

    if (filterAsset) {
      filtered = filtered.filter(item => item.asset_id === parseInt(filterAsset));
    }

    if (filterTechnician) {
      filtered = filtered.filter(item => item.assigned_to_name === filterTechnician);
    }

    if (filterDepartment) {
      filtered = filtered.filter(item => item.department === filterDepartment);
    }

    if (filterPriority) {
      filtered = filtered.filter(item => item.priority === filterPriority);
    }

    if (filterDateFrom) {
      filtered = filtered.filter(item => 
        item.completion_date && new Date(item.completion_date) >= new Date(filterDateFrom)
      );
    }

    if (filterDateTo) {
      filtered = filtered.filter(item => 
        item.completion_date && new Date(item.completion_date) <= new Date(filterDateTo)
      );
    }

    setFilteredHistory(filtered);
  }, [history, searchQuery, filterAsset, filterTechnician, filterDepartment, filterPriority, filterDateFrom, filterDateTo]);

  useEffect(() => {
    applyFilters();
  }, [applyFilters]);

  // View record details
  const viewDetails = (record) => {
    setSelectedRecord(record);
    setShowDetail(true);
  };

  // Export to PDF
  const exportToPDF = () => {
    const doc = new jsPDF();
    doc.text('Maintenance History Report', 14, 15);
    doc.text(`Generated: ${new Date().toLocaleString()}`, 14, 25);
    doc.text(`Total Records: ${filteredHistory.length}`, 14, 35);
    doc.text(`Total Cost: $${stats.totalCost.toFixed(2)}`, 14, 45);

    const tableData = filteredHistory.slice(0, 100).map(r => [
      r.request_number || r.id,
      r.title,
      r.asset_name || 'N/A',
      r.assigned_to_name || 'N/A',
      new Date(r.completion_date).toLocaleDateString(),
      `$${(parseFloat(r.actual_cost) || 0).toFixed(2)}`
    ]);

    doc.autoTable({
      head: [['#', 'Title', 'Asset', 'Technician', 'Date', 'Cost']],
      body: tableData,
      startY: 55
    });

    doc.save(`Maintenance_History_${new Date().toISOString().split('T')[0]}.pdf`);
    toast.success('Export successful');
  };

  // Export to Excel
  const exportToExcel = () => {
    const data = filteredHistory.map(r => ({
      'Request #': r.request_number || r.id,
      'Title': r.title,
      'Asset': r.asset_name || 'N/A',
      'Technician': r.assigned_to_name || 'N/A',
      'Priority': r.priority || 'N/A',
      'Type': r.type || 'N/A',
      'Completion Date': r.completion_date ? new Date(r.completion_date).toLocaleDateString() : 'N/A',
      'Cost': parseFloat(r.actual_cost) || 0,
      'Parts Used': r.parts_used || 'N/A',
      'Resolution': r.resolution || r.remarks || 'N/A'
    }));

    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Maintenance History');
    XLSX.writeFile(wb, `Maintenance_History_${new Date().toISOString().split('T')[0]}.xlsx`);
    toast.success('Export successful');
  };

  // Print history
  const printHistory = () => {
    setShowPrint(true);
    setTimeout(() => {
      window.print();
      setShowPrint(false);
    }, 500);
  };

  // Get asset maintenance frequency
  const getAssetFrequency = (assetId) => {
    return history.filter(r => r.asset_id === assetId).length;
  };

  // Get asset total cost
  const getAssetTotalCost = (assetId) => {
    return history
      .filter(r => r.asset_id === assetId)
      .reduce((sum, r) => sum + (parseFloat(r.actual_cost) || 0), 0);
  };

  // Get priority color
  const getPriorityColor = (priority) => {
    const colors = {
      'Low': '#48bb78',
      'Medium': '#4299e1',
      'High': '#ed8936',
      'Critical': '#fc8181'
    };
    return colors[priority] || '#a0aec0';
  };

  const styles = {
    container: { padding: '20px', maxWidth: '1400px', margin: '0 auto' },
    header: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      flexWrap: 'wrap',
      gap: '16px',
      marginBottom: '24px'
    },
    title: {
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '1.75rem',
      fontWeight: 700,
      margin: 0
    },
    subtitle: {
      color: isDark ? '#8896b0' : '#4a5568',
      margin: '4px 0 0 0'
    },
    statsRow: {
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fit, minmax(120px, 1fr))',
      gap: '12px',
      marginBottom: '20px'
    },
    statCard: {
      background: isDark ? '#1e2d45' : '#ffffff',
      padding: '12px 16px',
      borderRadius: '8px',
      border: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      textAlign: 'center'
    },
    statNumber: {
      fontSize: '1.25rem',
      fontWeight: 700,
      color: isDark ? '#c8dcf5' : '#1a365d'
    },
    statLabel: {
      fontSize: '0.75rem',
      color: isDark ? '#8896b0' : '#4a5568'
    },
    filters: {
      display: 'flex',
      gap: '12px',
      flexWrap: 'wrap',
      marginBottom: '16px',
      padding: '16px 20px',
      background: isDark ? '#1e2d45' : '#ffffff',
      borderRadius: '12px',
      border: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`
    },
    input: {
      padding: '10px 16px',
      borderRadius: '8px',
      border: `1px solid ${isDark ? '#32465f' : '#d0d8e8'}`,
      background: isDark ? '#0d1b2a' : '#f7fafc',
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.95rem',
      flex: 1,
      minWidth: '150px'
    },
    select: {
