      cursor: 'pointer',
      transition: 'all 0.2s ease'
    }),
    card: {
      background: isDark ? '#1e2d45' : '#ffffff',
      padding: '16px 20px',
      borderRadius: '12px',
      border: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      marginBottom: '12px',
      transition: 'all 0.2s ease',
      cursor: 'pointer'
    },
    cardHeader: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'flex-start',
      flexWrap: 'wrap',
      gap: '8px'
    },
    cardTitle: {
      fontWeight: 600,
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '1rem'
    },
    metaInfo: {
      display: 'flex',
      gap: '16px',
      flexWrap: 'wrap',
      marginTop: '4px',
