      fontWeight: 600,
      background: '#48bb7820',
      color: '#48bb78',
      border: '1px solid #48bb7840'
    },
    priorityBadge: (priority) => ({
      padding: '2px 10px',
      borderRadius: '4px',
      fontSize: '0.7rem',
