      background: `${getPriorityColor(priority)}20`,
      color: getPriorityColor(priority)
    }),
    detailGrid: {
      display: 'grid',
      gridTemplateColumns: '1fr 1fr',
      gap: '12px'
    },
    detailLabel: {
      fontSize: '0.75rem',
      color: isDark ? '#8896b0' : '#4a5568',
      fontWeight: 600,
      textTransform: 'uppercase',
      letterSpacing: '0.3px'
    },
    detailValue: {
      fontSize: '0.95rem',
      color: isDark ? '#c8dcf5' : '#1a365d',
      marginTop: '2px'
    },
    emptyState: {
      textAlign: 'center',
      padding: '60px 20px',
      color: isDark ? '#8896b0' : '#4a5568'
    },
    modal: {
      position: 'fixed',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      background: 'rgba(0,0,0,0.6)',
      backdropFilter: 'blur(4px)',
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      zIndex: 1000,
      padding: '20px'
    },
    modalContent: {
      background: isDark ? '#1e2d45' : '#ffffff',
