      width: '100%',
      maxHeight: '90vh',
      overflow: 'auto'
    },
    modalHeader: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      marginBottom: '20px',
      borderBottom: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      paddingBottom: '16px'
    },
    modalTitle: {
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '1.25rem',
      fontWeight: 700
    },
    modalClose: {
      background: 'none',
      border: 'none',
      fontSize: '1.5rem',
      cursor: 'pointer',
      color: isDark ? '#8896b0' : '#4a5568'
    }
  };

  if (loading) {
    return <div style={styles.emptyState}>⏳ {t.loading}</div>;
  }

  return (
    <div style={styles.container}>
      {/* Header */}
      <div style={styles.header}>
        <div>
          <h1 style={styles.title}>📜 {t.history}</h1>
          <p style={styles.subtitle}>{t.historyDesc}</p>
        </div>
        <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
          <button style={styles.button('linear-gradient(135deg, #48bb78, #38a169)')} onClick={exportToExcel}>
            📊 {t.exportExcel}
          </button>
          <button style={styles.button('linear-gradient(135deg, #805ad5, #b794f4)')} onClick={exportToPDF}>
            📄 {t.exportPDF}
          </button>
          <button style={styles.button('linear-gradient(135deg, #718096, #4a5568)')} onClick={printHistory}>
            🖨️ {t.print}
          </button>
        </div>
      </div>

      {/* Stats */}
      <div style={styles.statsRow}>
        <div style={styles.statCard}>
          <div style={styles.statNumber}>{stats.total}</div>
          <div style={styles.statLabel}>{t.totalRecords}</div>
        </div>
        <div style={styles.statCard}>
          <div style={styles.statNumber}>${stats.totalCost.toFixed(2)}</div>
          <div style={styles.statLabel}>{t.totalCost}</div>
        </div>
        <div style={styles.statCard}>
          <div style={styles.statNumber}>${stats.averageCost.toFixed(2)}</div>
          <div style={styles.statLabel}>{t.averageCost}</div>
        </div>
        <div style={styles.statCard}>
          <div style={styles.statNumber}>{Object.keys(stats.byType).length}</div>
          <div style={styles.statLabel}>{t.types}</div>
        </div>
        <div style={styles.statCard}>
          <div style={styles.statNumber}>{Object.keys(stats.byTechnician).length}</div>
          <div style={styles.statLabel}>{t.technicians}</div>
