        </select>

        <select
          style={styles.select}
          value={filterPriority}
          onChange={(e) => setFilterPriority(e.target.value)}
        >
          <option value="">{t.allPriority}</option>
          <option value="Critical">{t.critical}</option>
          <option value="High">{t.high}</option>
          <option value="Medium">{t.medium}</option>
          <option value="Low">{t.low}</option>
        </select>

        <input
          type="date"
          style={{...styles.input, minWidth: '130px'}}
          value={filterDateFrom}
          onChange={(e) => setFilterDateFrom(e.target.value)}
          placeholder={t.dateFrom}
        />

        <input
          type="date"
          style={{...styles.input, minWidth: '130px'}}
          value={filterDateTo}
          onChange={(e) => setFilterDateTo(e.target.value)}
          placeholder={t.dateTo}
        />
      </div>

      {/* Records */}
      {filteredHistory.length === 0 ? (
        <div style={styles.emptyState}>
          <div style={{ fontSize: '3rem', marginBottom: '16px' }}>📜</div>
          <h3>{t.noHistory}</h3>
          <p>{t.noHistoryDesc}</p>
        </div>
      ) : (
        filteredHistory.map(item => (
          <div
            key={item.id}
            style={styles.card}
            onMouseEnter={(e) => e.currentTarget.style.borderColor = isDark ? '#63b3ed' : '#2b6cb0'}
            onMouseLeave={(e) => e.currentTarget.style.borderColor = isDark ? '#32465f' : '#e8edf5'}
            onClick={() => viewDetails(item)}
          >
            <div style={styles.cardHeader}>
              <div style={{ flex: 1 }}>
                <div style={styles.cardTitle}>
                  #{item.request_number || item.id} - {item.title}
                </div>
                <div style={styles.metaInfo}>
                  <span>📦 {item.asset_name || 'N/A'}</span>
                  <span>{item.asset_tag || ''}</span>
                  <span style={styles.priorityBadge(item.priority)}>{item.priority}</span>
                  <span>📋 {item.type}</span>
                  <span>🔧 {item.assigned_to_name || 'N/A'}</span>
                  <span>📅 {item.completion_date ? new Date(item.completion_date).toLocaleDateString() : 'N/A'}</span>
                </div>
                {item.resolution && (
                  <div style={{ 
                    marginTop: '4px', 
                    fontSize: '0.85rem', 
                    color: isDark ? '#8896b0' : '#4a5568' 
                  }}>
                    {t.resolution}: {item.resolution}
                  </div>
                )}
                {item.parts_used && (
                  <div style={{ 
                    marginTop: '2px', 
                    fontSize: '0.8rem', 
                    color: isDark ? '#8896b0' : '#4a5568' 
                  }}>
                    {t.parts}: {item.parts_used}
                  </div>
                )}
              </div>
              <div style={{ textAlign: 'right' }}>
                <span style={styles.completedBadge}>✅ {t.completed}</span>
                {item.actual_cost > 0 && (
                  <div style={{ 
                    marginTop: '4px', 
                    fontWeight: 600, 
                    color: isDark ? '#c8dcf5' : '#1a365d' 
                  }}>
                    ${parseFloat(item.actual_cost).toFixed(2)}
                  </div>
                )}
              </div>
            </div>
          </div>
        ))
      )}

      {/* Detail Modal */}
      {showDetail && selectedRecord && (
        <div style={styles.modal} onClick={() => setShowDetail(false)}>
          <div style={styles.modalContent} onClick={e => e.stopPropagation()}>
            <div style={styles.modalHeader}>
              <h3 style={styles.modalTitle}>📜 {t.recordDetails}</h3>
              <button style={styles.modalClose} onClick={() => setShowDetail(false)}>✕</button>
            </div>

            <div style={styles.detailGrid}>
              <div>
                <div style={styles.detailLabel}>{t.requestNumber}</div>
                <div style={styles.detailValue}>#{selectedRecord.request_number || selectedRecord.id}</div>
              </div>
              <div>
                <div style={styles.detailLabel}>{t.status}</div>
                <div style={styles.detailValue}>
                  <span style={styles.completedBadge}>✅ {t.completed}</span>
                </div>
              </div>
              <div style={{ gridColumn: '1 / -1' }}>
                <div style={styles.detailLabel}>{t.title}</div>
                <div style={styles.detailValue}><strong>{selectedRecord.title}</strong></div>
              </div>
              <div style={{ gridColumn: '1 / -1' }}>
                <div style={styles.detailLabel}>{t.description}</div>
                <div style={styles.detailValue}>{selectedRecord.description || 'N/A'}</div>
              </div>
              <div>
                <div style={styles.detailLabel}>{t.asset}</div>
                <div style={styles.detailValue}>{selectedRecord.asset_name} ({selectedRecord.asset_tag})</div>
              </div>
              <div>
                <div style={styles.detailLabel}>{t.priority}</div>
                <div style={styles.detailValue}>
                  <span style={styles.priorityBadge(selectedRecord.priority)}>{selectedRecord.priority}</span>
                </div>
              </div>
              <div>
                <div style={styles.detailLabel}>{t.type}</div>
                <div style={styles.detailValue}>{selectedRecord.type}</div>
              </div>
              <div>
                <div style={styles.detailLabel}>{t.technician}</div>
                <div style={styles.detailValue}>{selectedRecord.assigned_to_name || 'N/A'}</div>
              </div>
              <div>
                <div style={styles.detailLabel}>{t.completionDate}</div>
                <div style={styles.detailValue}>
                  {selectedRecord.completion_date ? new Date(selectedRecord.completion_date).toLocaleString() : 'N/A'}
                </div>
              </div>
              <div>
                <div style={styles.detailLabel}>{t.cost}</div>
                <div style={styles.detailValue}>
                  ${parseFloat(selectedRecord.actual_cost || 0).toFixed(2)}
                </div>
              </div>
              {selectedRecord.parts_used && (
                <div style={{ gridColumn: '1 / -1' }}>
                  <div style={styles.detailLabel}>{t.partsUsed}</div>
                  <div style={styles.detailValue}>{selectedRecord.parts_used}</div>
                </div>
              )}
              {selectedRecord.resolution && (
                <div style={{ gridColumn: '1 / -1' }}>
                  <div style={styles.detailLabel}>{t.resolution}</div>
                  <div style={styles.detailValue}>{selectedRecord.resolution}</div>
                </div>
              )}
              {selectedRecord.remarks && (
                <div style={{ gridColumn: '1 / -1' }}>
                  <div style={styles.detailLabel}>{t.remarks}</div>
                  <div style={styles.detailValue}>{selectedRecord.remarks}</div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

