import React, { useState, useEffect, useMemo } from 'react';
import { useLanguage, useTheme } from '../../contexts/UiContext';
import { toast } from 'react-toastify';
import * as XLSX from 'xlsx';
import jsPDF from 'jspdf';
import 'jspdf-autotable';
import axios from 'axios';
import { Bar, Line, Pie, Doughnut } from 'react-chartjs-2';
import { getDepartmentLabel } from '../../utils/department';
import { 
  Chart as ChartJS, 
  CategoryScale, 
  LinearScale, 
  BarElement, 
  LineElement,
  PointElement,
  ArcElement,
  Title, 
  Tooltip, 
  Legend,
  Filler
} from 'chart.js';

ChartJS.register(
  CategoryScale, 
  LinearScale, 
  BarElement, 
  LineElement,
  PointElement,
  ArcElement,
  Title, 
  Tooltip, 
  Legend,
  Filler
);

const MaintReports = () => {
  const { language } = useLanguage();
  const { theme } = useTheme();
  const [loading, setLoading] = useState(true);
  const [requests, setRequests] = useState([]);
  const [technicians, setTechnicians] = useState([]);
  const [assets, setAssets] = useState([]);
  const [activeTab, setActiveTab] = useState('technicians');

  // Filter state
  const [filters, setFilters] = useState({
    dateFrom: '',
    dateTo: '',
    department: '',
    asset: '',
    category: '',
    technician: '',
    priority: '',
    status: ''
  });

  const [stats, setStats] = useState({
    total: 0,
    pending: 0,
    approved: 0,
    rejected: 0,
    inProgress: 0,
    completed: 0,
    byPriority: {},
    byStatus: {},
    byType: {},
    byDepartment: {},
    avgCompletionTime: 0,
    totalCost: 0,
    partsCost: 0,
    laborCost: 0
  });

  const [technicianStats, setTechnicianStats] = useState([]);
  const [assetStats, setAssetStats] = useState([]);

  const isDark = theme === 'dark';
  const t = language === 'en' ? englishTranslations : amharicTranslations;

  useEffect(() => {
    fetchAllData();
  }, []);

  useEffect(() => {
    if (requests.length > 0) {
      calculateStats();
    }
  }, [requests, filters]);

  const fetchAllData = async () => {
    setLoading(true);
    try {
      const [requestsRes, techniciansRes, assetsRes] = await Promise.all([
        axios.get('/api/maintenance', { params: { limit: 1000 } }),
        axios.get('/api/users', { params: { role: 'maintenance', limit: 500 } }),
        axios.get('/api/assets')
      ]);

      setRequests(Array.isArray(requestsRes.data?.requests) ? requestsRes.data.requests : []);
      setTechnicians(
        Array.isArray(techniciansRes.data?.users)
          ? techniciansRes.data.users
          : Array.isArray(techniciansRes.data?.data)
            ? techniciansRes.data.data
            : []
      );
      setAssets(
        Array.isArray(assetsRes.data?.assets)
          ? assetsRes.data.assets
          : Array.isArray(assetsRes.data?.data)
            ? assetsRes.data.data
            : []
      );
    } catch (error) {
      toast.error(t.fetchError || 'Failed to load data');
    }
    setLoading(false);
  };

  const calculateStats = () => {
    // Apply filters
    let filtered = [...requests];

    if (filters.dateFrom) {
      filtered = filtered.filter(r => new Date(r.created_at) >= new Date(filters.dateFrom));
    }
    if (filters.dateTo) {
      filtered = filtered.filter(r => new Date(r.created_at) <= new Date(filters.dateTo));
    }
    if (filters.department) {
      filtered = filtered.filter(r => r.department === filters.department);
    }
    if (filters.asset) {
      filtered = filtered.filter(r => r.asset_id === filters.asset);
    }
    if (filters.category) {
      filtered = filtered.filter(r => r.category === filters.category);
    }
    if (filters.technician) {
      filtered = filtered.filter(r => r.technician_id === filters.technician);
    }
    if (filters.priority) {
      filtered = filtered.filter(r => r.priority === filters.priority);
    }
    if (filters.status) {
      filtered = filtered.filter(r => r.status === filters.status);
    }

    // Basic stats
    const byPriority = filtered.reduce((acc, m) => {
      acc[m.priority] = (acc[m.priority] || 0) + 1;
      return acc;
    }, {});

    const byStatus = filtered.reduce((acc, m) => {
      acc[m.status] = (acc[m.status] || 0) + 1;
      return acc;
    }, {});

    const byType = filtered.reduce((acc, m) => {
      acc[m.type] = (acc[m.type] || 0) + 1;
      return acc;
    }, {});

    const byDepartment = filtered.reduce((acc, m) => {
      acc[m.department || 'Unknown'] = (acc[m.department || 'Unknown'] || 0) + 1;
      return acc;
    }, {});

    // Completion time
    const completed = filtered.filter(m => m.status === 'Completed' && m.completion_date);
    let avgTime = 0;
    if (completed.length > 0) {
      const totalTime = completed.reduce((sum, m) => {
        const time = (new Date(m.completion_date) - new Date(m.created_at)) / (1000 * 60 * 60);
        return sum + time;
      }, 0);
      avgTime = totalTime / completed.length;
    }

    // Financial stats
    let totalCost = 0, partsCost = 0, laborCost = 0;
    filtered.forEach(m => {
      totalCost += m.actual_cost || 0;
      partsCost += m.parts_cost || 0;
      laborCost += m.labor_cost || 0;
    });

    setStats({
      total: filtered.length,
      pending: filtered.filter(m => m.status === 'Pending').length,
      approved: filtered.filter(m => m.status === 'Approved').length,
      rejected: filtered.filter(m => m.status === 'Rejected').length,
      inProgress: filtered.filter(m => m.status === 'In-Progress').length,
      completed: filtered.filter(m => m.status === 'Completed').length,
      byPriority,
      byStatus,
      byType,
      byDepartment,
      avgCompletionTime: avgTime,
      totalCost,
      partsCost,
      laborCost
    });

    // Technician performance
    calculateTechnicianStats(filtered);

    // Asset stats
    calculateAssetStats(filtered);
  };

  const calculateTechnicianStats = (filtered) => {
    const techMap = {};
    technicians.forEach(tech => {
      techMap[tech.id] = {
        name: tech.name,
        assigned: 0,
        completed: 0,
        pending: 0,
        totalTime: 0,
        completedCount: 0
      };
    });

    filtered.forEach(req => {
      if (req.technician_id && techMap[req.technician_id]) {
        techMap[req.technician_id].assigned++;
        if (req.status === 'Completed') {
          techMap[req.technician_id].completed++;
          const time = (new Date(req.completion_date) - new Date(req.created_at)) / (1000 * 60 * 60);
          techMap[req.technician_id].totalTime += time;
          techMap[req.technician_id].completedCount++;
        } else if (req.status === 'Pending' || req.status === 'In-Progress') {
          techMap[req.technician_id].pending++;
        }
      }
    });

    const techStats = Object.values(techMap).map(tech => ({
      ...tech,
      avgCompletionTime: tech.completedCount > 0 ? tech.totalTime / tech.completedCount : 0
    }));

    setTechnicianStats(techStats);
  };

  const calculateAssetStats = (filtered) => {
    const assetMap = {};
    assets.forEach(asset => {
      assetMap[asset.id] = {
        name: asset.name,
        maintenanceCount: 0,
        inProgress: 0,
        failureCount: 0,
        lastMaintenance: null
      };
    });

    filtered.forEach(req => {
      if (req.asset_id && assetMap[req.asset_id]) {
        assetMap[req.asset_id].maintenanceCount++;
        if (req.status === 'In-Progress' || req.status === 'Pending') {
          assetMap[req.asset_id].inProgress++;
        }
        if (req.is_repeated_failure) {
          assetMap[req.asset_id].failureCount++;
        }
        if (req.completion_date) {
          assetMap[req.asset_id].lastMaintenance = req.completion_date;
        }
      }
    });

    const assetStats = Object.values(assetMap)
      .filter(a => a.maintenanceCount > 0)
      .sort((a, b) => b.maintenanceCount - a.maintenanceCount);

    setAssetStats(assetStats);
  };

  const handleFilterChange = (key, value) => {
    setFilters(prev => ({ ...prev, [key]: value }));
  };

  const clearFilters = () => {
    setFilters({
      dateFrom: '',
      dateTo: '',
      department: '',
      asset: '',
      category: '',
      technician: '',
      priority: '',
      status: ''
    });
  };

  // Chart configurations
  const chartColors = {
    primary: isDark ? '#63b3ed' : '#3182ce',
    success: isDark ? '#68d391' : '#38a169',
    warning: isDark ? '#f6ad55' : '#dd6b20',
    danger: isDark ? '#fc8181' : '#e53e3e',
    info: isDark ? '#81e6d9' : '#319795',
    purple: isDark ? '#b794f4' : '#805ad5',
    pink: isDark ? '#f687b3' : '#d53f8c',
    darkBg: isDark ? '#1e2d45' : '#ffffff',
    lightBg: isDark ? '#141e2d' : '#f7fafc'
  };

  const getChartOptions = (title) => ({
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'top',
        labels: {
          color: isDark ? '#c8dcf5' : '#1a365d',
          boxWidth: 12,
          padding: 15
        }
      },
      title: {
        display: true,
        text: title,
        color: isDark ? '#c8dcf5' : '#1a365d',
        font: { size: 14, weight: 'bold' }
      }
    },
    scales: {
      y: {
        ticks: { color: isDark ? '#8896b0' : '#4a5568' },
        grid: { color: isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.05)' }
      },
      x: {
        ticks: { color: isDark ? '#8896b0' : '#4a5568' },
        grid: { color: isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.05)' }
      }
    }
  });

  // Export functions
  const exportToPDF = () => {
    const doc = new jsPDF('landscape', 'mm', 'a4');

    doc.setFontSize(18);
    doc.setTextColor(isDark ? '#c8dcf5' : '#1a365d');
    doc.text('Maintenance Report', 14, 20);
    doc.setFontSize(10);
    doc.text(`Generated: ${new Date().toLocaleString()}`, 14, 28);

    const tableData = requests.slice(0, 100).map(m => [
      m.request_number || '',
      m.title || '',
      m.asset_name || '',
      m.status || '',
      m.priority || '',
      m.type || '',
      new Date(m.created_at).toLocaleDateString() || '',
      m.actual_cost ? `$${m.actual_cost}` : '$0'
    ]);

    doc.autoTable({
      head: [['Request #', 'Title', 'Asset', 'Status', 'Priority', 'Type', 'Created', 'Cost']],
      body: tableData,
      startY: 35,
      theme: isDark ? 'dark' : 'grid',
      styles: {
        fontSize: 8,
        cellPadding: 2
      },
      headStyles: {
        fillColor: isDark ? [30, 45, 69] : [55, 65, 81]
      }
    });

    doc.save('maintenance_report.pdf');
    toast.success(t.exportSuccess || 'PDF exported successfully');
  };

  const exportToExcel = () => {
    const data = requests.map(m => ({
      'Request #': m.request_number,
      'Title': m.title,
      'Asset': m.asset_name || '',
      'Status': m.status,
      'Priority': m.priority,
      'Type': m.type,
      'Department': m.department || '',
      'Technician': m.technician_name || '',
      'Reported By': m.reported_by_name || '',
      'Created': new Date(m.created_at).toLocaleDateString(),
      'Completed': m.completion_date ? new Date(m.completion_date).toLocaleDateString() : '-',
      'Cost': m.actual_cost || 0,
      'Parts Cost': m.parts_cost || 0,
      'Labor Cost': m.labor_cost || 0,
      'Description': m.description || ''
    }));
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Maintenance');
    XLSX.writeFile(wb, 'maintenance_report.xlsx');
    toast.success('Excel exported successfully');
  };

  const handlePrint = () => {
    window.print();
  };

  // Render different tab content
  const renderOverview = () => (
    <>
      {/* Summary Cards */}
      <div style={styles.statsGrid}>
        <div style={styles.statCard}>
          <div style={styles.statNumber}>{stats.total}</div>
          <div style={styles.statLabel}>{t.totalRequests}</div>
