import React, { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useLanguage } from '../../contexts/UiContext';
import { toast } from 'react-toastify';
import axios from 'axios';
import jsPDF from 'jspdf';
import 'jspdf-autotable';

const MaintRequests = () => {
  const { user } = useAuth();
  const { language, theme } = useLanguage();

  // State
  const [requests, setRequests] = useState([]);
  const [assets, setAssets] = useState([]);
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showCreate, setShowCreate] = useState(false);
  const [showDetail, setShowDetail] = useState(false);
  const [showEdit, setShowEdit] = useState(false);
  const [selectedRequest, setSelectedRequest] = useState(null);
  const [filterStatus, setFilterStatus] = useState('');
  const [filterPriority, setFilterPriority] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [filterAsset, setFilterAsset] = useState('');

  // Form Data
  const [formData, setFormData] = useState({
    asset_id: '',
    type: 'Corrective',
    priority: 'Medium',
    title: '',
    description: '',
    scheduled_date: '',
    estimated_cost: '',
    assigned_to: '',
    status: 'Pending',
    remarks: ''
  });

  const isDark = theme === 'dark';
  const t = language === 'en' ? englishTranslations : amharicTranslations;

  // Status options
  const statuses = ['Pending', 'Approved', 'Assigned', 'In Progress', 'Waiting for Parts', 'Completed', 'Rejected', 'Cancelled'];

  // Priority options
  const priorities = ['Low', 'Medium', 'High', 'Critical'];

  // Type options
  const types = ['Corrective', 'Preventive', 'Emergency', 'Scheduled'];

  useEffect(() => {
    fetchData();
  }, [filterStatus, filterPriority, filterAsset]);

  const fetchData = async () => {
    setLoading(true);
    try {
      const params = {};
      if (filterStatus) params.status = filterStatus;
      if (filterPriority) params.priority = filterPriority;
      if (filterAsset) params.asset_id = filterAsset;
      if (searchQuery) params.search = searchQuery;

      const [requestsRes, assetsRes, usersRes] = await Promise.all([
        axios.get('/api/maintenance', { params }),
        axios.get('/api/assets', { params: { limit: 1000 } }),
        axios.get('/api/users', { params: { limit: 500 } })
      ]);

      setRequests(requestsRes.data.requests || []);
      setAssets(assetsRes.data.assets || []);
      setUsers(usersRes.data.users || []);
    } catch (error) {
      console.error('Fetch error:', error);
      toast.error('Failed to load data');
    }
    setLoading(false);
  };

  // Handle create request
  const handleCreate = async (e) => {
    e.preventDefault();
    try {
      const payload = {
        ...formData,
        reported_by: user?.id,
        created_at: new Date().toISOString()
      };
      await axios.post('/api/maintenance', payload);
      toast.success('Maintenance request created');
      setShowCreate(false);
      resetForm();
      fetchData();
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to create request');
    }
  };

  // Handle update request
  const handleUpdate = async (e) => {
    e.preventDefault();
    try {
      await axios.put(`/api/maintenance/${selectedRequest.id}`, formData);
      toast.success('Request updated successfully');
      setShowEdit(false);
      fetchData();
    } catch (error) {
      toast.error('Failed to update request');
    }
  };

  // Handle status change
  const handleStatusChange = async (id, status) => {
    try {
      await axios.patch(`/api/maintenance/${id}/status`, { status });
      toast.success(`Status updated to ${status}`);
      fetchData();
    } catch (error) {
      toast.error('Failed to update status');
    }
  };

  // Handle delete request
  const handleDelete = async (id) => {
    if (!window.confirm('Are you sure you want to delete this request?')) return;
    try {
      await axios.delete(`/api/maintenance/${id}`);
      toast.success('Request deleted');
      fetchData();
    } catch (error) {
      toast.error('Failed to delete request');
    }
  };

  // Handle approve request
  const handleApprove = async (id) => {
    try {
      await axios.patch(`/api/maintenance/${id}/approve`);
      toast.success('Request approved');
      fetchData();
    } catch (error) {
      toast.error('Failed to approve request');
    }
  };

  // Handle reject request
  const handleReject = async (id) => {
    const reason = prompt('Please provide a reason for rejection:');
    if (reason === null) return;
    try {
      await axios.patch(`/api/maintenance/${id}/reject`, { reason });
      toast.success('Request rejected');
      fetchData();
    } catch (error) {
      toast.error('Failed to reject request');
    }
  };

  // Reset form
  const resetForm = () => {
    setFormData({
      asset_id: '',
      type: 'Corrective',
      priority: 'Medium',
      title: '',
      description: '',
      scheduled_date: '',
      estimated_cost: '',
      assigned_to: '',
      status: 'Pending',
      remarks: ''
    });
  };

  // View request details
  const viewDetails = (request) => {
    setSelectedRequest(request);
    setShowDetail(true);
  };

  // Edit request
  const editRequest = (request) => {
    setSelectedRequest(request);
    setFormData({
      asset_id: request.asset_id,
      type: request.type || 'Corrective',
      priority: request.priority || 'Medium',
      title: request.title,
      description: request.description,
      scheduled_date: request.scheduled_date?.split('T')[0] || '',
      estimated_cost: request.estimated_cost || '',
      assigned_to: request.assigned_to || '',
      status: request.status,
      remarks: request.remarks || ''
    });
    setShowEdit(true);
  };

  // Export to PDF
  const exportToPDF = () => {
    const doc = new jsPDF();
    doc.text('Maintenance Requests Report', 14, 15);
    doc.text(`Generated: ${new Date().toLocaleString()}`, 14, 25);
    doc.text(`Total Requests: ${requests.length}`, 14, 35);

    const tableData = requests.slice(0, 100).map(r => [
      r.request_number || r.id,
      r.title,
      r.asset_name || 'N/A',
      r.priority || 'N/A',
      r.status,
      r.assigned_to_name || 'Unassigned'
    ]);

    doc.autoTable({
      head: [['#', 'Title', 'Asset', 'Priority', 'Status', 'Technician']],
      body: tableData,
      startY: 45
    });

    doc.save(`Maintenance_Requests_${new Date().toISOString().split('T')[0]}.pdf`);
    toast.success('Export successful');
  };

  // Get status color
  const getStatusColor = (status) => {
    const colors = {
      'Pending': '#ed8936',
      'Approved': '#4299e1',
      'Assigned': '#4299e1',
      'In Progress': '#ed8936',
      'Waiting for Parts': '#ed8936',
      'Completed': '#48bb78',
      'Rejected': '#fc8181',
      'Cancelled': '#fc8181'
    };
    return colors[status] || '#a0aec0';
  };

  // Get priority color
  const getPriorityColor = (priority) => {
    const colors = {
      'Low': '#48bb78',
      'Medium': '#4299e1',
      'High': '#ed8936',
      'Critical': '#fc8181'
