      width: '100%', 
      padding: '10px 14px', 
      borderRadius: '8px', 
      border: `1px solid ${isDark ? '#32465f' : '#d0d8e8'}`, 
      background: isDark ? '#0d1b2a' : '#f7fafc', 
      color: isDark ? '#c8dcf5' : '#1a365d', 
      fontSize: '0.95rem', 
      marginBottom: '12px', 
      cursor: 'pointer' 
    },
    modalTextarea: { 
      width: '100%', 
      padding: '10px 14px', 
      borderRadius: '8px', 
      border: `1px solid ${isDark ? '#32465f' : '#d0d8e8'}`, 
      background: isDark ? '#0d1b2a' : '#f7fafc', 
      color: isDark ? '#c8dcf5' : '#1a365d', 
      fontSize: '0.95rem', 
      minHeight: '80px', 
      resize: 'vertical', 
      marginBottom: '12px' 
    },
    modalLabel: {
      display: 'block',
      marginBottom: '4px',
      color: isDark ? '#c8dcf5' : '#2d3748',
      fontWeight: 600,
      fontSize: '0.85rem'
    },
    grid: {
      display: 'grid',
      gridTemplateColumns: '1fr 1fr',
      gap: '16px'
    },
    fullWidth: {
      gridColumn: '1 / -1'
    },
    emptyState: { 
      textAlign: 'center', 
      padding: '60px 20px', 
      color: isDark ? '#8896b0' : '#4a5568' 
    },
    statsRow: {
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fit, minmax(100px, 1fr))',
      gap: '12px',
      marginBottom: '20px'
    },
    statCard: {
      background: isDark ? '#1e2d45' : '#ffffff',
      padding: '12px 16px',
      borderRadius: '8px',
      border: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      textAlign: 'center'
    },
    statNumber: {
      fontSize: '1.25rem',
      fontWeight: 700,
      color: isDark ? '#c8dcf5' : '#1a365d'
    },
    statLabel: {
      fontSize: '0.75rem',
      color: isDark ? '#8896b0' : '#4a5568'
    }
  };

  // Calculate stats
  const stats = {
    total: requests.length,
    pending: requests.filter(r => r.status === 'Pending').length,
    approved: requests.filter(r => r.status === 'Approved').length,
    inProgress: requests.filter(r => r.status === 'In Progress' || r.status === 'Assigned').length,
    completed: requests.filter(r => r.status === 'Completed').length
  };

  if (loading) {
    return <div style={styles.emptyState}>⏳ {t.loading}</div>;
  }

  return (
    <div style={styles.container}>
      {/* Header */}
      <div style={styles.header}>
        <div>
          <h1 style={styles.title}>🔧 {t.requests}</h1>
          <p style={styles.subtitle}>{t.requestsDesc}</p>
        </div>
        <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
          <button style={styles.createButton} onClick={() => setShowCreate(true)}>
            ➕ {t.createRequest}
          </button>
          <button style={{...styles.createButton, background: 'linear-gradient(135deg, #48bb78, #38a169)'}} onClick={exportToPDF}>
            📊 {t.exportPDF}
          </button>
        </div>
      </div>

      {/* Stats */}
      <div style={styles.statsRow}>
        <div style={styles.statCard}>
          <div style={styles.statNumber}>{stats.total}</div>
          <div style={styles.statLabel}>{t.total}</div>
        </div>
        <div style={styles.statCard}>
          <div style={{...styles.statNumber, color: '#ed8936'}}>{stats.pending}</div>
          <div style={styles.statLabel}>{t.pending}</div>
        </div>
        <div style={styles.statCard}>
          <div style={{...styles.statNumber, color: '#4299e1'}}>{stats.approved}</div>
          <div style={styles.statLabel}>{t.approved}</div>
        </div>
        <div style={styles.statCard}>
          <div style={{...styles.statNumber, color: '#ed8936'}}>{stats.inProgress}</div>
          <div style={styles.statLabel}>{t.inProgress}</div>
        </div>
        <div style={styles.statCard}>
          <div style={{...styles.statNumber, color: '#48bb78'}}>{stats.completed}</div>
          <div style={styles.statLabel}>{t.completed}</div>
        </div>
      </div>

      {/* Controls */}
      <div style={styles.controls}>
        <input 
          type="text" 
          style={styles.searchInput} 
          placeholder={t.searchPlaceholder}
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          onKeyPress={(e) => e.key === 'Enter' && fetchData()}
        />

        <select style={styles.select} value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)}>
          <option value="">{t.allStatus}</option>
          {statuses.map(status => (
            <option key={status} value={status}>{status}</option>
          ))}
        </select>

        <select style={styles.select} value={filterPriority} onChange={(e) => setFilterPriority(e.target.value)}>
          <option value="">{t.allPriority}</option>
          {priorities.map(priority => (
            <option key={priority} value={priority}>{priority}</option>
          ))}
        </select>

        <select style={styles.select} value={filterAsset} onChange={(e) => setFilterAsset(e.target.value)}>
          <option value="">{t.allAssets}</option>
          {assets.map(asset => (
            <option key={asset.id} value={asset.id}>{asset.name}</option>
          ))}
        </select>

        <button style={styles.createButton} onClick={fetchData}>
          🔄 {t.refresh}
        </button>
      </div>

      {/* Request Cards */}
      {requests.length === 0 ? (
        <div style={styles.emptyState}>
          <div style={{ fontSize: '3rem', marginBottom: '16px' }}>🔧</div>
          <h3>{t.noRequests}</h3>
          <p style={{ color: isDark ? '#8896b0' : '#4a5568' }}>{t.noRequestsDesc}</p>
        </div>
      ) : (
        requests.map(req => (
          <div 
            key={req.id} 
            style={styles.card}
            onMouseEnter={(e) => e.currentTarget.style.borderColor = isDark ? '#63b3ed' : '#2b6cb0'}
            onMouseLeave={(e) => e.currentTarget.style.borderColor = isDark ? '#32465f' : '#e8edf5'}
            onClick={() => viewDetails(req)}
          >
            <div style={styles.cardHeader}>
              <div style={{ flex: 1 }}>
                <div style={styles.cardTitle}>
                  #{req.request_number || req.id} - {req.title}
                </div>
                <div style={styles.metaInfo}>
                  <span style={styles.metaItem}>📦 {req.asset_name || 'N/A'}</span>
                  <span style={styles.metaItem}>🏷️ {req.asset_tag || ''}</span>
                  <span style={{...styles.metaItem, ...getStatusBadge(req.status)}}>
                    {req.status}
                  </span>
                  <span style={{...styles.metaItem, ...getPriorityBadge(req.priority)}}>
                    {req.priority}
                  </span>
                  <span style={styles.metaItem}>📋 {req.type}</span>
                </div>
                <div style={styles.description}>
                  {req.description?.substring(0, 120)}{req.description?.length > 120 ? '...' : ''}
                </div>
                <div style={styles.metaInfo}>
                  <span style={styles.metaItem}>👤 {req.reported_by_name || 'Unknown'}</span>
                  <span style={styles.metaItem}>📅 {new Date(req.created_at).toLocaleDateString()}</span>
                  {req.scheduled_date && (
                    <span style={styles.metaItem}>📆 {new Date(req.scheduled_date).toLocaleDateString()}</span>
                  )}
                  {req.assigned_to_name && (
                    <span style={styles.metaItem}>🔧 {req.assigned_to_name}</span>
                  )}
                </div>
              </div>
            </div>

            {/* Action Buttons */}
            <div style={styles.actionButtons} onClick={(e) => e.stopPropagation()}>
              <button style={styles.actionBtn('#4299e1')} onClick={() => viewDetails(req)}>
                👁️ {t.view}
              </button>

              {req.status === 'Pending' && (
                <>
                  <button style={styles.actionBtn('#48bb78')} onClick={() => handleApprove(req.id)}>
                    ✅ {t.approve}
                  </button>
                  <button style={styles.actionBtn('#fc8181')} onClick={() => handleReject(req.id)}>
                    ❌ {t.reject}
                  </button>
                </>
              )}

              {req.status !== 'Completed' && req.status !== 'Rejected' && req.status !== 'Cancelled' && (
                <button style={styles.actionBtn('#ed8936')} onClick={() => editRequest(req)}>
                  ✏️ {t.edit}
                </button>
              )}

              <select 
                style={{...styles.select, padding: '4px 8px', fontSize: '11px', minWidth: '120px'}}
                onChange={(e) => handleStatusChange(req.id, e.target.value)}
                value={req.status}
                onClick={(e) => e.stopPropagation()}
              >
                {statuses.map(status => (
                  <option key={status} value={status}>{status}</option>
                ))}
              </select>

              <button style={styles.actionBtn('#fc8181')} onClick={() => handleDelete(req.id)}>
                🗑️ {t.delete}
              </button>
            </div>
          </div>
        ))
      )}

      {/* Create Modal */}
      {showCreate && (
        <div style={styles.modal} onClick={() => setShowCreate(false)}>
          <div style={styles.modalContent} onClick={e => e.stopPropagation()}>
            <div style={styles.modalHeader}>
              <h3 style={styles.modalTitle}>➕ {t.createRequest}</h3>
              <button style={styles.modalClose} onClick={() => setShowCreate(false)}>✕</button>
            </div>

            <form onSubmit={handleCreate}>
              <div style={styles.grid}>
                <div style={styles.fullWidth}>
                  <label style={styles.modalLabel}>{t.selectAsset} *</label>
                  <select style={styles.modalSelect} value={formData.asset_id} onChange={(e) => setFormData({ ...formData, asset_id: e.target.value })} required>
                    <option value="">{t.selectAsset}</option>
                    {assets.map(a => (
                      <option key={a.id} value={a.id}>{a.asset_tag} - {a.name}</option>
                    ))}
                  </select>
                </div>

                <div style={styles.fullWidth}>
                  <label style={styles.modalLabel}>{t.title} *</label>
                  <input type="text" style={styles.modalInput} placeholder={t.titlePlaceholder} value={formData.title} onChange={(e) => setFormData({ ...formData, title: e.target.value })} required />
                </div>

                <div style={styles.fullWidth}>
                  <label style={styles.modalLabel}>{t.description} *</label>
                  <textarea style={styles.modalTextarea} placeholder={t.descPlaceholder} value={formData.description} onChange={(e) => setFormData({ ...formData, description: e.target.value })} required />
                </div>

                <div>
                  <label style={styles.modalLabel}>{t.type}</label>
                  <select style={styles.modalSelect} value={formData.type} onChange={(e) => setFormData({ ...formData, type: e.target.value })}>
                    {types.map(type => (
                      <option key={type} value={type}>{type}</option>
                    ))}
                  </select>
                </div>

                <div>
                  <label style={styles.modalLabel}>{t.priority}</label>
                  <select style={styles.modalSelect} value={formData.priority} onChange={(e) => setFormData({ ...formData, priority: e.target.value })}>
                    {priorities.map(p => (
                      <option key={p} value={p}>{p}</option>
                    ))}
                  </select>
                </div>

                <div>
                  <label style={styles.modalLabel}>{t.scheduledDate}</label>
                  <input type="date" style={styles.modalInput} value={formData.scheduled_date} onChange={(e) => setFormData({ ...formData, scheduled_date: e.target.value })} />
                </div>

                <div>
                  <label style={styles.modalLabel}>{t.estimatedCost}</label>
                  <input type="number" style={styles.modalInput} placeholder="0.00" value={formData.estimated_cost} onChange={(e) => setFormData({ ...formData, estimated_cost: e.target.value })} step="0.01" min="0" />
                </div>

                <div style={styles.fullWidth}>
                  <label style={styles.modalLabel}>{t.remarks}</label>
                  <textarea style={styles.modalTextarea} placeholder={t.remarksPlaceholder} value={formData.remarks} onChange={(e) => setFormData({ ...formData, remarks: e.target.value })} />
                </div>
              </div>

              <div style={{ display: 'flex', gap: '12px', marginTop: '12px' }}>
                <button type="submit" style={styles.createButton}>{t.submit}</button>
                <button type="button" style={{ ...styles.createButton, background: '#fc8181' }} onClick={() => setShowCreate(false)}>{t.cancel}</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Detail Modal */}
      {showDetail && selectedRequest && (
        <div style={styles.modal} onClick={() => setShowDetail(false)}>
          <div style={styles.modalContent} onClick={e => e.stopPropagation()}>
            <div style={styles.modalHeader}>
              <h3 style={styles.modalTitle}>📋 {t.requestDetails}</h3>
              <button style={styles.modalClose} onClick={() => setShowDetail(false)}>✕</button>
            </div>

            <div style={styles.grid}>
              <div>
                <label style={styles.modalLabel}>{t.requestNumber}</label>
                <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc'}}>
                  #{selectedRequest.request_number || selectedRequest.id}
                </div>
              </div>
              <div>
                <label style={styles.modalLabel}>{t.status}</label>
                <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc'}}>
                  <span style={getStatusBadge(selectedRequest.status)}>{selectedRequest.status}</span>
                </div>
              </div>
              <div style={styles.fullWidth}>
                <label style={styles.modalLabel}>{t.title}</label>
                <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc', fontWeight: 600}}>
                  {selectedRequest.title}
                </div>
              </div>
              <div style={styles.fullWidth}>
                <label style={styles.modalLabel}>{t.description}</label>
                <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc', minHeight: '60px'}}>
                  {selectedRequest.description}
                </div>
              </div>
              <div>
                <label style={styles.modalLabel}>{t.asset}</label>
                <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc'}}>
                  {selectedRequest.asset_name} ({selectedRequest.asset_tag})
                </div>
              </div>
              <div>
                <label style={styles.modalLabel}>{t.priority}</label>
                <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc'}}>
                  <span style={getPriorityBadge(selectedRequest.priority)}>{selectedRequest.priority}</span>
                </div>
              </div>
              <div>
                <label style={styles.modalLabel}>{t.type}</label>
                <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc'}}>
                  {selectedRequest.type}
                </div>
              </div>
              <div>
                <label style={styles.modalLabel}>{t.reportedBy}</label>
                <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc'}}>
                  {selectedRequest.reported_by_name || 'Unknown'}
                </div>
              </div>
              <div>
                <label style={styles.modalLabel}>{t.created}</label>
                <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc'}}>
                  {new Date(selectedRequest.created_at).toLocaleString()}
                </div>
              </div>
              <div>
                <label style={styles.modalLabel}>{t.scheduledDate}</label>
                <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc'}}>
                  {selectedRequest.scheduled_date ? new Date(selectedRequest.scheduled_date).toLocaleDateString() : 'N/A'}
                </div>
              </div>
              {selectedRequest.assigned_to_name && (
                <div>
                  <label style={styles.modalLabel}>{t.technician}</label>
                  <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc'}}>
                    {selectedRequest.assigned_to_name}
                  </div>
                </div>
              )}
              {selectedRequest.estimated_cost && (
                <div>
                  <label style={styles.modalLabel}>{t.estimatedCost}</label>
                  <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc'}}>
                    ${selectedRequest.estimated_cost}
                  </div>
                </div>
              )}
              {selectedRequest.remarks && (
                <div style={styles.fullWidth}>
                  <label style={styles.modalLabel}>{t.remarks}</label>
                  <div style={{...styles.modalInput, background: isDark ? '#0d1b2a' : '#f7fafc', minHeight: '40px'}}>
                    {selectedRequest.remarks}
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Edit Modal */}
      {showEdit && selectedRequest && (
        <div style={styles.modal} onClick={() => setShowEdit(false)}>
          <div style={styles.modalContent} onClick={e => e.stopPropagation()}>
            <div style={styles.modalHeader}>
              <h3 style={styles.modalTitle}>✏️ {t.editRequest}</h3>
              <button style={styles.modalClose} onClick={() => setShowEdit(false)}>✕</button>
            </div>

            <form onSubmit={handleUpdate}>
              <div style={styles.grid}>
                <div style={styles.fullWidth}>
                  <label style={styles.modalLabel}>{t.title} *</label>
                  <input type="text" style={styles.modalInput} value={formData.title} onChange={(e) => setFormData({ ...formData, title: e.target.value })} required />
                </div>

                <div style={styles.fullWidth}>
                  <label style={styles.modalLabel}>{t.description} *</label>
                  <textarea style={styles.modalTextarea} value={formData.description} onChange={(e) => setFormData({ ...formData, description: e.target.value })} required />
                </div>

                <div>
                  <label style={styles.modalLabel}>{t.type}</label>
                  <select style={styles.modalSelect} value={formData.type} onChange={(e) => setFormData({ ...formData, type: e.target.value })}>
                    {types.map(type => (
                      <option key={type} value={type}>{type}</option>
                    ))}
                  </select>
                </div>

                <div>
                  <label style={styles.modalLabel}>{t.priority}</label>
                  <select style={styles.modalSelect} value={formData.priority} onChange={(e) => setFormData({ ...formData, priority: e.target.value })}>
                    {priorities.map(p => (
                      <option key={p} value={p}>{p}</option>
                    ))}
                  </select>
                </div>

                <div>
                  <label style={styles.modalLabel}>{t.technician}</label>
                  <select style={styles.modalSelect} value={formData.assigned_to} onChange={(e) => setFormData({ ...formData, assigned_to: e.target.value })}>
                    <option value="">{t.selectTechnician}</option>
                    {users.map(u => (
                      <option key={u.id} value={u.id}>{u.full_name || u.username}</option>
                    ))}
                  </select>
                </div>

                <div>
                  <label style={styles.modalLabel}>{t.scheduledDate}</label>
                  <input type="date" style={styles.modalInput} value={formData.scheduled_date} onChange={(e) => setFormData({ ...formData, scheduled_date: e.target.value })} />
                </div>

                <div>
                  <label style={styles.modalLabel}>{t.estimatedCost}</label>
                  <input type="number" style={styles.modalInput} value={formData.estimated_cost} onChange={(e) => setFormData({ ...formData, estimated_cost: e.target.value })} step="0.01" min="0" />
                </div>

                <div style={styles.fullWidth}>
                  <label style={styles.modalLabel}>{t.remarks}</label>
                  <textarea style={styles.modalTextarea} value={formData.remarks} onChange={(e) => setFormData({ ...formData, remarks: e.target.value })} placeholder={t.remarksPlaceholder} />
                </div>
              </div>

              <div style={{ display: 'flex', gap: '12px', marginTop: '12px' }}>
                <button type="submit" style={styles.createButton}>{t.update}</button>
                <button type="button" style={{ ...styles.createButton, background: '#fc8181' }} onClick={() => setShowEdit(false)}>{t.cancel}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

