import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { useLanguage, useTheme } from '../../contexts/UiContext';
import { apiBase } from '../../utils/api';
import axios from 'axios';

const Login = () => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [rfidData, setRfidData] = useState(null);
  const [rfidLoading, setRfidLoading] = useState(false);
  const [rfidError, setRfidError] = useState(null);
  const [backendStatus, setBackendStatus] = useState('checking');
  const [activeRole, setActiveRole] = useState(null);

  const { login } = useAuth();
  const { language } = useLanguage();
  const { theme } = useTheme();
  const navigate = useNavigate();

  const isDark = theme === 'dark';
  const t = language === 'en' ? englishTranslations : amharicTranslations;

  const roles = [
    { id: 'admin', label: 'Admin', emoji: '👑', color: '#f59e0b' },
    { id: 'store_manager', label: 'Store Mgr', emoji: '📦', color: '#8b5cf6' },
    { id: 'ict_officer', label: 'ICT Officer', emoji: '💻', color: '#3b82f6' },
    { id: 'department_head', label: 'Dept Head', emoji: '📋', color: '#10b981' },
    { id: 'finance', label: 'Finance', emoji: '💰', color: '#06b6d4' },
    { id: 'maintenance', label: 'Maintenance', emoji: '🔧', color: '#f97316' }
  ];

  // Quick fill demo credentials
  const handleQuickFillRole = (roleId) => {
    setActiveRole(roleId);
    setUsername(roleId);
    setPassword('bekelei123');
  };

  // Check backend health on mount
  useEffect(() => {
    const checkBackend = async () => {
      try {
        const backendUrl = apiBase().replace(/\/api\/?$/, '');
        await axios.get(`${backendUrl}/api/health`, { timeout: 3000 });
        setBackendStatus('online');
      } catch (err) {
        console.error('Backend health check failed:', err);
        setBackendStatus('offline');
      }
    };
    checkBackend();
  }, []);

  const fetchRfidData = async () => {
    try {
      setRfidLoading(true);
      setRfidError(null);
      const token = localStorage.getItem('token');

      const response = await axios.get(`${apiBase()}/rfid`, {
        headers: { 'Authorization': `Bearer ${token}` },
        timeout: 8000
      });

      if (response.data.success) {
        const logs = Array.isArray(response.data.data) ? response.data.data : [];
        setRfidData(logs[0] || { status: 'Connected', tag_id: 'RFID-9842-AX' });
      } else {
        throw new Error(response.data.message || 'Failed to load RFID');
      }
    } catch (err) {
      setRfidError('RFID Reader is idle or not connected.');
    } finally {
      setRfidLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(null);

    if (backendStatus === 'offline') {
      setError('🔌 Backend server offline. Please verify API service.');
      return;
    }

    if (!username.trim() || !password.trim()) {
      setError('Please provide both username and password.');
      return;
    }

    setLoading(true);

    try {
      const result = await login(username.trim(), password);

      if (!result?.success) {
        setError(result?.error || 'Authentication failed. Please verify credentials.');
        return;
      }

      const role = result.user?.role;
      const roleRoutes = {
        'admin': '/admin',
        'ict_officer': '/ict',
        'department_head': '/department',
        'finance': '/finance',
        'store_manager': '/store',
        'maintenance': '/maintenance'
      };
      navigate(roleRoutes[role] || '/dashboard');
    } catch (err) {
      setError('❌ An unexpected network error occurred.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-root" style={{
      minHeight: '100vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      background: isDark 
        ? 'radial-gradient(circle at 10% 20%, #0f172a 0%, #020617 90%)'
        : 'radial-gradient(circle at 10% 20%, #e0e7ff 0%, #f8fafc 90%)',
      padding: '24px',
      position: 'relative',
      overflow: 'hidden',
      fontFamily: "'Inter', system-ui, -apple-system, sans-serif"
    }}>

      {/* Background Glowing Ambient Orbs */}
      <div style={{
        position: 'absolute',
        width: '450px',
        height: '450px',
        borderRadius: '50%',
        background: isDark ? 'rgba(59, 130, 246, 0.15)' : 'rgba(99, 102, 241, 0.2)',
        filter: 'blur(90px)',
        top: '-5%',
        left: '-5%',
        pointerEvents: 'none'
      }} />
      <div style={{
        position: 'absolute',
        width: '400px',
        height: '400px',
        borderRadius: '50%',
        background: isDark ? 'rgba(168, 85, 247, 0.15)' : 'rgba(236, 72, 153, 0.15)',
        filter: 'blur(100px)',
        bottom: '-5%',
        right: '-5%',
        pointerEvents: 'none'
      }} />

      {/* Main Login Card */}
      <div style={{
        width: '100%',
        maxWidth: '460px',
        background: isDark ? 'rgba(15, 23, 42, 0.85)' : 'rgba(255, 255, 255, 0.9)',
        backdropFilter: 'blur(16px)',
        borderRadius: '24px',
        border: isDark ? '1px solid rgba(255, 255, 255, 0.08)' : '1px solid rgba(255, 255, 255, 0.8)',
        boxShadow: isDark ? '0 25px 50px -12px rgba(0, 0, 0, 0.7)' : '0 20px 40px -15px rgba(0, 0, 0, 0.1)',
        padding: '36px 32px',
        zIndex: 2
      }}>

        {/* Brand & Title */}
        <div style={{ textAlign: 'center', marginBottom: '24px' }}>
          <h1 style={{
            fontSize: '22px',
            fontWeight: 800,
            color: isDark ? '#f8fafc' : '#0f172a',
            margin: '0 0 4px 0',
            letterSpacing: '-0.5px'
          }}>
            {t.title}
          </h1>
          <p style={{ fontSize: '13px', color: isDark ? '#94a3b8' : '#64748b', margin: 0 }}>
            {t.subtitle}
          </p>

          {/* System Workflow Badges */}
          <div style={{
            display: 'flex',
            justifyContent: 'center',
            gap: '8px',
            marginTop: '12px'
          }}>
            {['Inventory', 'Assets', 'Requests'].map((module, idx) => (
              <span key={idx} style={{
                fontSize: '11px',
                fontWeight: 600,
                padding: '2px 8px',
                borderRadius: '12px',
                background: isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.04)',
                color: isDark ? '#94a3b8' : '#475569'
              }}>
                • {module}
              </span>
            ))}
          </div>
        </div>

        {/* Backend & RFID Status Card */}
        <div style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          background: isDark ? 'rgba(30, 41, 59, 0.5)' : '#f1f5f9',
          padding: '8px 14px',
          borderRadius: '12px',
          marginBottom: '18px',
          fontSize: '12px'
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
            <span style={{
              width: '8px',
              height: '8px',
              borderRadius: '50%',
              background: backendStatus === 'online' ? '#10b981' : '#ef4444',
              boxShadow: backendStatus === 'online' ? '0 0 8px #10b981' : 'none'
            }}></span>
            <span style={{ color: isDark ? '#cbd5e1' : '#475569', fontWeight: 500 }}>
              System {backendStatus}
            </span>
          </div>

          <button
            onClick={fetchRfidData}
            style={{
              background: 'none',
              border: 'none',
              color: isDark ? '#60a5fa' : '#2563eb',
              cursor: 'pointer',
              fontWeight: 600,
              fontSize: '12px',
              display: 'flex',
              alignItems: 'center',
              gap: '4px'
            }}
          >
            📡 {rfidLoading ? 'Scanning Tag...' : 'Scan RFID Card'}
          </button>
        </div>

        {/* Quick Role Autofill Matrix */}
        <div style={{
          background: isDark ? 'rgba(30, 41, 59, 0.4)' : '#f8fafc',
          border: isDark ? '1px solid rgba(255, 255, 255, 0.05)' : '1px solid #e2e8f0',
          borderRadius: '14px',
          padding: '12px',
          marginBottom: '20px'
        }}>
          <div style={{
            fontSize: '11px',
            fontWeight: 700,
            textTransform: 'uppercase',
            letterSpacing: '0.5px',
            color: isDark ? '#94a3b8' : '#64748b',
            marginBottom: '8px',
            textAlign: 'center'
          }}>
            ⚡ {t.demoCredentials} (Click to Fill)
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '6px' }}>
            {roles.map((r) => (
              <button
                key={r.id}
                type="button"
                onClick={() => handleQuickFillRole(r.id)}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '4px',
                  padding: '6px 8px',
                  borderRadius: '8px',
                  fontSize: '11px',
                  fontWeight: 600,
                  cursor: 'pointer',
                  border: activeRole === r.id ? `1px solid ${r.color}` : '1px solid transparent',
                  background: activeRole === r.id 
                    ? (isDark ? 'rgba(59, 130, 246, 0.2)' : '#e0e7ff') 
                    : (isDark ? 'rgba(255, 255, 255, 0.04)' : '#ffffff'),
                  color: isDark ? '#f1f5f9' : '#1e293b',
                  transition: 'all 0.15s ease'
                }}
              >
                <span>{r.emoji}</span>
                <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                  {r.label}
                </span>
              </button>
            ))}
          </div>
        </div>

        {/* Error Alert Box */}
        {(error || rfidError) && (
          <div style={{
            background: isDark ? '#7f1d1d25' : '#fee2e2',
            borderLeft: '4px solid #ef4444',
            color: isDark ? '#fca5a5' : '#991b1b',
            padding: '10px 14px',
            borderRadius: '8px',
            fontSize: '13px',
            marginBottom: '18px',
            fontWeight: 500
          }}>
            {error || rfidError}
          </div>
        )}

        {/* Login Form */}
        <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>

          <div>
            <label style={{
              display: 'block',
              fontSize: '12px',
              fontWeight: 700,
              textTransform: 'uppercase',
              color: isDark ? '#cbd5e1' : '#475569',
              marginBottom: '6px'
            }}>
              👤 {t.username}
            </label>
            <input
              type="text"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              placeholder={t.usernamePlaceholder}
              disabled={loading}
              style={{
                width: '100%',
                padding: '12px 14px',
                borderRadius: '10px',
                background: isDark ? '#1e293b' : '#ffffff',
                border: isDark ? '1px solid #334155' : '1px solid #cbd5e1',
                color: isDark ? '#f8fafc' : '#0f172a',
                fontSize: '14px',
                outline: 'none',
                boxSizing: 'border-box'
              }}
            />
          </div>

          <div>
            <label style={{
              display: 'block',
              fontSize: '12px',
              fontWeight: 700,
              textTransform: 'uppercase',
              color: isDark ? '#cbd5e1' : '#475569',
              marginBottom: '6px'
            }}>
              🔒 {t.password}
            </label>
            <div style={{ position: 'relative' }}>
              <input
                type={showPassword ? 'text' : 'password'}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder={t.passwordPlaceholder}
                disabled={loading}
                style={{
                  width: '100%',
                  padding: '12px 42px 12px 14px',
                  borderRadius: '10px',
                  background: isDark ? '#1e293b' : '#ffffff',
                  border: isDark ? '1px solid #334155' : '1px solid #cbd5e1',
                  color: isDark ? '#f8fafc' : '#0f172a',
                  fontSize: '14px',
                  outline: 'none',
                  boxSizing: 'border-box'
                }}
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                style={{
                  position: 'absolute',
                  right: '12px',
                  top: '50%',
                  transform: 'translateY(-50%)',
                  background: 'none',
                  border: 'none',
                  cursor: 'pointer',
                  fontSize: '16px'
                }}
              >
                {showPassword ? '👁️‍🗨️' : '👁️'}
              </button>
            </div>
          </div>

          {/* Remember Me & Forgot Password */}
          <div style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            fontSize: '13px'
          }}>
            <label style={{ display: 'flex', alignItems: 'center', gap: '6px', color: isDark ? '#94a3b8' : '#64748b' }}>
              <input type="checkbox" style={{ accentColor: '#3b82f6' }} />
              {t.rememberMe}
            </label>
            <Link to="/forgot-password" style={{ color: '#3b82f6', textDecoration: 'none', fontWeight: 600 }}>
              {t.forgotPassword}
            </Link>
          </div>

          {/* Action Submit Button */}
          <button
            type="submit"
            disabled={loading}
            style={{
              padding: '14px',
              borderRadius: '12px',
              border: 'none',
              background: 'linear-gradient(135deg, #3b82f6 0%, #6366f1 100%)',
              color: 'white',
              fontSize: '15px',
              fontWeight: 700,
              cursor: loading ? 'not-allowed' : 'pointer',
              boxShadow: '0 4px 15px rgba(59, 130, 246, 0.4)',
              transition: 'all 0.2s ease',
              marginTop: '6px'
            }}
          >
            {loading ? 'Authenticating...' : t.signIn}
          </button>
        </form>

        {/* Footer */}
        <div style={{
          marginTop: '24px',
          paddingTop: '16px',
          borderTop: isDark ? '1px solid #334155' : '1px solid #e2e8f0',
          textAlign: 'center',
          fontSize: '13px',
          color: isDark ? '#94a3b8' : '#64748b'
        }}>
          {t.noAccount} <Link to="/register" style={{ color: '#3b82f6', fontWeight: 600, textDecoration: 'none' }}>{t.signUp}</Link>
        </div>
      </div>
    </div>
  );
};

