);

const Dashboard = ({ userRole = 'staff' }) => {
  const { user } = useAuth();
  const { language, theme } = useLanguage();
  const [stats, setStats] = useState({
    totalAssets: 0,
    totalUsers: 0,
    totalMaintenance: 0,
    pendingMaintenance: 0,
    totalDepartments: 0,
    totalValue: 0,
    assetByStatus: [],
    maintenanceByPriority: [],
    recentActivities: []
  });
  const [loading, setLoading] = useState(true);

  const isDark = theme === 'dark';
  const t = language === 'en' ? englishTranslations : amharicTranslations;

  useEffect(() => {
    fetchDashboardData();
  }, [userRole]);

  const fetchDashboardData = async () => {
    setLoading(true);
    try {
      // Build query params based on role
      const params = {};
      if (userRole === 'department_head' && user?.department) {
        params.department = user.department;
      }

      const [assetsRes, usersRes, maintRes, deptsRes] = await Promise.all([
        axios.get('/api/assets', { params: { ...params, limit: 500 } }),
        axios.get('/api/users'),
        axios.get('/api/maintenance', { params: { limit: 500 } }),
        axios.get('/api/departments')
      ]);

      const assets = assetsRes.data?.assets || [];
      const users = usersRes.data?.users || [];
      const maintenance = maintRes.data?.requests || [];
      const departments = deptsRes.data?.departments || [];

      const byStatus = assets.reduce((acc, a) => {
        acc[a.status] = (acc[a.status] || 0) + 1;
        return acc;
      }, {});

      const byPriority = maintenance.reduce((acc, m) => {
        acc[m.priority] = (acc[m.priority] || 0) + 1;
        return acc;
      }, {});

      const pending = maintenance.filter(m => m.status === 'Pending').length;
      const totalValue = assets.reduce((sum, a) => sum + (a.current_value || 0), 0);

      const activities = [
        ...assets.slice(0, 5).map(a => ({
          type: 'asset',
          title: `📦 ${a.name} - ${a.status}`,
          time: a.updated_at,
          icon: '📦'
        })),
        ...maintenance.slice(0, 5).map(m => ({
          type: 'maintenance',
          title: `🔧 ${m.title} - ${m.status}`,
          time: m.updated_at,
          icon: '🔧'
        }))
      ].sort((a, b) => new Date(b.time) - new Date(a.time)).slice(0, 10);

      setStats({
        totalAssets: assets.length,
        totalUsers: users.length,
        totalMaintenance: maintenance.length,
        pendingMaintenance: pending,
        totalDepartments: departments.length,
        totalValue: totalValue,
        assetByStatus: Object.entries(byStatus).map(([key, value]) => ({ label: key, value })),
        maintenanceByPriority: Object.entries(byPriority).map(([key, value]) => ({ label: key, value })),
