  currentValue: 'አሁን ያለው ዋጋ',
  depreciation: 'ውድመት'
};

export default Reports;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useLanguage } from '../../contexts/UiContext';
import { useAuth } from '../../contexts/AuthContext';
import { toast } from 'react-toastify';
import axios from 'axios';
import * as XLSX from 'xlsx';
import { getDepartmentLabel } from '../../utils/department';

const StoreAssets = () => {
  const { user } = useAuth();
  const { language, theme } = useLanguage();

  const [assets, setAssets] = useState([]);
  const [users, setUsers] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [issuedAssets, setIssuedAssets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('issue');

  // Issue form state
  const [issueForm, setIssueForm] = useState({
    assetId: '',
    userId: '',
    departmentId: '',
    expectedReturnDate: '',
    condition: 'Good',
    remarks: ''
  });

  // Return form state
  const [returnForm, setReturnForm] = useState({
    assignmentId: '',
    conditionAfter: 'Good',
    remarks: '',
    damaged: false,
    damageDescription: ''
  });

  // Transfer form state
  const [transferForm, setTransferForm] = useState({
    assignmentId: '',
    targetDepartment: '',
    targetUser: '',
    reason: '',
    remarks: ''
  });

  const [selectedAssignment, setSelectedAssignment] = useState(null);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [showReturnModal, setShowReturnModal] = useState(false);
  const [showTransferModal, setShowTransferModal] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);

  const isDark = theme === 'dark';
  const t = language === 'en' ? englishTranslations : amharicTranslations;

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const [assetsRes, usersRes, deptsRes, issuedRes] = await Promise.all([
        axios.get('/api/assets', { params: { limit: 500 } }),
        axios.get('/api/users', { params: { limit: 200 } }),
        axios.get('/api/departments'),
        axios.get('/api/assignments', { params: { status: 'active', limit: 200 } })
      ]);

      setAssets(assetsRes.data.assets || assetsRes.data.data || []);
      setUsers(usersRes.data.users || []);
      setDepartments(deptsRes.data.departments || []);
      setIssuedAssets(issuedRes.data.assignments || []);
    } catch (error) {
      toast.error(t.fetchError || 'Failed to load data');
      setAssets([]);
      setUsers([]);
      setDepartments([]);
      setIssuedAssets([]);
    }
    setLoading(false);
  };

  const handleIssue = async (e) => {
    e.preventDefault();
    if (!issueForm.assetId || !issueForm.userId) {
      toast.error(t.selectBoth || 'Please select both asset and user');
      return;
    }

    setIsProcessing(true);
    try {
      await axios.post('/api/assignments', {
        asset_id: issueForm.assetId,
        assigned_to: issueForm.userId,
        assigned_by: user?.id,
        notes: issueForm.remarks
      });

      toast.success(t.issueSuccess || 'Asset issued successfully');
      setIssueForm({
        assetId: '',
        userId: '',
        departmentId: '',
        expectedReturnDate: '',
        condition: 'Good',
        remarks: ''
      });
      await fetchData();
    } catch (error) {
      toast.error(t.issueError || 'Failed to issue asset');
    }
    setIsProcessing(false);
  };

  const handleReturn = async (e) => {
    e.preventDefault();
    if (!returnForm.assignmentId) {
      toast.error(t.selectAssignment || 'Please select an assignment');
      return;
    }

    setIsProcessing(true);
    try {
      await axios.post(`/api/assignments/${returnForm.assignmentId}/return`, {
        condition_at_return: returnForm.damaged ? 'Damaged' : returnForm.conditionAfter,
        returned_by: user?.id,
        notes: returnForm.remarks || returnForm.damageDescription
      });

      toast.success(t.returnSuccess || 'Asset returned successfully');
      setReturnForm({
        assignmentId: '',
        conditionAfter: 'Good',
        remarks: '',
        damaged: false,
        damageDescription: ''
      });
      setShowReturnModal(false);
      await fetchData();
    } catch (error) {
      toast.error(t.returnError || 'Failed to return asset');
    }
    setIsProcessing(false);
  };

  const handleTransfer = async (e) => {
    e.preventDefault();
    if (!transferForm.assignmentId || !transferForm.targetDepartment) {
      toast.error(t.selectTransferDetails || 'Please fill all transfer details');
      return;
    }

    setIsProcessing(true);
    try {
      await axios.post(`/api/assignments/${transferForm.assignmentId}/transfer`, {
        new_user_id: transferForm.targetUser || undefined,
        new_department_id: transferForm.targetDepartment || undefined,
        transferred_by: user?.id,
        notes: transferForm.reason || transferForm.remarks
      });

      toast.success(t.transferSuccess || 'Asset transferred successfully');
      setTransferForm({
        assignmentId: '',
        targetDepartment: '',
        targetUser: '',
        reason: '',
        remarks: ''
      });
      setShowTransferModal(false);
      await fetchData();
    } catch (error) {
      toast.error(t.transferError || 'Failed to transfer asset');
    }
    setIsProcessing(false);
  };

  const getAvailableAssets = useMemo(() => {
    return assets.filter(a => a.status === 'Available' || a.is_available);
  }, [assets]);

  const getActiveAssignments = useMemo(() => {
    return issuedAssets.filter(a => a.status === 'Active' || a.status === 'Overdue');
  }, [issuedAssets]);

  const getReturnableAssignments = useMemo(() => {
    return issuedAssets.filter(a => a.status === 'Active' || a.status === 'Overdue');
  }, [issuedAssets]);

  const getStatusColor = (status) => {
    const colors = {
      'Active': '#48bb78',
      'Overdue': '#fc8181',
      'Returned': '#4299e1',
      'Transferred': '#805ad5',
      'Available': '#48bb78',
      'Issued': '#4299e1',
      'Under Maintenance': '#ed8936',
      'Reserved': '#805ad5'
    };
    return colors[status] || '#a0aec0';
  };

  const getConditionColor = (condition) => {
    const colors = {
      'New': '#48bb78',
      'Good': '#4299e1',
      'Fair': '#f6ad55',
      'Poor': '#ed8936',
      'Damaged': '#fc8181'
    };
    return colors[condition] || '#a0aec0';
  };

  const exportToExcel = () => {
    const data = issuedAssets.map(a => ({
      'Assignment ID': a.assignment_id || '',
      'Asset Tag': a.asset_tag || '',
      'Asset Name': a.asset_name || '',
      'Issued To': a.user_name || '',
      'Department': a.department || '',
      'Issue Date': a.issue_date ? new Date(a.issue_date).toLocaleDateString() : '',
      'Expected Return': a.expected_return_date ? new Date(a.expected_return_date).toLocaleDateString() : '',
      'Actual Return': a.actual_return_date ? new Date(a.actual_return_date).toLocaleDateString() : '',
      'Status': a.status || '',
      'Condition Before': a.condition_before || '',
      'Condition After': a.condition_after || '',
      'Remarks': a.remarks || ''
    }));
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Asset Assignments');
    XLSX.writeFile(wb, 'store_assets.xlsx');
    toast.success(t.exportSuccess || 'Exported successfully');
  };

  const styles = {
    container: {
      padding: '20px',
      maxWidth: '1600px',
      margin: '0 auto',
      background: isDark ? '#0d1a2e' : '#f0f4f8',
      minHeight: '100vh'
    },
    header: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'flex-start',
      flexWrap: 'wrap',
      marginBottom: '24px'
    },
    title: {
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '1.75rem',
      fontWeight: 700,
      marginBottom: '4px'
    },
    subtitle: {
      color: isDark ? '#8896b0' : '#4a5568',
      fontSize: '0.95rem'
    },
    headerActions: {
      display: 'flex',
      gap: '10px',
      flexWrap: 'wrap',
      marginTop: '8px'
    },
    exportButton: {
      background: 'linear-gradient(135deg, #48bb78, #38a169)',
      color: 'white',
      padding: '8px 16px',
      borderRadius: '8px',
      border: 'none',
      fontWeight: 600,
      cursor: 'pointer',
      fontSize: '0.9rem'
    },
    tabs: {
      display: 'flex',
      gap: '4px',
      marginBottom: '24px',
      flexWrap: 'wrap',
      background: isDark ? '#1e2d45' : '#f7fafc',
      padding: '4px',
      borderRadius: '12px'
    },
    tab: {
      padding: '10px 20px',
      borderRadius: '8px',
      border: 'none',
      background: 'transparent',
      color: isDark ? '#8896b0' : '#4a5568',
      cursor: 'pointer',
      fontWeight: 600,
      fontSize: '0.9rem',
      transition: 'all 0.2s'
    },
    activeTab: {
      background: isDark ? '#2d4a6f' : '#ffffff',
      color: isDark ? '#c8dcf5' : '#1a365d',
      boxShadow: isDark ? '0 4px 12px rgba(0,0,0,0.3)' : '0 2px 8px rgba(0,0,100,0.08)'
    },
    card: {
      background: isDark ? '#1e2d45' : '#ffffff',
      padding: '24px',
      borderRadius: '12px',
      border: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      marginBottom: '24px'
    },
    formGrid: {
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
      gap: '16px'
    },
    formGroup: {
      display: 'flex',
      flexDirection: 'column'
    },
    label: {
      color: isDark ? '#8896b0' : '#4a5568',
      fontSize: '0.8rem',
      fontWeight: 600,
      marginBottom: '4px'
    },
    select: {
      padding: '8px 12px',
      borderRadius: '6px',
      border: `1px solid ${isDark ? '#32465f' : '#d0d8e8'}`,
      background: isDark ? '#141e2d' : '#ffffff',
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.9rem',
      outline: 'none',
      width: '100%'
    },
    input: {
      padding: '8px 12px',
      borderRadius: '6px',
      border: `1px solid ${isDark ? '#32465f' : '#d0d8e8'}`,
      background: isDark ? '#141e2d' : '#ffffff',
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.9rem',
      outline: 'none',
      width: '100%'
    },
    textarea: {
      padding: '8px 12px',
      borderRadius: '6px',
      border: `1px solid ${isDark ? '#32465f' : '#d0d8e8'}`,
      background: isDark ? '#141e2d' : '#ffffff',
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.9rem',
      outline: 'none',
      width: '100%',
      minHeight: '60px',
      resize: 'vertical'
    },
    button: {
      padding: '10px 24px',
      background: 'linear-gradient(135deg, #4299e1, #3182ce)',
      color: 'white',
      border: 'none',
      borderRadius: '8px',
      fontWeight: 600,
      cursor: 'pointer',
      fontSize: '0.9rem',
      width: '100%',
      marginTop: '24px'
    },
    buttonSuccess: {
      padding: '10px 24px',
      background: 'linear-gradient(135deg, #48bb78, #38a169)',
      color: 'white',
      border: 'none',
      borderRadius: '8px',
      fontWeight: 600,
      cursor: 'pointer',
      fontSize: '0.9rem',
      width: '100%',
      marginTop: '24px'
    },
    buttonDanger: {
      padding: '10px 24px',
      background: 'linear-gradient(135deg, #fc8181, #e53e3e)',
      color: 'white',
      border: 'none',
      borderRadius: '8px',
      fontWeight: 600,
      cursor: 'pointer',
      fontSize: '0.9rem',
      width: '100%',
      marginTop: '24px'
    },
    table: {
      width: '100%',
      borderCollapse: 'collapse',
      background: isDark ? '#1e2d45' : '#ffffff',
      borderRadius: '12px',
      overflow: 'hidden',
      boxShadow: isDark ? '0 4px 12px rgba(0,0,0,0.3)' : '0 4px 12px rgba(0,0,100,0.06)'
    },
    th: {
      padding: '10px 14px',
      textAlign: 'left',
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontWeight: 600,
      borderBottom: `2px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      background: isDark ? '#141e2d' : '#f7fafc',
      fontSize: '0.75rem',
      textTransform: 'uppercase',
      letterSpacing: '0.5px',
      whiteSpace: 'nowrap'
    },
    td: {
      padding: '10px 14px',
      borderBottom: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '0.85rem'
    },
    statusBadge: (status) => ({
      display: 'inline-block',
      padding: '2px 10px',
      borderRadius: '12px',
      fontSize: '0.75rem',
      fontWeight: 600,
      background: getStatusColor(status) + '22',
      color: getStatusColor(status)
    }),
    emptyState: {
      textAlign: 'center',
      padding: '40px',
      color: isDark ? '#8896b0' : '#4a5568'
    },
    assetGrid: {
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))',
      gap: '16px'
    },
    assetCard: {
      background: isDark ? '#1e2d45' : '#ffffff',
      padding: '16px',
      borderRadius: '12px',
      border: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`,
      textAlign: 'center'
    },
    // Modal styles
    modal: {
      position: 'fixed',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      background: 'rgba(0,0,0,0.7)',
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      zIndex: 1000,
      padding: '20px',
      backdropFilter: 'blur(4px)'
    },
    modalContent: {
      background: isDark ? '#1e2d45' : '#ffffff',
      borderRadius: '16px',
      padding: '28px',
      maxWidth: '600px',
      width: '100%',
      maxHeight: '85vh',
      overflow: 'auto',
      border: `1px solid ${isDark ? '#32465f' : '#e8edf5'}`
    },
    modalHeader: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      marginBottom: '20px'
    },
    modalTitle: {
      color: isDark ? '#c8dcf5' : '#1a365d',
      fontSize: '1.3rem',
      fontWeight: 700
    },
    modalClose: {
      background: 'none',
      border: 'none',
      fontSize: '1.5rem',
      color: isDark ? '#8896b0' : '#4a5568',
      cursor: 'pointer',
      padding: '4px 8px',
      borderRadius: '4px'
    },
    checkbox: {
      display: 'flex',
      alignItems: 'center',
      gap: '8px',
      color: isDark ? '#c8dcf5' : '#1a365d',
      cursor: 'pointer'
    },
    actionButtons: {
      display: 'flex',
      gap: '8px',
      flexWrap: 'wrap'
    },
    actionButton: (color) => ({
      padding: '4px 12px',
      borderRadius: '4px',
      border: 'none',
      background: color || '#4299e1',
      color: 'white',
      cursor: 'pointer',
      fontSize: '0.8rem'
    })
  };

  if (loading) {
    return (
      <div style={styles.container}>
        <div style={styles.emptyState}>
          <div style={{ fontSize: '2rem', marginBottom: '12px' }}>⏳</div>
          <div>{t.loading}</div>
        </div>
      </div>
    );
  }

  const tabs = [
    { id: 'issue', label: '📤 ' + t.issueAsset },
    { id: 'return', label: '📥 ' + t.returnAsset },
    { id: 'transfer', label: '🔄 ' + t.transferAsset },
    { id: 'history', label: '📋 ' + t.assignmentHistory }
  ];

  return (
    <div style={styles.container}>
      {/* Header */}
      <div style={styles.header}>
        <div>
          <h1 style={styles.title}>📋 {t.assets}</h1>
          <p style={styles.subtitle}>
            {t.issueDesc}
            <span style={{ marginLeft: '12px', fontSize: '0.85rem', color: isDark ? '#8896b0' : '#4a5568' }}>
              {getAvailableAssets.length} {t.available} • {getActiveAssignments.length} {t.issued}
            </span>
          </p>
        </div>
        <div style={styles.headerActions}>
          <button style={styles.exportButton} onClick={exportToExcel}>
            📥 {t.exportExcel}
          </button>
        </div>
      </div>

      {/* Tabs */}
      <div style={styles.tabs}>
        {tabs.map(tab => (
          <button
            key={tab.id}
            style={{
              ...styles.tab,
              ...(activeTab === tab.id ? styles.activeTab : {})
            }}
            onClick={() => setActiveTab(tab.id)}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* Issue Tab */}
      {activeTab === 'issue' && (
        <div style={styles.card}>
          <h3 style={{ color: isDark ? '#c8dcf5' : '#1a365d', marginBottom: '16px' }}>
            {t.issueAsset}
          </h3>
          <form onSubmit={handleIssue}>
            <div style={styles.formGrid}>
              <div style={styles.formGroup}>
                <label style={styles.label}>{t.selectAsset} *</label>
                <select
                  style={styles.select}
                  value={issueForm.assetId}
                  onChange={(e) => setIssueForm({ ...issueForm, assetId: e.target.value })}
                  required
                >
                  <option value="">{t.selectAsset}</option>
                  {getAvailableAssets.map(a => (
                    <option key={a.id} value={a.id}>
                      {a.asset_tag} - {a.name} ({a.location})
                    </option>
                  ))}
                </select>
              </div>
              <div style={styles.formGroup}>
                <label style={styles.label}>{t.selectUser} *</label>
                <select
                  style={styles.select}
                  value={issueForm.userId}
                  onChange={(e) => setIssueForm({ ...issueForm, userId: e.target.value })}
                  required
                >
                  <option value="">{t.selectUser}</option>
                  {users.map(u => (
                    <option key={u.id} value={u.id}>
                      {u.full_name || u.username} ({getDepartmentLabel(u.department) || 'No dept'})
                    </option>
                  ))}
                </select>
              </div>
              <div style={styles.formGroup}>
                <label style={styles.label}>{t.department}</label>
                <select
                  style={styles.select}
                  value={issueForm.departmentId}
                  onChange={(e) => setIssueForm({ ...issueForm, departmentId: e.target.value })}
                >
                  <option value="">{t.selectDepartment}</option>
                  {departments.map(d => (
                    <option key={d.id} value={d.id}>{getDepartmentLabel(d)}</option>
                  ))}
                </select>
              </div>
              <div style={styles.formGroup}>
                <label style={styles.label}>{t.expectedReturnDate}</label>
                <input
                  type="date"
                  style={styles.input}
                  value={issueForm.expectedReturnDate}
                  onChange={(e) => setIssueForm({ ...issueForm, expectedReturnDate: e.target.value })}
                />
              </div>
              <div style={styles.formGroup}>
                <label style={styles.label}>{t.condition}</label>
                <select
                  style={styles.select}
                  value={issueForm.condition}
                  onChange={(e) => setIssueForm({ ...issueForm, condition: e.target.value })}
                >
                  <option value="New">New</option>
                  <option value="Good">Good</option>
                  <option value="Fair">Fair</option>
                  <option value="Poor">Poor</option>
                </select>
              </div>
              <div style={styles.formGroup}>
                <label style={styles.label}>{t.remarks}</label>
                <input
                  type="text"
                  style={styles.input}
                  placeholder={t.remarksPlaceholder}
                  value={issueForm.remarks}
                  onChange={(e) => setIssueForm({ ...issueForm, remarks: e.target.value })}
                />
              </div>
            </div>
            <button type="submit" style={styles.buttonSuccess} disabled={isProcessing}>
              {isProcessing ? t.processing : t.issue}
            </button>
          </form>
        </div>
      )}

      {/* Return Tab */}
      {activeTab === 'return' && (
        <div style={styles.card}>
          <h3 style={{ color: isDark ? '#c8dcf5' : '#1a365d', marginBottom: '16px' }}>
            {t.returnAsset}
          </h3>
          <form onSubmit={handleReturn}>
            <div style={styles.formGrid}>
              <div style={styles.formGroup}>
                <label style={styles.label}>{t.selectAssignment} *</label>
                <select
                  style={styles.select}
                  value={returnForm.assignmentId}
                  onChange={(e) => setReturnForm({ ...returnForm, assignmentId: e.target.value })}
                  required
                >
                  <option value="">{t.selectAssignment}</option>
                  {getReturnableAssignments.map(a => (
                    <option key={a.id} value={a.id}>
                      {a.asset_tag} - {a.asset_name} → {a.user_name} ({getDepartmentLabel(a.department)})
                      {a.is_overdue && ' 🔴'}
                    </option>
                  ))}
                </select>
              </div>
              <div style={styles.formGroup}>
                <label style={styles.label}>{t.conditionAfter} *</label>
                <select
                  style={styles.select}
                  value={returnForm.conditionAfter}
                  onChange={(e) => setReturnForm({ ...returnForm, conditionAfter: e.target.value })}
                  required
                >
                  <option value="New">New</option>
                  <option value="Good">Good</option>
                  <option value="Fair">Fair</option>
                  <option value="Poor">Poor</option>
                  <option value="Damaged">Damaged</option>
                </select>
              </div>
              <div style={styles.formGroup}>
                <label style={styles.label}>{t.remarks}</label>
                <input
                  type="text"
                  style={styles.input}
                  placeholder={t.returnRemarksPlaceholder}
                  value={returnForm.remarks}
                  onChange={(e) => setReturnForm({ ...returnForm, remarks: e.target.value })}
                />
              </div>
              <div style={styles.formGroup}>
                <label style={styles.checkbox}>
                  <input
                    type="checkbox"
                    checked={returnForm.damaged}
                    onChange={(e) => setReturnForm({ ...returnForm, damaged: e.target.checked })}
                  />
                  {t.reportDamaged}
                </label>
                {returnForm.damaged && (
                  <input
                    type="text"
                    style={{ ...styles.input, marginTop: '8px' }}
                    placeholder={t.damageDescriptionPlaceholder}
                    value={returnForm.damageDescription}
                    onChange={(e) => setReturnForm({ ...returnForm, damageDescription: e.target.value })}
                  />
                )}
              </div>
            </div>
            <button type="submit" style={styles.buttonSuccess} disabled={isProcessing}>
              {isProcessing ? t.processing : t.return}
            </button>
          </form>
        </div>
      )}

      {/* Transfer Tab */}
      {activeTab === 'transfer' && (
        <div style={styles.card}>
          <h3 style={{ color: isDark ? '#c8dcf5' : '#1a365d', marginBottom: '16px' }}>
            {t.transferAsset}
          </h3>
          <form onSubmit={handleTransfer}>
            <div style={styles.formGrid}>
              <div style={styles.formGroup}>
                <label style={styles.label}>{t.selectAssignment} *</label>
                <select
                  style={styles.select}
                  value={transferForm.assignmentId}
                  onChange={(e) => setTransferForm({ ...transferForm, assignmentId: e.target.value })}
                  required
                >
                  <option value="">{t.selectAssignment}</option>
                  {getActiveAssignments.map(a => (
                    <option key={a.id} value={a.id}>
                      {a.asset_tag} - {a.asset_name} → {a.user_name}
                    </option>
                  ))}
                </select>
              </div>
              <div style={styles.formGroup}>
                <label style={styles.label}>{t.targetDepartment} *</label>
                <select
                  style={styles.select}
                  value={transferForm.targetDepartment}
                  onChange={(e) => setTransferForm({ ...transferForm, targetDepartment: e.target.value })}
                  required
                >
                  <option value="">{t.selectDepartment}</option>
                  {departments.map(d => (
                    <option key={d.id} value={d.id}>{getDepartmentLabel(d)}</option>
                  ))}
                </select>
              </div>
              <div style={styles.formGroup}>
                <label style={styles.label}>{t.targetUser}</label>
                <select
                  style={styles.select}
                  value={transferForm.targetUser}
                  onChange={(e) => setTransferForm({ ...transferForm, targetUser: e.target.value })}
                >
                  <option value="">{t.selectUser}</option>
                  {users.map(u => (
                    <option key={u.id} value={u.id}>
                      {u.full_name || u.username}
                    </option>
                  ))}
                </select>
              </div>
              <div style={styles.formGroup}>
                <label style={styles.label}>{t.reason}</label>
                <input
                  type="text"
                  style={styles.input}
                  placeholder={t.transferReasonPlaceholder}
                  value={transferForm.reason}
                  onChange={(e) => setTransferForm({ ...transferForm, reason: e.target.value })}
                />
              </div>
              <div style={styles.formGroup}>
                <label style={styles.label}>{t.remarks}</label>
                <input
                  type="text"
                  style={styles.input}
                  placeholder={t.transferRemarksPlaceholder}
                  value={transferForm.remarks}
                  onChange={(e) => setTransferForm({ ...transferForm, remarks: e.target.value })}
                />
              </div>
            </div>
            <button type="submit" style={styles.button} disabled={isProcessing}>
              {isProcessing ? t.processing : t.transfer}
            </button>
          </form>
        </div>
      )}

      {/* History Tab */}
      {activeTab === 'history' && (
        <div style={styles.card}>
          <h3 style={{ color: isDark ? '#c8dcf5' : '#1a365d', marginBottom: '16px' }}>
            {t.assignmentHistory}
          </h3>
          <div style={{ overflowX: 'auto' }}>
            <table style={styles.table}>
              <thead>
                <tr>
                  <th style={styles.th}>{t.assignmentId}</th>
                  <th style={styles.th}>{t.asset}</th>
                  <th style={styles.th}>{t.issuedTo}</th>
                  <th style={styles.th}>{t.department}</th>
                  <th style={styles.th}>{t.issueDate}</th>
                  <th style={styles.th}>{t.expectedReturn}</th>
                  <th style={styles.th}>{t.status}</th>
                  <th style={styles.th}>{t.actions}</th>
                </tr>
              </thead>
              <tbody>
                {issuedAssets.length === 0 ? (
                  <tr>
                    <td colSpan="8" style={{ ...styles.td, textAlign: 'center', padding: '30px' }}>
                      {t.noAssignments}
                    </td>
                  </tr>
                ) : (
                  issuedAssets.map(assignment => (
                    <tr key={assignment.id}>
                      <td style={styles.td}>
                        <span style={{
                          display: 'inline-block',
                          padding: '2px 8px',
                          background: isDark ? '#2d4a6f' : '#e8edf5',
                          borderRadius: '4px',
                          fontSize: '0.75rem',
                          fontWeight: 600,
                          color: isDark ? '#c8dcf5' : '#1a365d'
                        }}>
                          {assignment.assignment_id}
                        </span>
                      </td>
                      <td style={styles.td}>
                        <div>{assignment.asset_name}</div>
                        <div style={{ fontSize: '0.7rem', color: isDark ? '#8896b0' : '#4a5568' }}>
                          {assignment.asset_tag}
                        </div>
                      </td>
                      <td style={styles.td}>{assignment.user_name}</td>
                      <td style={styles.td}>{getDepartmentLabel(assignment.department) || '-'}</td>
                      <td style={styles.td}>
                        {assignment.issue_date ? new Date(assignment.issue_date).toLocaleDateString() : '-'}
                      </td>
                      <td style={styles.td}>
                        {assignment.expected_return_date ? new Date(assignment.expected_return_date).toLocaleDateString() : '-'}
                        {assignment.is_overdue && (
                          <span style={{ marginLeft: '4px', color: '#fc8181' }}>🔴</span>
                        )}
                      </td>
                      <td style={styles.td}>
                        <span style={styles.statusBadge(assignment.status)}>
                          {assignment.status}
                        </span>
                      </td>
                      <td style={styles.td}>
                        <div style={styles.actionButtons}>
                          {assignment.status === 'Active' && (
                            <>
                              <button
                                style={styles.actionButton('#48bb78')}
                                onClick={() => {
                                  setReturnForm({ ...returnForm, assignmentId: assignment.id });
                                  setActiveTab('return');
                                }}
                              >
                                {t.return}
                              </button>
                              <button
                                style={styles.actionButton('#805ad5')}
                                onClick={() => {
                                  setTransferForm({ ...transferForm, assignmentId: assignment.id });
                                  setActiveTab('transfer');
                                }}
                              >
                                {t.transfer}
                              </button>
                            </>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

