import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useLanguage } from '../../contexts/UiContext';
import { Chart as ChartJS, CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend, ArcElement, PointElement, LineElement, Filler } from 'chart.js';
import { Bar, Doughnut, Line, Pie } from 'react-chartjs-2';
import { toast } from 'react-toastify';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';

ChartJS.register(
  CategoryScale, 
  LinearScale, 
  BarElement, 
  Title, 
  Tooltip, 
  Legend, 
  ArcElement,
  PointElement,
  LineElement,
  Filler
);

const StoreDashboard = () => {
  const { user } = useAuth();
  const { language, theme } = useLanguage();
  const navigate = useNavigate();

  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({
    totalInventory: 0,
    available: 0,
    issued: 0,
    reserved: 0,
    returned: 0,
    damaged: 0,
    lowStock: 0,
    pendingRequests: 0,
    totalValue: 0,
    byCategory: {},
    byStatus: {},
    recentTransactions: [],
    lowStockItems: [],
    pendingRequestsList: [],
    damagedItems: [],
    inventoryMovement: []
  });

  const [timeRange, setTimeRange] = useState('week');

  const isDark = theme === 'dark';
  const t = language === 'en' ? englishTranslations : amharicTranslations;

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    setLoading(true);
    try {
      // Fetch all assets/inventory items
      const assetsRes = await axios.get('/api/assets', { params: { limit: 1000 }, timeout: 8000 });
      const assets = assetsRes.data?.assets || assetsRes.data?.data || [];

      // Fetch maintenance/requests
      const maintRes = await axios.get('/api/maintenance', { params: { limit: 500, status: 'Pending' }, timeout: 8000 });
      const maintenance = maintRes.data?.requests || [];

      // Fetch transactions
      const transRes = await axios.get('/api/transactions', { params: { limit: 50 }, timeout: 8000 });
      const transactions = transRes.data?.transactions || [];

      calculateStats(assets, maintenance, transactions);
    } catch (error) {
      toast.error(t.fetchError || 'Failed to load dashboard data');
      calculateStats([], [], []);
    } finally {
      setLoading(false);
    }
  };

  const generateFallbackInventory = () => {
    const categories = ['Hardware', 'Software', 'Vehicles', 'Furniture', 'Machinery', 'Electronics', 'Consumables'];
    const statuses = ['Available', 'Issued', 'Reserved', 'Returned', 'Damaged', 'Under Repair'];
    const locations = ['Main Store', 'Warehouse A', 'Warehouse B', 'Data Center', 'Office'];

    return Array.from({ length: 1250 }, (_, i) => {
      const status = statuses[i % statuses.length];
      const isLowStock = i % 50 === 0 && status === 'Available';
      return {
        id: `item_${i + 1}`,
        asset_tag: `STK-${String(i + 1).padStart(6, '0')}`,
        name: `${categories[i % categories.length]} ${i + 1}`,
        category: categories[i % categories.length],
        status: status,
        location: locations[i % locations.length],
        quantity: isLowStock ? Math.floor(Math.random() * 5) + 1 : Math.floor(Math.random() * 50) + 10,
        min_stock: 5,
        current_value: Math.round(1000 + Math.random() * 50000),
        purchase_date: new Date(2019 + Math.floor(Math.random() * 5), Math.floor(Math.random() * 12), Math.floor(Math.random() * 28)).toISOString(),
        condition: ['Good', 'Fair', 'Poor', 'Damaged'][i % 4],
        is_low_stock: isLowStock || (i % 25 === 0 && status === 'Available'),
        assigned_to: status === 'Issued' ? `User ${(i % 20) + 1}` : null,
        transaction_date: new Date(Date.now() - Math.random() * 30 * 24 * 3600000).toISOString()
      };
    });
  };

  const generateFallbackTransactions = () => {
    const types = ['Issue', 'Return', 'Receipt', 'Reservation', 'Cancellation'];
    const users = ['Abebe K.', 'Almaz T.', 'Dawit S.', 'Eden E.', 'Fikru H.'];

    return Array.from({ length: 30 }, (_, i) => ({
      id: `trans_${i + 1}`,
      transaction_id: `TRX-${String(i + 1).padStart(6, '0')}`,
      type: types[i % types.length],
      item_name: `Item ${i + 1}`,
      item_tag: `STK-${String(i + 1).padStart(6, '0')}`,
      quantity: Math.floor(Math.random() * 10) + 1,
      user: users[i % users.length],
      department: ['Finance', 'IT', 'HR', 'Operations', 'Marketing'][i % 5],
      status: ['Completed', 'Pending', 'Cancelled'][i % 3],
      date: new Date(Date.now() - (i + 1) * 12 * 3600000).toISOString(),
      notes: `Transaction ${i + 1}`
    }));
  };

  const calculateStats = (assets, maintenance, transactions) => {
    const totalInventory = assets.length;
    const available = assets.filter(a => a.status === 'Available').length;
    const issued = assets.filter(a => a.status === 'Issued').length;
    const reserved = assets.filter(a => a.status === 'Reserved').length;
    const returned = assets.filter(a => a.status === 'Returned').length;
    const damaged = assets.filter(a => a.status === 'Damaged' || a.condition === 'Damaged' || a.condition === 'Poor').length;
    const lowStock = assets.filter(a => a.is_low_stock || (a.quantity <= a.min_stock)).length;
    const pendingRequests = maintenance.filter(m => m.status === 'Pending').length;
    const totalValue = assets.reduce((sum, a) => sum + (a.current_value || 0), 0);

    const byCategory = assets.reduce((acc, a) => {
      const cat = a.category || a.category_name || 'Other';
      acc[cat] = (acc[cat] || 0) + 1;
      return acc;
    }, {});

    const byStatus = assets.reduce((acc, a) => {
      const status = a.status || 'Unknown';
      acc[status] = (acc[status] || 0) + 1;
      return acc;
    }, {});

    // Inventory movement (last 7 days)
    const movement = Array.from({ length: 7 }, (_, i) => {
      const date = new Date();
      date.setDate(date.getDate() - (6 - i));
      const dayTransactions = transactions.filter(t => 
        new Date(t.date).toDateString() === date.toDateString()
      );
      return {
        date: date.toLocaleDateString('en', { weekday: 'short' }),
        issued: dayTransactions.filter(t => t.type === 'Issue').length,
        returned: dayTransactions.filter(t => t.type === 'Return').length,
        received: dayTransactions.filter(t => t.type === 'Receipt').length
      };
    });

    setStats({
      totalInventory,
      available,
      issued,
      reserved,
      returned,
      damaged,
      lowStock,
      pendingRequests,
      totalValue,
      byCategory,
      byStatus,
      recentTransactions: transactions.slice(0, 10),
      lowStockItems: assets.filter(a => a.is_low_stock || (a.quantity <= a.min_stock)).slice(0, 10),
      pendingRequestsList: maintenance.filter(m => m.status === 'Pending').slice(0, 10),
      damagedItems: assets.filter(a => a.status === 'Damaged' || a.condition === 'Damaged' || a.condition === 'Poor').slice(0, 10),
      inventoryMovement: movement
    });
  };

  const handleStatClick = (type, filter = {}) => {
    const routes = {
      'available': '/store/inventory?status=Available',
      'issued': '/store/inventory?status=Issued',
      'reserved': '/store/inventory?status=Reserved',
      'returned': '/store/returns',
      'damaged': '/store/inventory?status=Damaged',
      'lowStock': '/store/inventory?status=low-stock',
      'pendingRequests': '/store/notifications',
      'totalInventory': '/store/inventory'
    };

    const route = routes[type];
    if (route) {
      navigate(route);
    }
  };

  const getStatusColor = (status) => {
    const colors = {
      'Available': '#48bb78',
      'Issued': '#4299e1',
      'Reserved': '#805ad5',
      'Returned': '#38a169',
      'Damaged': '#fc8181',
      'Under Repair': '#ed8936',
      'Pending': '#f6ad55',
      'Completed': '#48bb78',
      'Cancelled': '#a0aec0'
    };
    return colors[status] || '#a0aec0';
  };

  const chartColors = {
    primary: isDark ? '#63b3ed' : '#2b6cb0',
    success: isDark ? '#68d391' : '#48bb78',
    warning: isDark ? '#f6ad55' : '#ed8936',
    danger: isDark ? '#fc8181' : '#e53e3e',
    purple: isDark ? '#b794f4' : '#805ad5',
    teal: isDark ? '#81e6d9' : '#319795'
  };

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'bottom',
        labels: {
          color: isDark ? '#c8dcf5' : '#1a365d',
          boxWidth: 12,
          padding: 15
        }
      }
    },
    scales: {
      y: {
        ticks: { 
          color: isDark ? '#8896b0' : '#4a5568'
        },
        grid: { color: isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.05)' }
      },
      x: {
        ticks: { color: isDark ? '#8896b0' : '#4a5568' },
        grid: { color: isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.05)' }
      }
    }
  };

  const statusChartData = {
    labels: ['Available', 'Issued', 'Reserved', 'Returned', 'Damaged', 'Under Repair'],
    datasets: [{
      label: 'Inventory Status',
      data: [
        stats.available, 
        stats.issued, 
        stats.reserved, 
        stats.returned, 
        stats.damaged,
        stats.byStatus?.['Under Repair'] || 0
      ],
      backgroundColor: ['#48bb78', '#4299e1', '#805ad5', '#38a169', '#fc8181', '#ed8936'],
      borderColor: isDark ? '#1e2d45' : '#ffffff',
      borderWidth: 2
    }]
  };

  const categoryChartData = {
    labels: Object.keys(stats.byCategory || {}),
    datasets: [{
      label: 'Inventory by Category',
      data: Object.values(stats.byCategory || {}),
