  useEffect(() => {
    fetchInventory();
  }, [filterStatus, filterCategory, filterLocation]);

  const fetchInventory = async () => {
    setLoading(true);
    try {
      const params = { 
        limit: 500,
        ...(filterStatus && { status: filterStatus }),
        ...(filterCategory && { category: filterCategory }),
        ...(filterLocation && { location: filterLocation })
      };
      const response = await axios.get('/api/inventory', { params });
      const data = response.data.inventory || [];
      setAssets(data);
    } catch (error) {
      toast.error(t.fetchError || 'Failed to load inventory');
      setAssets([]);
    }
    setLoading(false);
  };

  const generateFallbackInventory = () => {
    const categories = ['Hardware', 'Software', 'Vehicles', 'Furniture', 'Machinery', 'Electronics', 'Consumables'];
    const statuses = ['Available', 'Reserved', 'Issued', 'Returned', 'Damaged', 'Under Inspection', 'Disposed'];
    const locations = ['Main Store', 'Warehouse A', 'Warehouse B', 'Data Center', 'Office'];
    const suppliers = ['ABC Supplies', 'XYZ Corp', 'Mega Store', 'Tech Distributors', 'Office Mart'];

    return Array.from({ length: 80 }, (_, i) => {
      const status = statuses[i % statuses.length];
      const qty = 5 + Math.floor(Math.random() * 45);
      const issued = status === 'Issued' ? Math.floor(qty * 0.6) : 0;
      const available = qty - issued - (status === 'Damaged' ? Math.floor(qty * 0.1) : 0);
      const isLowStock = available <= 5 && status !== 'Disposed';

      return {
        id: `inv_${i + 1}`,
        item_id: `ITEM-${String(i + 1).padStart(6, '0')}`,
        asset_id: `AST-${String(i + 1).padStart(6, '0')}`,
        name: `${categories[i % categories.length]} ${i + 1}`,
        category: categories[i % categories.length],
        serial_number: `SN-${String(i + 1).padStart(8, '0')}`,
        quantity: qty,
        available_quantity: available,
        issued_quantity: issued,
        reserved_quantity: status === 'Reserved' ? Math.floor(qty * 0.3) : 0,
        damaged_quantity: status === 'Damaged' ? Math.floor(qty * 0.1) : 0,
        location: locations[i % locations.length],
        condition: ['New', 'Good', 'Fair', 'Poor', 'Damaged'][i % 5],
        status: status,
        stock_status: isLowStock ? 'Low Stock' : status === 'Damaged' ? 'Damaged' : status === 'Disposed' ? 'Disposed' : 'Normal',
        date_received: new Date(2023 + Math.floor(Math.random() * 2), Math.floor(Math.random() * 12), Math.floor(Math.random() * 28)).toISOString(),
        supplier: suppliers[i % suppliers.length],
        current_value: 1000 + Math.random() * 50000,
        purchase_cost: 1200 + Math.random() * 60000,
        is_low_stock: isLowStock,
        min_stock: 5,
        max_stock: 50,
        last_updated: new Date(Date.now() - Math.random() * 30 * 24 * 3600000).toISOString()
      };
    });
  };

  const generateMovementHistory = (item) => {
    const types = ['Received', 'Issued', 'Returned', 'Damaged', 'Transferred', 'Adjusted'];
    const users = ['Abebe K.', 'Almaz T.', 'Dawit S.', 'Eden E.', 'Fikru H.'];

    return Array.from({ length: 8 }, (_, i) => ({
      id: `mov_${i}`,
      type: types[i % types.length],
      quantity: Math.floor(Math.random() * 5) + 1,
      from_location: ['Main Store', 'Warehouse A', 'Office'][i % 3],
      to_location: ['Warehouse B', 'Data Center', 'Main Store'][i % 3],
      reason: `${types[i % types.length]} reason ${i + 1}`,
      user: users[i % users.length],
      date: new Date(Date.now() - (i + 1) * 5 * 24 * 3600000).toISOString(),
