import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { toast } from 'react-toastify';

const StoreReceive = () => {
  const [inventory, setInventory] = useState([]);
  const [form, setForm] = useState({
    assetId: '',
    quantity: 1,
    reason: 'Stock received',
    location: 'Main Store'
  });
  const [loading, setLoading] = useState(true);

  const fetchInventory = async () => {
    try {
      const response = await axios.get('/api/inventory');
      const data = response.data?.inventory || [];
      setInventory(data);
      if (!form.assetId && data.length > 0) {
        setForm((prev) => ({ ...prev, assetId: data[0].asset_id || data[0].assetId || '' }));
      }
    } catch (error) {
      toast.error('Unable to load inventory');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchInventory();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.assetId || Number(form.quantity) <= 0) {
      toast.error('Select an asset and enter a valid quantity');
      return;
    }

    try {
      await axios.post(`/api/inventory/${form.assetId}/movement`, {
        type: 'receive',
        quantity: Number(form.quantity),
        reason: form.reason,
        to_location: form.location,
        notes: 'Received into store'
      });
      toast.success('Stock received successfully');
      setForm((prev) => ({ ...prev, quantity: 1, reason: 'Stock received', location: 'Main Store' }));
      fetchInventory();
    } catch (error) {
      toast.error('Failed to record receive transaction');
    }
  };

  return (
    <div style={{ padding: 24, maxWidth: 1100, margin: '0 auto' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
        <div>
          <h2 style={{ margin: 0, fontSize: '2rem' }}>📥 Receive Assets</h2>
          <p style={{ margin: '8px 0 0', color: '#64748b' }}>Track incoming items and update stock levels.</p>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1.2fr 0.8fr', gap: 20 }}>
        <div style={{ background: '#fff', borderRadius: 12, padding: 20, boxShadow: '0 2px 12px rgba(0,0,0,0.06)' }}>
          <h3 style={{ marginTop: 0 }}>Receive form</h3>
          <form onSubmit={handleSubmit} style={{ display: 'grid', gap: 14 }}>
            <label>
              Asset
              <select value={form.assetId} onChange={(e) => setForm({ ...form, assetId: e.target.value })} style={styles.input}>
                <option value="">Select an asset</option>
                {inventory.map((item) => (
                  <option key={item.asset_id || item.id} value={item.asset_id || item.id}>
                    {item.name || item.asset_tag || item.assetCode || `Inventory ${item.id}`}
                  </option>
                ))}
              </select>
            </label>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14 }}>
              <label>
                Quantity
                <input type="number" min="1" value={form.quantity} onChange={(e) => setForm({ ...form, quantity: e.target.value })} style={styles.input} />
              </label>
              <label>
                Location
                <input value={form.location} onChange={(e) => setForm({ ...form, location: e.target.value })} style={styles.input} />
              </label>
            </div>

            <label>
              Reason
              <input value={form.reason} onChange={(e) => setForm({ ...form, reason: e.target.value })} style={styles.input} />
            </label>

            <button type="submit" style={styles.primaryButton}>Save receive entry</button>
          </form>
        </div>

        <div style={{ background: '#fff', borderRadius: 12, padding: 20, boxShadow: '0 2px 12px rgba(0,0,0,0.06)' }}>
          <h3 style={{ marginTop: 0 }}>Quick stock overview</h3>
          {loading ? (
            <p>Loading inventory...</p>
          ) : (
            <div style={{ display: 'grid', gap: 12 }}>
              {inventory.slice(0, 6).map((item) => (
                <div key={item.asset_id || item.id} style={{ border: '1px solid #e2e8f0', borderRadius: 10, padding: 12 }}>
                  <div style={{ fontWeight: 700 }}>{item.name || 'Unnamed Asset'}</div>
                  <div style={{ color: '#64748b', fontSize: 14 }}>
                    Available: {item.available_quantity ?? item.availableQuantity ?? 0}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const styles = {
  input: {
    display: 'block',
    width: '100%',
    marginTop: 6,
    padding: '10px 12px',
