    boxSizing: 'border-box'
  },
  primaryButton: {
    padding: '12px 16px',
    border: 'none',
    borderRadius: 8,
    background: '#2563eb',
    color: '#fff',
    fontWeight: 700,
    cursor: 'pointer'
  }
};

