    let tableData = [];
    let headers = [];

    if (activeTab === 'inventory') {
      headers = ['Asset Tag', 'Name', 'Category', 'Status', 'Location', 'Condition', 'Value'];
      tableData = getFilteredAssets.slice(0, 50).map(a => [
