        e.name || '',
        e.department || '',
        e.assigned || 0,
        e.returned || 0,
        e.outstanding || 0
      ]);
    }

    if (tableData.length > 0) {
      doc.autoTable({
        head: [headers],
        body: tableData,
        startY: 42,
        theme: isDark ? 'dark' : 'grid',
        styles: { fontSize: 7 },
